  const fatwaIssuer= (body?.fatwaIssuer || '').toString().trim().slice(0, 200) || null;
  const fatwaUrl   = (body?.fatwaUrl || '').toString().trim().slice(0, 500) || null;
  const bodyText   = (body?.body || '').toString().slice(0, 200_000);
