// ─── Investor feedback (NPS + free text) ─────────────────────────
R('POST', '/app/feedback', async (req, res) => {
  const body = await readJson(req);
  const score = Number(body?.score);
  const comment = (body?.comment || '').toString().trim().slice(0, 2000);
  const category = (body?.category || 'general').toString().slice(0, 40);
  if (!Number.isFinite(score) || score < 0 || score > 10) return err(res, 400, 'invalid_input');
  const user = S.currentUser(req);
  await db.insert('feedback', {
    id: S.newId('fb_'),
    userId: user?.id || null,
    name: user?.name || (body?.name || '').toString().slice(0, 120) || null,
    email: user?.email || (body?.email || '').toString().slice(0, 254) || null,
    score, comment, category,
    ip: clientIp(req),
    ua: (req.headers['user-agent'] || '').slice(0, 200),
    createdAt: now(),
    resolvedAt: null,
  });
  return send(res, 200, { ok: true });
});

R('GET', '/app/admin/feedback', async (req, res) => {
  const admin = requireAdmin(req, res); if (!admin) return;
  const params = new URL(req.url, 'http://x').searchParams;
  const limit = Math.min(parseInt(params.get('limit') || '100', 10), 500);
  const onlyOpen = params.get('open') === '1';
  const rows = db.all('feedback')
    .filter(r => onlyOpen ? !r.resolvedAt : true)
    .sort((a, b) => new Date(b.createdAt) - new Date(a.createdAt))
    .slice(0, limit);
  const npsTotal = db.all('feedback').length;
  const npsPromoters = db.all('feedback').filter(f => f.score >= 9).length;
  const npsDetractors = db.all('feedback').filter(f => f.score <= 6).length;
  const nps = npsTotal ? Math.round(((npsPromoters - npsDetractors) / npsTotal) * 100) : null;
  return send(res, 200, { feedback: rows, count: rows.length, nps, total: npsTotal });
});

R('POST', /^\/app\/admin\/feedback\/([^/]+)\/resolve$/, async (req, res, m) => {
  const admin = requireAdmin(req, res); if (!admin) return;
  await db.patch('feedback', f => f.id === m[1], { resolvedAt: now(), resolvedBy: admin.id });
  await audit(admin.id, 'feedback.resolve', m[1], {}, req);
  return send(res, 200, { ok: true });
});

// ─── Wire-deposit reference (pre-funded bank transfer flow) ──────
R('GET', '/app/me/wire-reference', async (req, res) => {
  const user = requireAuth(req, res); if (!user) return;
  const fresh = db.find('users', u => u.id === user.id);
  // Stable per-user reference number that includes a checksum.
  const seed = (fresh.id || '').replace(/[^a-z0-9]/gi, '').toUpperCase().slice(-6) || 'MRBHA0';
  const checksum = require('crypto').createHash('sha256').update('wire:' + fresh.id).digest('hex').slice(0, 4).toUpperCase();
  const reference = `MRB-${seed}-${checksum}`;
  return send(res, 200, {
    reference,
    instructions: {
      bankName: 'البنك الأهلي السعودي',
      bankNameEn: 'Saudi National Bank',
      accountName: 'شركة مُرابحة للاستثمار',
      accountNameEn: 'Murbha Investment Co.',
      iban: 'SA0000000000000000000000',
      bic: 'NCBKSAJEXXX',
      minAmount: 1000,
      notes: 'استخدم الرمز المرجعي في حقل الوصف لضمان إيداع المبلغ في حسابك خلال يوم عمل واحد.',
    },
  });
});

R('POST', '/app/me/wire-claim', async (req, res) => {
  const user = requireAuth(req, res); if (!user) return;
  const body = await readJson(req);
  const amount = Number(body?.amount);
  const senderName = (body?.senderName || '').toString().trim().slice(0, 120);
  const sentAt = (body?.sentAt || '').toString().slice(0, 30);
  if (!(amount > 0) || !senderName) return err(res, 400, 'invalid_input');
  await db.update(d => {
    d.transactions.push({
      id: S.newId('txn_'),
      userId: user.id, kind: 'wire_pending',
      amount, status: 'pending',
      methodLabel: 'حوالة بنكية',
      description: `بانتظار وصول الحوالة (المُرسِل: ${senderName})`,
      createdAt: now(),
      senderName, sentAt: sentAt || null,
    });
  });
  await notify(user.id, 'deposit', 'استلمنا إشعار الحوالة',
    `نتحقّق الآن من وصول حوالتك بمبلغ ${amount.toLocaleString('ar-SA')} ر.س. سنُحدّث حالتها فور وصولها.`);
  await audit(user.id, 'wire.claim', user.id, { amount, sender: senderName }, req);
  return send(res, 200, { ok: true });
});

