// ─── Weekly portfolio summary email (user-triggered or scheduled) ─
R('POST', '/app/me/summary/send', async (req, res) => {
  const user = requireAuth(req, res); if (!user) return;
  const fresh = db.find('users', u => u.id === user.id);
  if (!fresh?.email) return err(res, 400, 'invalid_input', { field: 'email' });
  const invs = db.filter('investments', i => i.userId === user.id && i.status !== 'canceled');
  const txns = db.filter('transactions', t => t.userId === user.id);
  const projIdx = Object.fromEntries(db.all('projects').map(p => [p.id, p]));
  const fmt = (n) => Number(n || 0).toLocaleString('ar-SA');
  const balance = Number(fresh.balance || 0);
  const totalInvested = invs.reduce((s, i) => s + (Number(i.amount) || 0), 0);
  const ago7 = Date.now() - 7 * 24 * 60 * 60 * 1000;
  const weekTxns = txns.filter(t => new Date(t.createdAt).getTime() >= ago7);
  const weekDeposits = weekTxns.filter(t => t.kind === 'deposit').reduce((s, t) => s + Number(t.amount || 0), 0);
  const weekProfits = weekTxns.filter(t => (t.kind === 'profit' || t.kind === 'payout' || t.kind === 'refund')).reduce((s, t) => s + Number(t.amount || 0), 0);
  // Upcoming payouts (next quarter from each investment)
  const upcoming = [];
  for (const inv of invs) {
    const p = projIdx[inv.projectId];
    if (!p) continue;
    const start = inv.createdAt ? new Date(inv.createdAt) : new Date();
    for (let q = 1; q <= Math.max(1, Math.round((p.termMonths || 12) / 3)); q++) {
      const d = new Date(start);
      d.setMonth(d.getMonth() + q * 3);
      if (d.getTime() < Date.now()) continue;
      if (d.getTime() > Date.now() + 60 * 24 * 60 * 60 * 1000) break;
      const perQ = ((p.profitRate || 0.092) * (inv.amount || 0)) / 4;
      upcoming.push({ when: d, amount: perQ, name: p.name });
      break;
    }
  }
  upcoming.sort((a, b) => a.when - b.when);

  const upcomingRows = upcoming.slice(0, 5).map(u =>
    `<tr><td style="padding:6px 0;color:#0d1612;">${u.name}</td>
    <td style="padding:6px 0;color:#6b7268;font-size:12px;direction:ltr;text-align:start;">${u.when.toISOString().slice(0, 10)}</td>
    <td style="padding:6px 0;text-align:end;font-weight:700;color:#0f6e3a;">~ ${fmt(Math.round(u.amount))} ر.س</td></tr>`
  ).join('');

  const html = `<!doctype html><html lang="ar" dir="rtl"><meta charset="utf-8">
<body style="font-family:Tajawal,Cairo,Arial,sans-serif;background:#fbf6ea;padding:24px;color:#0d1612;direction:rtl;text-align:right;">
<div style="max-width:560px;margin:0 auto;background:#fff;border-radius:14px;padding:28px;border:1px solid rgba(13,22,18,0.08);">
  <div style="border-bottom:2px solid #b08840;padding-bottom:14px;margin-bottom:18px;">
    <div style="font:900 18px Cairo,sans-serif;color:#062b1e;">منصة مُرابحة</div>
    <div style="font-size:12px;color:#6b7268;">ملخّص محفظتك الأسبوعي</div>
  </div>
  <p style="margin:0 0 16px;color:#0d1612;">مرحباً ${fresh.name || ''}, هذا ملخّص آخر ٧ أيام.</p>
  <div style="display:flex;gap:8px;margin-bottom:18px;flex-wrap:wrap;">
    <div style="flex:1;min-width:140px;background:#fbf8ee;border:1px solid rgba(13,22,18,0.08);border-radius:10px;padding:12px;text-align:center;">
      <div style="font:900 18px Cairo,sans-serif;color:#062b1e;">${fmt(balance)} ر.س</div>
      <div style="font-size:11px;color:#6b7268;margin-top:3px;">الرصيد المتاح</div>
    </div>
    <div style="flex:1;min-width:140px;background:#fbf8ee;border:1px solid rgba(13,22,18,0.08);border-radius:10px;padding:12px;text-align:center;">
      <div style="font:900 18px Cairo,sans-serif;color:#0a4d36;">${fmt(totalInvested)} ر.س</div>
      <div style="font-size:11px;color:#6b7268;margin-top:3px;">إجمالي الاستثمار</div>
    </div>
  </div>
  <table style="width:100%;border-collapse:collapse;font-size:13px;">
    <tr><td style="padding:8px 0;color:#6b7268;">الإيداعات هذا الأسبوع</td><td style="text-align:end;font-weight:700;">${fmt(weekDeposits)} ر.س</td></tr>
    <tr><td style="padding:8px 0;color:#6b7268;">الأرباح والاسترداد</td><td style="text-align:end;font-weight:700;color:#0f6e3a;">${fmt(weekProfits)} ر.س</td></tr>
    <tr><td style="padding:8px 0;color:#6b7268;">عدد الصفقات النشطة</td><td style="text-align:end;font-weight:700;">${invs.filter(i => i.status === 'active').length}</td></tr>
  </table>
  ${upcomingRows ? `<div style="margin-top:18px;"><div style="font:800 13px Cairo,sans-serif;color:#062b1e;margin-bottom:6px;">التوزيعات القادمة (٦٠ يوم)</div><table style="width:100%;border-collapse:collapse;font-size:12px;">${upcomingRows}</table></div>` : ''}
  <p style="margin-top:24px;font-size:11px;color:#6b7268;line-height:1.7;">لإيقاف هذه الرسالة، عدّل تفضيلات الإشعارات من <a href="https://murbha.sa/profile.html" style="color:#062b1e;font-weight:700;">حسابك</a>.</p>
</div>
</body></html>`;

  const text = `ملخّص محفظتك الأسبوعي\nالرصيد: ${fmt(balance)} ر.س\nإجمالي الاستثمار: ${fmt(totalInvested)} ر.س\nإيداعات الأسبوع: ${fmt(weekDeposits)} ر.س\nأرباح: ${fmt(weekProfits)} ر.س`;
  try {
    await M.send({ to: fresh.email, subject: 'ملخّص محفظتك على مُرابحة', html, text });
    await db.patch('users', u => u.id === user.id, { lastSummaryAt: now() });
    return send(res, 200, { ok: true, to: fresh.email });
  } catch (e) { return err(res, 502, 'server'); }
});

// ─── Sessions / devices ──────────────────────────────────────────
// We don't persist per-session rows; instead, group successful login records
// by IP + UA fingerprint to surface "trusted devices". Revoke = bump a per-user
// timestamp; cookies issued before it are rejected by the validator.
const _uaFingerprint = (ua) => {
  if (!ua) return 'unknown';
  // Browser + OS family extracted, ignoring version churn.
  const browser = /(Edg|Chrome|Firefox|Safari|Opera)\//.exec(ua)?.[1] || 'browser';
  const os = /(Windows|Mac OS X|iPhone|iPad|Android|Linux)/.exec(ua)?.[1] || 'os';
  const isMobile = /iPhone|Android.*Mobile|iPad/.test(ua);
  return `${browser} · ${os}` + (isMobile ? ' · mobile' : '');
};
const _maskIp = (ip) => {
  if (!ip) return '—';
  if (ip.includes(':')) return ip.replace(/^([^:]+:[^:]+).*/, '$1::****');
  return ip.replace(/\.\d+$/, '.***');
};
R('GET', '/app/me/tax-statement', async (req, res) => {
  const user = requireAuth(req, res); if (!user) return;
  const url = new URL(req.url, 'http://x');
  const year = parseInt(url.searchParams.get('year') || '', 10) || new Date().getFullYear();
  if (year < 2020 || year > 2100) return err(res, 400, 'invalid_input');
  const start = new Date(year, 0, 1).getTime();
  const end = new Date(year + 1, 0, 1).getTime();
  const fresh = db.find('users', u => u.id === user.id);
  const projIdx = Object.fromEntries(db.all('projects').map(p => [p.id, p]));
  const inYear = (iso) => {
    const t = new Date(iso || 0).getTime();
    return t >= start && t < end;
  };
  const invs = db.filter('investments', i => i.userId === user.id && inYear(i.createdAt));
  const txns = db.filter('transactions', t => t.userId === user.id && inYear(t.createdAt));
  const profits = txns.filter(t => t.kind === 'profit' || t.kind === 'payout');
  const refunds = txns.filter(t => t.kind === 'refund');
  const totalInvested = invs.reduce((s, i) => s + Number(i.amount || 0), 0);
  const totalProfit = profits.reduce((s, t) => s + Number(t.amount || 0), 0);
  const totalRefunds = refunds.reduce((s, t) => s + Number(t.amount || 0), 0);
  const certHash = require('crypto').createHash('sha256').update('tax:' + user.id + ':' + year).digest('hex').slice(0, 8).toUpperCase();
  return send(res, 200, {
    issuedAt: now(),
    certificateNumber: `MRB-TAX-${year}-${certHash}`,
    holder: {
      name: fresh.name || null,
      nationalId: fresh.nationalId || null,
      email: fresh.email || null,
    },
    year,
    summary: {
      investmentsCount: invs.length,
      totalInvested,
      totalProfit,
      totalRefunds,
      netGain: totalProfit + totalRefunds,
    },
    investments: invs.map(i => ({
      id: i.id,
      projectName: projIdx[i.projectId]?.name || '—',
      projectCategory: projIdx[i.projectId]?.category || null,
      amount: i.amount,
      expectedReturn: i.expectedReturn,
      createdAt: i.createdAt,
      status: i.status,
    })),
    profits: profits.map(t => ({
      id: t.id, amount: t.amount, description: t.description, createdAt: t.createdAt,
    })),
    notes: 'هذا البيان مُولّد إلكترونياً ويصلح كمستند داعم في إقراراتك الضريبية. ليس بديلاً عن تقرير المحاسب القانوني.',
  });
});

R('GET', '/app/me/activity', async (req, res) => {
  const user = requireAuth(req, res); if (!user) return;
  const fresh = db.find('users', u => u.id === user.id);
  const events = [];
  // Logins (success only, last 60)
  db.filter('loginAttempts', a => a.userId === user.id && a.success)
    .slice(-60).forEach(a => events.push({
      kind: 'login', title: 'تسجيل دخول ناجح',
      at: a.createdAt, meta: { ip: _maskIp(a.ip), ua: _uaFingerprint(a.ua) },
    }));
  db.filter('loginAttempts', a => a.userId === user.id && !a.success)
    .slice(-30).forEach(a => events.push({
      kind: 'login_fail', title: 'محاولة دخول فاشلة',
      at: a.createdAt, meta: { ip: _maskIp(a.ip), reason: a.reason || '—' },
    }));
  // Transactions
  db.filter('transactions', t => t.userId === user.id).slice(-100).forEach(t => events.push({
    kind: 'txn:' + (t.kind || 'transaction'),
    title: t.description || (t.kind === 'deposit' ? 'إيداع' : t.kind === 'withdraw' ? 'سحب' : t.kind),
    at: t.createdAt,
    meta: { amount: t.amount, status: t.status },
  }));
  // Investments
  db.filter('investments', i => i.userId === user.id).forEach(i => events.push({
    kind: 'investment', title: 'استثمار جديد',
    at: i.createdAt, meta: { amount: i.amount },
  }));
  // Security events from audit log (filter by actor=user)
  db.filter('auditLog', l => l.actorId === user.id && (
    l.action?.startsWith('auth.') || l.action?.startsWith('email.') ||
    l.action?.startsWith('phone.') || l.action === 'password.change' ||
    l.action === 'flags.update' || l.action?.startsWith('leaderboard.')
  )).forEach(l => events.push({
    kind: 'security', title: l.action,
    at: l.createdAt, meta: l.meta || {},
  }));
  events.sort((a, b) => new Date(b.at) - new Date(a.at));
  return send(res, 200, { events: events.slice(0, 200) });
});

