R('GET', '/app/me/anniversaries', async (req, res) => {
  const auth = requireAuth(req, res); if (!auth) return;
  const u = db.find('users', x => x.id === auth.id);
  if (!u) return err(res, 404, 'not_found');
  if (!u.createdAt) return send(res, 200, { hasData: false });
  const joined = new Date(u.createdAt);
  if (Number.isNaN(joined.getTime())) return send(res, 200, { hasData: false });
  const now = new Date();
  const yearsElapsed = (now.getTime() - joined.getTime()) / (365.25 * 86400000);
  const fullYears = Math.floor(yearsElapsed);
  const next = new Date(joined);
  next.setUTCFullYear(next.getUTCFullYear() + fullYears + 1);
  const daysUntilNext = Math.max(0, Math.ceil((next.getTime() - now.getTime()) / 86400000));
  const invs = db.filter('investments', i => i.userId === u.id && i.status !== 'canceled');
  const milestones = [
    { key: '1m', label: '🎉 شهر معنا', target: 30, achieved: yearsElapsed * 365 >= 30 },
    { key: '6m', label: '💫 ستّة أشهر', target: 180, achieved: yearsElapsed * 365 >= 180 },
    { key: '1y', label: '🥇 سنة كاملة', target: 365, achieved: fullYears >= 1 },
    { key: '2y', label: '🥈 سنتان', target: 730, achieved: fullYears >= 2 },
    { key: '3y', label: '🥉 ثلاث سنوات', target: 1095, achieved: fullYears >= 3 },
    { key: '5y', label: '⭐ خمس سنوات', target: 1825, achieved: fullYears >= 5 },
    { key: '10y', label: '💎 عشر سنوات', target: 3650, achieved: fullYears >= 10 },
  ];
  return send(res, 200, {
    hasData: true,
    joinedAt: joined.toISOString(),
    fullYears,
    yearsElapsed: +(yearsElapsed).toFixed(2),
    daysUntilNextAnniversary: daysUntilNext,
    investmentsToDate: invs.length,
    milestones,
    nextMilestone: milestones.find(m => !m.achieved) || null,
  });
});

