R('GET', '/app/me/sessions', async (req, res) => {
  const user = requireAuth(req, res); if (!user) return;
  const fresh = db.find('users', u => u.id === user.id);
  const recent = db.filter('loginAttempts', a => a.userId === user.id && a.success)
    .sort((a, b) => new Date(b.createdAt) - new Date(a.createdAt))
    .slice(0, 100);
  const groups = new Map();
  for (const a of recent) {
    const fp = _uaFingerprint(a.ua) + ' · ' + _maskIp(a.ip);
    if (!groups.has(fp)) groups.set(fp, { fingerprint: fp, ua: _uaFingerprint(a.ua), ip: _maskIp(a.ip), lastSeen: a.createdAt, firstSeen: a.createdAt, count: 0 });
    const g = groups.get(fp);
    g.count++;
    if (new Date(a.createdAt) > new Date(g.lastSeen)) g.lastSeen = a.createdAt;
    if (new Date(a.createdAt) < new Date(g.firstSeen)) g.firstSeen = a.createdAt;
  }
  const currentFp = _uaFingerprint(req.headers['user-agent'] || '') + ' · ' + _maskIp(clientIp(req));
  const labels = fresh.deviceLabels || {};
  const devices = [...groups.values()]
    .map(g => ({ ...g, label: labels[g.fingerprint] || null }))
    .sort((a, b) => new Date(b.lastSeen) - new Date(a.lastSeen));
  return send(res, 200, {
    devices,
    sessionsInvalidAfter: fresh.sessionsInvalidAfter || null,
    currentFingerprint: currentFp,
  });
});

