R('POST', '/app/newsletter/unsubscribe', async (req, res) => {
  const body = await readJson(req);
  const email = (body?.email || '').toString().trim().toLowerCase();
  if (!email || !/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)) {
    return err(res, 400, 'invalid_email');
  }
  const existing = db.find('newsletter', n => n.email === email);
  if (!existing) return send(res, 200, { ok: true, removed: false });
  await db.update(d => { d.newsletter = (d.newsletter || []).filter(n => n.email !== email); });
  return send(res, 200, { ok: true, removed: true });
});

