// ─── Receipt verification (public, signed, no PII) ───────────────
const _receiptSig = (invId) => require('crypto').createHmac('sha256',
  process.env.SESSION_SECRET || 'dev-only-fallback')
  .update('receipt:' + invId).digest('hex').slice(0, 24);

R('GET', /^\/app\/public\/receipt\/verify\/([^/]+)\/([^/]+)$/, async (req, res, m) => {
  const invId = m[1];
  const sig = m[2];
  if (sig !== _receiptSig(invId)) return err(res, 400, 'invalid_token');
  const inv = db.find('investments', i => i.id === invId);
  if (!inv) return err(res, 404, 'not_found');
  const project = db.find('projects', p => p.id === inv.projectId);
  return send(res, 200, {
    verified: true,
    investment: {
      id: inv.id,
      amountSar: inv.amount,
      createdAt: inv.createdAt,
      status: inv.status,
    },
    project: {
      name: project?.name || '—',
      slug: project?.slug || null,
    },
    issuer: 'Murbha Platform',
  });
});

// Helper visible to receipt UI to build the canonical verification URL.
R('GET', '/app/me/monthly-statement', async (req, res) => {
  const user = requireAuth(req, res); if (!user) return;
  const params = new URL(req.url, 'http://x').searchParams;
  const ym = (params.get('month') || '').trim();
  const m = ym && /^\d{4}-\d{2}$/.test(ym) ? ym : new Date().toISOString().slice(0, 7);
  const [y, mo] = m.split('-').map(Number);
  const start = new Date(y, mo - 1, 1).getTime();
  const end = new Date(y, mo, 1).getTime();
  const txns = db.filter('transactions', t => t.userId === user.id && new Date(t.createdAt).getTime() >= start && new Date(t.createdAt).getTime() < end);
  const invs = db.filter('investments', i => i.userId === user.id && new Date(i.createdAt).getTime() >= start && new Date(i.createdAt).getTime() < end);
  const sum = (arr, fn) => arr.reduce((s, x) => s + fn(x), 0);
  const deposits = txns.filter(t => t.kind === 'deposit' && t.status === 'completed');
  const withdrawals = txns.filter(t => t.kind === 'withdraw' && (t.status === 'completed' || t.status === 'pending'));
  const profits = txns.filter(t => t.kind === 'profit' || t.kind === 'payout');
  return send(res, 200, {
    month: m,
    deposits: { count: deposits.length, total: sum(deposits, t => Math.abs(Number(t.amount) || 0)) },
    withdrawals: { count: withdrawals.length, total: sum(withdrawals, t => Math.abs(Number(t.amount) || 0)) },
    investments: { count: invs.length, total: sum(invs.filter(i => i.status !== 'canceled'), i => Number(i.amount) || 0) },
    profits: { count: profits.length, total: sum(profits, t => Number(t.amount) || 0) },
    transactions: txns.sort((a, b) => new Date(b.createdAt) - new Date(a.createdAt)),
  });
});

R('GET', '/app/me/transactions.csv', async (req, res) => {
  const user = requireAuth(req, res); if (!user) return;
  const txns = db.all('transactions')
    .filter(t => t.userId === user.id)
    .sort((a, b) => new Date(b.createdAt) - new Date(a.createdAt));
  const rows = [['createdAt','kind','amount','status','description','methodLabel','ref']];
  for (const t of txns) {
    rows.push([
      t.createdAt || '',
      t.kind || '',
      String(t.amount ?? ''),
      t.status || '',
      t.description || '',
      t.methodLabel || '',
      t.ref || '',
    ]);
  }
  const csv = rows.map(r => r.map(c => /[",\n]/.test(String(c)) ? '"' + String(c).replace(/"/g, '""') + '"' : String(c)).join(',')).join('\n');
  res.writeHead(200, {
    'Content-Type': 'text/csv; charset=utf-8',
    'Content-Disposition': 'attachment; filename="murbha-payments-' + new Date().toISOString().slice(0, 10) + '.csv"',
  });
  return res.end('﻿' + csv);
});

R('GET', /^\/app\/me\/receipt\/url\/([^/]+)$/, async (req, res, m) => {
  const user = requireAuth(req, res); if (!user) return;
  const invId = m[1];
  const inv = db.find('investments', i => i.id === invId && i.userId === user.id);
  if (!inv) return err(res, 404, 'not_found');
  const sig = _receiptSig(invId);
  const base = process.env.APP_PUBLIC_URL || ('http://' + (req.headers.host || 'localhost'));
  return send(res, 200, { url: `${base}/verify-receipt.html?inv=${encodeURIComponent(invId)}&sig=${sig}` });
});

// ─── Email a receipt to the user (Resend if configured) ──────────
R('POST', '/app/me/receipt/email', async (req, res) => {
  const user = requireAuth(req, res); if (!user) return;
  const body = await readJson(req);
  const invId = (body?.investmentId || '').toString();
  if (!invId) return err(res, 400, 'invalid_input');
  const inv = db.find('investments', i => i.id === invId && i.userId === user.id);
  if (!inv) return err(res, 404, 'not_found');
  const project = db.find('projects', p => p.id === inv.projectId);
  const fresh = db.find('users', u => u.id === user.id);
  if (!fresh?.email) return err(res, 400, 'invalid_input', { field: 'email' });

  const fmt = (n) => Number(n || 0).toLocaleString('ar-SA');
  const subject = `إيصال استثمارك في ${project?.name || 'مشروع'}`;
  const rate = ((project?.profitRate || 0) * 100).toFixed(1);
  const expected = Number(inv.expectedReturn || 0);
  const principal = Number(inv.amount || 0);
  const profit = Math.max(0, expected - principal);
  const date = new Date(inv.createdAt).toLocaleDateString('ar-SA', { year: 'numeric', month: 'long', day: 'numeric' });

  const html = `<!doctype html><html lang="ar" dir="rtl"><meta charset="utf-8">
<body style="font-family:Tajawal,Cairo,Arial,sans-serif;background:#fbf6ea;padding:24px;color:#0d1612;direction:rtl;text-align:right;">
<div style="max-width:560px;margin:0 auto;background:#fff;border-radius:14px;padding:28px;border:1px solid rgba(13,22,18,0.08);">
  <div style="display:flex;justify-content:space-between;padding-bottom:14px;border-bottom:2px solid #b08840;margin-bottom:18px;">
    <div>
      <div style="font:900 18px Cairo,sans-serif;color:#062b1e;">منصة مُرابحة</div>
      <div style="font-size:12px;color:#6b7268;">إيصال استثمار</div>
    </div>
    <div style="text-align:end;font-size:11px;color:#6b7268;">
      <div>رقم الإيصال</div>
      <div style="font:800 13px monospace;color:#062b1e;">MRB-${inv.id.slice(-8).toUpperCase()}</div>
      <div style="margin-top:6px;">${date}</div>
    </div>
  </div>
  <h2 style="font:900 16px Cairo,sans-serif;color:#0a4d36;margin:0 0 14px;">${project?.name || 'مشروع'}</h2>
  <table style="width:100%;border-collapse:collapse;font-size:13px;">
    <tr><td style="padding:8px 0;color:#6b7268;">المستثمر</td><td style="text-align:end;font-weight:700;">${fresh.name || '—'}</td></tr>
    <tr><td style="padding:8px 0;color:#6b7268;">العائد السنوي</td><td style="text-align:end;font-weight:700;">${rate}٪</td></tr>
    <tr><td style="padding:8px 0;color:#6b7268;">رأس المال</td><td style="text-align:end;font-weight:700;">${fmt(principal)} ر.س</td></tr>
    <tr><td style="padding:8px 0;color:#6b7268;">الربح المتوقع</td><td style="text-align:end;font-weight:700;color:#0f6e3a;">${fmt(profit)} ر.س</td></tr>
    <tr style="border-top:2px solid #062b1e;"><td style="padding:10px 0;font-weight:900;color:#062b1e;">الإجمالي المتوقع</td><td style="text-align:end;font:900 16px Cairo,sans-serif;color:#062b1e;">${fmt(expected)} ر.س</td></tr>
  </table>
  <p style="margin-top:24px;font-size:12px;color:#6b7268;line-height:1.7;border-top:1px solid rgba(13,22,18,0.08);padding-top:12px;">
    صادر إلكترونياً — لا يحتاج إلى ختم أو توقيع. للاستفسار راسل support@murbha.sa.
  </p>
</div>
</body></html>`;
  const text = `إيصال استثمارك\n\n${project?.name || 'مشروع'}\nرأس المال: ${fmt(principal)} ر.س\nالربح المتوقع: ${fmt(profit)} ر.س\nالإجمالي: ${fmt(expected)} ر.س`;

  try {
    const r = await M.send({ to: fresh.email, subject, html, text });
    await audit(user.id, 'receipt.email', invId, { to: fresh.email, sent: !!r }, req);
    return send(res, 200, { ok: true, to: fresh.email });
  } catch (e) {
    return err(res, 502, 'server');
  }
});

// ─── Calendar (.ics) export for upcoming payouts ──────────────────
// Signed public ICS feed users can subscribe to in their calendar app.
// We sign on user.id + a per-user secret seeded once so revoking the feed
// is as simple as bumping the secret.
const _icsSecret = () => process.env.SESSION_SECRET || 'dev-only-fallback';
const _icsSig = (userId, salt) => require('crypto').createHmac('sha256', _icsSecret())
  .update('ics:' + userId + ':' + (salt || '')).digest('hex').slice(0, 24);

R('GET', '/app/me/calendar-feed', async (req, res) => {
  const user = requireAuth(req, res); if (!user) return;
  const fresh = db.find('users', u => u.id === user.id);
  let salt = fresh.icsSalt;
  if (!salt) {
    salt = require('crypto').randomBytes(8).toString('hex');
    await db.patch('users', u => u.id === user.id, { icsSalt: salt });
  }
  const sig = _icsSig(user.id, salt);
  const base = process.env.APP_PUBLIC_URL || ('http://' + (req.headers.host || 'localhost'));
  return send(res, 200, {
    url: `${base}/app/public/calendar/${encodeURIComponent(user.id)}/${sig}.ics`,
    webcalUrl: `webcal://${(req.headers.host || 'localhost')}/app/public/calendar/${encodeURIComponent(user.id)}/${sig}.ics`,
  });
});

