R('GET', /^\/app\/public\/calendar\/([^/]+)\/([^/]+)\.ics$/, async (req, res, m) => {
  const userId = m[1];
  const sig = m[2];
  const user = db.find('users', u => u.id === userId);
  if (!user) { res.writeHead(404); return res.end(); }
  if (sig !== _icsSig(userId, user.icsSalt || '')) { res.writeHead(403); return res.end(); }
  // Reuse the payouts-ICS body builder by calling the same logic.
  const projIdx = Object.fromEntries(db.all('projects').map(p => [p.id, p]));
  const invs = db.filter('investments', i => i.userId === userId && i.status !== 'canceled');
  const lines = [
    'BEGIN:VCALENDAR',
    'VERSION:2.0',
    'PRODID:-//Murbha//Payouts//AR',
    'CALSCALE:GREGORIAN',
    'METHOD:PUBLISH',
    'X-WR-CALNAME:توزيعات مُرابحة',
    'X-WR-TIMEZONE:Asia/Riyadh',
  ];
  const pad = (n) => String(n).padStart(2, '0');
  const fmt = (d) => d.getUTCFullYear() + pad(d.getUTCMonth()+1) + pad(d.getUTCDate()) + 'T' + pad(d.getUTCHours()) + pad(d.getUTCMinutes()) + '00Z';
  const escIcs = (s) => String(s || '').replace(/\\/g, '\\\\').replace(/;/g, '\\;').replace(/,/g, '\\,').replace(/\n/g, '\\n');
  const nowD = new Date();
  for (const inv of invs) {
    const p = projIdx[inv.projectId];
    if (!p) continue;
    const rate = p.profitRate || 0.092;
    const term = p.termMonths || 12;
    const quarters = Math.max(1, Math.round(term / 3));
    const perQ = ((inv.amount || 0) * rate) / 4;
    const start = inv.createdAt ? new Date(inv.createdAt) : new Date();
    for (let q = 1; q <= quarters; q++) {
      const d = new Date(start);
      d.setMonth(d.getMonth() + q * 3);
      d.setHours(10, 0, 0, 0);
      const end = new Date(d.getTime() + 60 * 60 * 1000);
      const uid = `payout-${inv.id}-q${q}@murbha`;
      lines.push(
        'BEGIN:VEVENT',
        `UID:${uid}`,
        `DTSTAMP:${fmt(nowD)}`,
        `DTSTART:${fmt(d)}`,
        `DTEND:${fmt(end)}`,
        `SUMMARY:${escIcs('توزيع ربعي — ' + p.name + ' (الربع ' + q + ')')}`,
        `DESCRIPTION:${escIcs('توزيع متوقّع: ~' + Math.round(perQ).toLocaleString('ar-SA') + ' ر.س.')}`,
        'STATUS:CONFIRMED',
        'TRANSP:TRANSPARENT',
        'END:VEVENT'
      );
    }
  }
  lines.push('END:VCALENDAR');
  res.writeHead(200, {
    'Content-Type': 'text/calendar; charset=utf-8',
    'Cache-Control': 'public, max-age=300',
  });
  res.end(lines.join('\r\n'));
});

