    secretPreview: w.secret ? w.secret.slice(0, 8) + '...' : null,
    disabledAt: w.disabledAt, lastDeliveredAt: w.lastDeliveredAt || null,
    lastStatus: w.lastStatus || null, createdAt: w.createdAt,
