R('GET', '/app/admin/idle-balances', async (req, res) => {
  const admin = requireAdmin(req, res); if (!admin) return;
  const params = new URL(req.url, 'http://x').searchParams;
  const minBalance = Math.max(0, parseInt(params.get('minBalance') || '500', 10));
  const idleDays = Math.max(1, Math.min(365, parseInt(params.get('idleDays') || '14', 10)));
  const cutoff = Date.now() - idleDays * 24 * 60 * 60 * 1000;
  const invByUser = new Map();
  for (const i of db.all('investments')) {
    const t = new Date(i.createdAt || 0).getTime();
    const cur = invByUser.get(i.userId) || 0;
    if (t > cur) invByUser.set(i.userId, t);
  }
  const list = db.all('users')
    .filter(u => !u.deletedAt && u.role !== 'admin' && (u.balance || 0) >= minBalance)
    .map(u => ({ user: u, lastInv: invByUser.get(u.id) || 0 }))
    .filter(x => x.lastInv < cutoff)
    .sort((a, b) => (b.user.balance || 0) - (a.user.balance || 0))
    .slice(0, 200)
    .map(({ user, lastInv }) => ({
      id: user.id, name: user.name || '—', email: user.email || '',
      balance: user.balance || 0,
      lastInvestmentAt: lastInv ? new Date(lastInv).toISOString() : null,
      daysIdle: lastInv ? Math.floor((Date.now() - lastInv) / (24 * 60 * 60 * 1000)) : null,
    }));
  return send(res, 200, { users: list, total: list.length, idleDays, minBalance });
});

