R('POST', /^\/app\/admin\/withdrawals\/([^/]+)\/approve$/, async (req, res, m) => {
  const admin = requireAdmin(req, res); if (!admin) return;
  const txn = db.find('transactions', t => t.id === m[1] && t.kind === 'withdraw');
  if (!txn) return err(res, 404, 'not_found');
  if (txn.status !== 'pending') return err(res, 400, 'invalid_status');
  await db.patch('transactions', t => t.id === txn.id, { status: 'completed', completedAt: new Date().toISOString(), approvedBy: admin.id });
  await audit(admin.id, 'admin.withdraw.approve', txn.id, { amount: Math.abs(txn.amount), userId: txn.userId }, req);
  await notify(txn.userId, 'withdraw_approved', 'تم اعتماد سحبك',
    'تمت الموافقة على طلب سحب ' + Math.abs(txn.amount).toLocaleString('ar-SA') + ' ر.س. سيصل إلى حسابك قريباً.');
  return send(res, 200, { ok: true });
});

R('POST', /^\/app\/admin\/withdrawals\/([^/]+)\/reject$/, async (req, res, m) => {
  const admin = requireAdmin(req, res); if (!admin) return;
  const body = await readJson(req);
  const reason = (body?.reason || '').toString().trim().slice(0, 500);
  const txn = db.find('transactions', t => t.id === m[1] && t.kind === 'withdraw');
  if (!txn) return err(res, 404, 'not_found');
  if (txn.status !== 'pending') return err(res, 400, 'invalid_status');
  await db.update(d => {
    const t = d.transactions.find(x => x.id === txn.id);
    t.status = 'rejected';
    t.rejectedAt = new Date().toISOString();
    t.rejectedBy = admin.id;
    t.rejectionReason = reason;
    const u = d.users.find(x => x.id === txn.userId);
    if (u) u.balance = (u.balance || 0) + Math.abs(txn.amount);
  });
  await audit(admin.id, 'admin.withdraw.reject', txn.id, { amount: Math.abs(txn.amount), reason }, req);
  await notify(txn.userId, 'withdraw_rejected', 'تم رفض سحبك',
    'تعذّر تنفيذ طلب السحب. تمت إعادة المبلغ إلى رصيدك.' + (reason ? ' السبب: ' + reason : ''));
  return send(res, 200, { ok: true });
});

R('GET', '/app/admin/project-status', async (req, res) => {
  const admin = requireAdmin(req, res); if (!admin) return;
  const buckets = {
    open: { label: '🟢 مفتوحة للاستثمار', count: 0 },
    funded: { label: '✓ تم تمويلها', count: 0 },
    closed: { label: '🔵 مُغلقة', count: 0 },
    completed: { label: '✅ منجزة بالكامل', count: 0 },
    paused: { label: '⏸ مُوقفة مؤقتاً', count: 0 },
    archived: { label: '📦 مؤرشفة', count: 0 },
    draft: { label: '📝 مسودّة', count: 0 },
  };
  for (const p of db.all('projects')) {
    if (p.archived) buckets.archived.count++;
    else if (p.paused) buckets.paused.count++;
    else if (p.status === 'completed') buckets.completed.count++;
    else if (p.status === 'closed') buckets.closed.count++;
    else if (p.status === 'funded') buckets.funded.count++;
    else if (p.status === 'open') buckets.open.count++;
    else buckets.draft.count++;
  }
  const total = Object.values(buckets).reduce((s, b) => s + b.count, 0);
  const list = Object.entries(buckets).map(([key, b]) => ({ key, ...b, pct: total > 0 ? Math.round((b.count / total) * 100) : 0 })).filter(b => b.count > 0);
  return send(res, 200, { statuses: list, total });
});

R('GET', '/app/admin/investments-by-category', async (req, res) => {
  const admin = requireAdmin(req, res); if (!admin) return;
  const projIdx = Object.fromEntries(db.all('projects').map(p => [p.id, p]));
  const byCat = new Map();
  for (const i of db.all('investments')) {
    if (i.status === 'canceled') continue;
    const p = projIdx[i.projectId];
    const cat = p?.category || 'غير محدّد';
    const b = byCat.get(cat) || { category: cat, count: 0, total: 0, projectIds: new Set() };
    b.count++;
    b.total += Number(i.amount || 0);
    b.projectIds.add(i.projectId);
    byCat.set(cat, b);
  }
  const total = [...byCat.values()].reduce((s, b) => s + b.total, 0);
  const rows = [...byCat.values()].map(b => ({
    category: b.category,
    count: b.count,
    total: b.total,
    projects: b.projectIds.size,
    pct: total > 0 ? Math.round((b.total / total) * 100) : 0,
  })).sort((a, b) => b.total - a.total);
  return send(res, 200, { categories: rows, total });
});

R('GET', '/app/admin/weekly-trend', async (req, res) => {
  const admin = requireAdmin(req, res); if (!admin) return;
  const weeks = 8;
  const buckets = [];
  const now = new Date();
  // Snap to Sunday morning (KSA week start)
  const day = now.getDay();
  const weekStart = new Date(now);
  weekStart.setDate(now.getDate() - day);
  weekStart.setHours(0, 0, 0, 0);
  for (let i = weeks - 1; i >= 0; i--) {
    const start = new Date(weekStart); start.setDate(weekStart.getDate() - i * 7);
    const end = new Date(start); end.setDate(start.getDate() + 7);
    buckets.push({
      label: start.toLocaleDateString('ar-SA', { month: 'short', day: 'numeric' }),
      start: start.toISOString(),
      end: end.toISOString(),
      deposits: 0, depositCount: 0,
      investments: 0, investmentCount: 0,
      withdrawals: 0, withdrawalCount: 0,
      signups: 0,
    });
  }
  const findBucket = (ts) => {
    const t = new Date(ts).getTime();
    for (const b of buckets) {
      if (t >= new Date(b.start).getTime() && t < new Date(b.end).getTime()) return b;
    }
    return null;
  };
  for (const t of db.all('transactions')) {
    if (t.status !== 'completed') continue;
    const b = findBucket(t.createdAt);
    if (!b) continue;
    if (t.kind === 'deposit') { b.deposits += Math.abs(t.amount); b.depositCount++; }
    else if (t.kind === 'withdraw') { b.withdrawals += Math.abs(t.amount); b.withdrawalCount++; }
  }
  for (const i of db.all('investments')) {
    if (i.status === 'canceled') continue;
    const b = findBucket(i.createdAt);
    if (b) { b.investments += Number(i.amount || 0); b.investmentCount++; }
  }
  for (const u of db.all('users')) {
    if (u.role === 'admin' || u.deletedAt) continue;
    const b = findBucket(u.createdAt);
    if (b) b.signups++;
  }
  return send(res, 200, { weeks: buckets });
});

R('GET', '/app/admin/kyc-processing-time', async (req, res) => {
  const admin = requireAdmin(req, res); if (!admin) return;
  const params = new URL(req.url, 'http://x').searchParams;
  const days = Math.max(1, Math.min(365, parseInt(params.get('days') || '90', 10)));
  const cutoff = Date.now() - days * 24 * 60 * 60 * 1000;
  const users = db.all('users').filter(u => u.role !== 'admin' && !u.deletedAt && new Date(u.createdAt || 0).getTime() >= cutoff);
  const times = users
    .filter(u => u.approved && u.approvedAt && u.createdAt)
    .map(u => (new Date(u.approvedAt).getTime() - new Date(u.createdAt).getTime()) / (60 * 60 * 1000))
    .filter(h => h >= 0);
  times.sort((a, b) => a - b);
  const median = times.length ? times[Math.floor(times.length / 2)] : 0;
  const p90 = times.length ? times[Math.floor(times.length * 0.9)] : 0;
  const avg = times.length ? times.reduce((s, h) => s + h, 0) / times.length : 0;
  const within24h = times.filter(h => h <= 24).length;
  const within72h = times.filter(h => h <= 72).length;
  return send(res, 200, {
    days,
    totalSignups: users.length,
    totalApproved: times.length,
    avgHours: Math.round(avg * 10) / 10,
    medianHours: Math.round(median * 10) / 10,
    p90Hours: Math.round(p90 * 10) / 10,
    within24hPct: times.length ? Math.round((within24h / times.length) * 100) : 0,
    within72hPct: times.length ? Math.round((within72h / times.length) * 100) : 0,
  });
});

R('GET', '/app/admin/revenue-trend', async (req, res) => {
  const admin = requireAdmin(req, res); if (!admin) return;
  const byMonth = new Map();
  const now = new Date();
  for (let i = 11; i >= 0; i--) {
    const d = new Date(now.getFullYear(), now.getMonth() - i, 1);
    const key = d.getFullYear() + '-' + String(d.getMonth() + 1).padStart(2, '0');
    byMonth.set(key, {
      month: key,
      label: d.toLocaleString('ar-SA', { month: 'short' }),
      investments: 0, deposits: 0, withdrawals: 0, fees: 0, profits: 0, count: 0,
    });
  }
  for (const t of db.all('transactions')) {
    const status = (t.status || '').toLowerCase();
    if (status && status !== 'completed' && status !== 'succeeded' && status !== 'paid') continue;
    const d = new Date(t.createdAt);
    if (Number.isNaN(d.getTime())) continue;
    const key = d.getFullYear() + '-' + String(d.getMonth() + 1).padStart(2, '0');
    if (!byMonth.has(key)) continue;
    const b = byMonth.get(key);
    const kind = (t.kind || t.type || '').toLowerCase();
    const amt = Math.abs(Number(t.amount || 0));
    if (kind === 'deposit') { b.deposits += amt; b.count++; }
    else if (kind === 'withdraw' || kind === 'withdrawal') { b.withdrawals += amt; b.count++; }
    else if (kind === 'fee' || kind === 'commission') { b.fees += amt; b.count++; }
    else if (kind === 'profit' || kind === 'distribution' || kind === 'payout') { b.profits += amt; b.count++; }
  }
  for (const inv of db.all('investments')) {
    if (inv.status === 'canceled') continue;
    const d = new Date(inv.createdAt);
    if (Number.isNaN(d.getTime())) continue;
    const key = d.getFullYear() + '-' + String(d.getMonth() + 1).padStart(2, '0');
    if (byMonth.has(key)) byMonth.get(key).investments += Number(inv.amount || 0);
  }
  const months = [...byMonth.values()].map(b => ({
    ...b,
    key: b.month,
    investments: Math.round(b.investments),
    deposits: Math.round(b.deposits),
    withdrawals: Math.round(b.withdrawals),
    fees: Math.round(b.fees),
    profits: Math.round(b.profits),
    revenue: Math.round(b.fees + b.investments * 0.012),
  }));
  const totals = months.reduce((acc, m) => ({
    fees: acc.fees + m.fees,
    profits: acc.profits + m.profits,
    deposits: acc.deposits + m.deposits,
  }), { fees: 0, profits: 0, deposits: 0 });
  const totalRevenue = months.reduce((s, m) => s + m.revenue, 0);
  return send(res, 200, {
    hasData: months.length > 0,
    months,
    totalRevenue,
    totals,
  });
});

R('GET', '/app/me/referral-network', async (req, res) => {
  const auth = requireAuth(req, res); if (!auth) return;
  const refs = db.filter('users', u => u.referredBy === auth.id);
  const investedBy = new Map();
  for (const inv of db.all('investments')) {
    if (inv.status === 'canceled') continue;
    investedBy.set(inv.userId, (investedBy.get(inv.userId) || 0) + Number(inv.amount || 0));
  }
  let activeCount = 0, totalInvested = 0;
  const friends = refs.slice().sort((a, b) => new Date(b.createdAt) - new Date(a.createdAt)).slice(0, 20).map(u => {
    const inv = investedBy.get(u.id) || 0;
    if (inv > 0) activeCount++;
    totalInvested += inv;
    const name = (u.name || u.email || '').slice(0, 2) + '***';
    return {
      joinedAt: u.createdAt,
      name,
      kycStatus: u.kycStatus || 'pending',
      hasInvested: inv > 0,
      investedAmount: Math.round(inv),
    };
  });
  for (const u of refs) {
    if (friends.some(f => f.name === ((u.name || u.email || '').slice(0, 2) + '***'))) continue;
    const inv = investedBy.get(u.id) || 0;
    if (inv > 0) activeCount++;
    totalInvested += inv;
  }
  return send(res, 200, {
    total: refs.length,
    activeCount,
    totalInvested: Math.round(totalInvested),
    earnedReward: activeCount * 50,
    friends,
  });
});

