    if (p.fundedAt || (Number(p.fundedAmount || 0) >= Number(p.goalAmount || 0) && Number(p.goalAmount || 0) > 0)) g.funded++;
    if (p.status === 'repaid' || p.repaidAt) g.repaid++;
    if (p.status === 'defaulted' || p.defaultedAt) g.defaulted++;
