R('GET', /^\/app\/projects\/([^/]+)\/portfolio-impact$/, async (req, res, m) => {
  const auth = requireAuth(req, res); if (!auth) return;
  const projectId = m[1];
  const proj = db.find('projects', p => p.id === projectId);
  if (!proj) return send(res, 404, { error: 'not_found' });
  const u = db.find('users', x => x.id === auth.id);
  if (!u) return send(res, 200, { hasData: false });
  const external = Array.isArray(u.externalAssets) ? u.externalAssets : [];
  if (external.length === 0) return send(res, 200, { hasData: false });
  const investments = db.all('investments').filter(i => i.userId === auth.id);
  const myMurabaha = investments.reduce((s, i) => s + Number(i.amount || 0), 0);
  const myExternal = external.reduce((s, a) => s + Number(a.valueSar || 0), 0);
  const totalWealth = myMurabaha + myExternal;
  if (totalWealth === 0) return send(res, 200, { hasData: false });
  const minTicket = Number(proj.minTicket || 1000);
  const cat = proj.category || 'other';
  // Calculate diversification before and after the investment
  const beforeMuShare = (myMurabaha / totalWealth) * 100;
  const afterMuShare = ((myMurabaha + minTicket) / (totalWealth + minTicket)) * 100;
  const externalCategoryMap = {
    realestate: 'real-estate',
    stocks: 'tech',
    business: 'industrial',
  };
  const projConcentration = (() => {
    let same = 0;
    external.forEach(a => {
      const extCat = externalCategoryMap[a.type] || a.type;
      if (extCat === cat) same += Number(a.valueSar || 0);
    });
    return totalWealth > 0 ? (same / totalWealth) * 100 : 0;
  })();
  const overlap = projConcentration > 30;
  return send(res, 200, {
    hasData: true,
    totalWealth: Math.round(totalWealth),
    muSharePct: +beforeMuShare.toFixed(1),
    muShareAfter: +afterMuShare.toFixed(1),
    projectCategoryExposurePct: +projConcentration.toFixed(1),
    overlap,
    recommendation: overlap ? 'تركّز عالٍ في هذه الفئة. فكّر بفئة مختلفة.' : 'يحسّن تنويعك',
  });
});

