R('GET', /^\/app\/projects\/([^/]+)\/gold-benchmark$/, async (req, res, m) => {
  const projectId = m[1];
  const proj = db.find('projects', p => p.id === projectId);
  if (!proj) return send(res, 404, { error: 'not_found' });
  const yieldPct = Number(proj.expectedYield || 0);
  const months = Number(proj.durationMonths || 0);
  if (!yieldPct || !months) return send(res, 200, { hasData: false });
  // Historical gold real return (long-run) ~ 4.4% real, ~7.2% nominal
  const goldNominalYield = 7.2;
  const years = months / 12;
  const dealEndAmount = 10000 * Math.pow(1 + yieldPct / 100, years);
  const goldEndAmount = 10000 * Math.pow(1 + goldNominalYield / 100, years);
  const advantage = dealEndAmount - goldEndAmount;
  const advantagePct = +((advantage / goldEndAmount) * 100).toFixed(1);
  let verdict = 'mu_wins';
  if (yieldPct >= goldNominalYield + 2) verdict = 'mu_clear_winner';
  else if (yieldPct >= goldNominalYield) verdict = 'mu_marginal_winner';
  else if (yieldPct >= goldNominalYield - 2) verdict = 'tie';
  else verdict = 'gold_winner';
  return send(res, 200, {
    hasData: true,
    dealYield: yieldPct,
    goldYield: goldNominalYield,
    years,
    dealEndAmount: Math.round(dealEndAmount),
    goldEndAmount: Math.round(goldEndAmount),
    advantage: Math.round(advantage),
    advantagePct,
    verdict,
  });
});

R('GET', /^\/app\/projects\/([^/]+)\/qualification-required$/, async (req, res, m) => {
  const auth = requireAuth(req, res); if (!auth) return;
  const projectId = m[1];
  const proj = db.find('projects', p => p.id === projectId);
  if (!proj) return send(res, 404, { error: 'not_found' });
  const u = db.find('users', x => x.id === auth.id);
  if (!u) return send(res, 200, { hasData: false });
  const requiresQualified = !!proj.qualifiedOnly;
  const isQualified = !!u.qualifiedInvestor;
  const minTicket = Number(proj.minTicket || 1000);
  // Only show badge if the project has special requirements
  if (!requiresQualified && minTicket < 50000) return send(res, 200, { hasData: false });
  let canInvest = true;
  let reason = '';
  const recommendation = [];
  if (requiresQualified && !isQualified) {
    canInvest = false;
    reason = 'صفقة حصريّة للمستثمر المؤهّل';
    recommendation.push('قدّم لطلب الترقية في ملفّك');
  } else if (minTicket >= 50000 && !isQualified) {
    // SAMA limit warning
    const userTotal = Number(u.yearlyInvested || 0);
    if (userTotal + minTicket > 200000) {
      canInvest = false;
      reason = 'يتجاوز سقف ساما السنوي (٢٠٠ ألف). ترقّ لمؤهّل لرفع السقف';
      recommendation.push('تجاوز سقف ساما');
    } else if (minTicket > 50000) {
      canInvest = false;
      reason = 'يتجاوز سقف ساما لكلّ صفقة (٥٠ ألف)';
      recommendation.push('ترقّ لمؤهّل');
    }
  }
  return send(res, 200, {
    hasData: true,
    requiresQualified,
    isQualified,
    canInvest,
    reason,
    recommendation,
    minTicket,
  });
});

