R('GET', /^\/app\/projects\/([^/]+)\/compound-projection$/, async (req, res, m) => {
  const projectId = m[1];
  const proj = db.find('projects', p => p.id === projectId);
  if (!proj) return send(res, 404, { error: 'not_found' });
  const yieldPct = Number(proj.expectedYield || 0);
  const months = Number(proj.durationMonths || 0);
  if (!yieldPct || !months) return send(res, 200, { hasData: false });
  const reinvestable = !!proj.reinvestmentAvailable || months >= 6;
  // If reinvestable, show what happens if user keeps reinvesting in similar deals over time
  const startAmount = 10000;
  const monthlyRate = yieldPct / 100 / 12;
  const projections = [
    { years: 1, amount: startAmount * Math.pow(1 + monthlyRate, 12) },
    { years: 5, amount: startAmount * Math.pow(1 + monthlyRate, 60) },
    { years: 10, amount: startAmount * Math.pow(1 + monthlyRate, 120) },
    { years: 20, amount: startAmount * Math.pow(1 + monthlyRate, 240) },
    { years: 30, amount: startAmount * Math.pow(1 + monthlyRate, 360) },
  ].map(p => ({ ...p, amount: Math.round(p.amount) }));
  const doublingYears = +(72 / yieldPct).toFixed(1);
  // What happens without reinvestment (just collect distributions)
  const simpleAt30 = Math.round(startAmount + startAmount * (yieldPct / 100) * 30);
  const compoundAt30 = projections[4].amount;
  const compoundAdvantage = compoundAt30 - simpleAt30;
  return send(res, 200, {
    hasData: true,
    yieldPct,
    startAmount,
    reinvestable,
    projections,
    doublingYears,
    simpleAt30,
    compoundAt30,
    compoundAdvantage,
  });
});

R('GET', /^\/app\/projects\/([^/]+)\/lumpsum-suitability$/, async (req, res, m) => {
  const projectId = m[1];
  const proj = db.find('projects', p => p.id === projectId);
  if (!proj) return send(res, 404, { error: 'not_found' });
  const minTicket = Number(proj.minTicket || 1000);
  const maxTicket = Number(proj.maxTicket || 500000);
  const goalAmount = Number(proj.goalAmount || 0);
  const fundedAmount = Number(proj.fundedAmount || 0);
  const remaining = Math.max(0, goalAmount - fundedAmount);
  const fundedPct = goalAmount > 0 ? (fundedAmount / goalAmount) * 100 : 0;
  // Can the project absorb a large lump-sum without becoming too-concentrated?
  let absorption = 'limited';
  if (remaining >= 1000000 && fundedPct < 50) absorption = 'high';
  else if (remaining >= 250000 && fundedPct < 80) absorption = 'medium';
  // Recommendation: lump-sum or DCA?
  let recommendation = 'dca';
  let reason = '';
  if (absorption === 'high' && Number(proj.expectedYield || 0) > 8) {
    recommendation = 'lump_sum_ok';
    reason = 'فرصة كبيرة بعائد جيّد، السعة عالية';
  } else if (fundedPct > 80) {
    recommendation = 'small_lump_sum';
    reason = 'المشروع قارب على الإغلاق، الجزء المتبقّي محدود';
  } else {
    recommendation = 'dca';
    reason = 'وزّع المبلغ على عدّة شهور لتقليل المخاطر';
  }
  return send(res, 200, {
    hasData: true,
    minTicket,
    maxTicket,
    remaining,
    fundedPct: +fundedPct.toFixed(1),
    absorption,
    recommendation,
    reason,
  });
});

R('GET', /^\/app\/projects\/([^/]+)\/screening-check$/, async (req, res, m) => {
  const auth = requireAuth(req, res); if (!auth) return;
  const projectId = m[1];
  const proj = db.find('projects', p => p.id === projectId);
  if (!proj) return send(res, 404, { error: 'not_found' });
  const u = db.find('users', x => x.id === auth.id);
  if (!u) return err(res, 404, 'user_not_found');
  const userScreens = u.negativeScreens || [];
  if (!userScreens.length) return send(res, 200, { hasData: false });
  // Check project category and sponsor against user's screens
  const cat = (proj.category || '').toLowerCase();
  const sponsorId = proj.sponsorId;
  const projectTags = (proj.tags || []).map(t => t.toLowerCase());
  const violations = [];
  for (const screen of userScreens) {
    const key = (screen.key || '').toLowerCase();
    if (screen.type === 'category' && cat === key) {
      violations.push({ screen: screen.label, reason: 'فئة مرفوضة' });
    } else if (screen.type === 'tag' && projectTags.includes(key)) {
      violations.push({ screen: screen.label, reason: 'علامة مرفوضة' });
    } else if (screen.type === 'sponsor' && sponsorId === key) {
      violations.push({ screen: screen.label, reason: 'راعٍ مرفوض' });
    } else if (screen.type === 'keyword' && (proj.title || '').toLowerCase().includes(key) || (proj.titleAr || '').includes(key)) {
      violations.push({ screen: screen.label, reason: 'كلمة مفتاحيّة مرفوضة' });
    }
  }
  return send(res, 200, {
    hasData: true,
    passes: violations.length === 0,
    violations,
    totalScreensChecked: userScreens.length,
  });
});

R('GET', /^\/app\/projects\/([^/]+)\/recession-resilience$/, async (req, res, m) => {
  const projectId = m[1];
  const proj = db.find('projects', p => p.id === projectId);
  if (!proj) return send(res, 404, { error: 'not_found' });
  const defensiveCats = new Set(['healthcare', 'pharma', 'education', 'food', 'water', 'utilities', 'agritech', 'consumer-staples']);
  const cyclicalCats = new Set(['retail', 'tourism', 'real-estate-commercial', 'tech', 'construction', 'luxury', 'entertainment']);
  const cat = proj.category || 'other';
  let categoryScore = 50;
  if (defensiveCats.has(cat)) categoryScore = 85;
  else if (cyclicalCats.has(cat)) categoryScore = 30;
  const checks = [
    { key: 'defensive_sector', label: 'قطاع دفاعي', passed: defensiveCats.has(cat) },
    { key: 'essential_service', label: 'خدمة أساسيّة', passed: !!proj.essentialService || defensiveCats.has(cat) },
    { key: 'long_term_contracts', label: 'عقود طويلة الأجل', passed: !!proj.longTermContracts },
    { key: 'recurring_revenue', label: 'إيرادات متكرّرة', passed: !!proj.recurringRevenue },
    { key: 'low_debt', label: 'ديون منخفضة', passed: Number(proj.debtToEquity || 1) <= 0.5 },
    { key: 'diversified_customers', label: 'عملاء متنوّعون', passed: !!proj.diversifiedCustomers },
    { key: 'cash_reserves', label: 'احتياطي نقدي ٦ شهور+', passed: !!proj.cashReservesGood },
  ];
  const passed = checks.filter(c => c.passed).length;
  const checkScore = (passed / checks.length) * 100;
  const finalScore = Math.round((categoryScore + checkScore) / 2);
  let grade = 'D';
  if (finalScore >= 80) grade = 'A';
  else if (finalScore >= 65) grade = 'B';
  else if (finalScore >= 50) grade = 'C';
  let resilience = 'low';
  if (finalScore >= 70) resilience = 'high';
  else if (finalScore >= 50) resilience = 'medium';
  return send(res, 200, {
    hasData: true,
    score: finalScore,
    grade,
    resilience,
    categoryScore,
    passed,
    total: checks.length,
    checks,
  });
});

R('GET', /^\/app\/projects\/([^/]+)\/goal-suitability$/, async (req, res, m) => {
  const projectId = m[1];
  const proj = db.find('projects', p => p.id === projectId);
  if (!proj) return send(res, 404, { error: 'not_found' });
  const months = Number(proj.durationMonths || 12);
  const expectedYield = Number(proj.expectedYield || 0);
  const minTicket = Number(proj.minTicket || 1000);
  const goalSuitability = {
    emergency: months <= 1 ? 'excellent' : (months <= 3 ? 'good' : 'poor'),
    hajj: months >= 6 && months <= 60 ? 'excellent' : (months <= 6 ? 'good' : 'fair'),
    marriage: months >= 12 && months <= 60 ? 'excellent' : 'fair',
    big_purchase: months >= 6 && months <= 36 ? 'excellent' : 'fair',
    home: months >= 24 && months <= 84 ? 'excellent' : (months >= 12 ? 'good' : 'fair'),
    business: months >= 12 && months <= 60 ? 'excellent' : 'fair',
    education: months >= 60 && expectedYield >= 8 ? 'excellent' : (months >= 12 ? 'good' : 'fair'),
    retirement: months >= 60 && expectedYield >= 9 ? 'excellent' : (months >= 36 ? 'good' : 'fair'),
  };
  const labels = {
    emergency: 'الطوارئ',
    hajj: 'الحجّ',
    marriage: 'الزواج',
    big_purchase: 'مشتريات كبيرة',
    home: 'دفعة بيت',
    business: 'رأس مال مشروع',
    education: 'تعليم الأبناء',
    retirement: 'التقاعد',
  };
  const ratings = Object.entries(goalSuitability).map(([k, v]) => ({
    goal: k,
    label: labels[k],
    rating: v,
  }));
  const bestGoals = ratings.filter(r => r.rating === 'excellent').map(r => r.label);
  return send(res, 200, {
    hasData: true,
    months,
    expectedYield,
    minTicket,
    ratings,
    bestGoals,
  });
});

