R('GET', /^\/app\/projects\/([^/]+)\/moat-rating$/, async (req, res, m) => {
  const projectId = m[1];
  const proj = db.find('projects', p => p.id === projectId);
  if (!proj) return send(res, 404, { error: 'not_found' });
  // Score from 6 checks
  const grossMargin = Number(proj.grossMarginPct || 0);
  const roic = Number(proj.roicPct || 0);
  const revGrowthYears = Number(proj.consecutiveGrowthYears || 0);
  const marketShare = Number(proj.marketSharePct || 0);
  const pricingPowerScore = Number(proj.pricingPowerScore || 0);
  const nps = Number(proj.npsScore || 0);
  const checks = [
    { key: 'margin', label: 'هامش ربح إجمالي ٢٠٪+', passed: grossMargin >= 20 },
    { key: 'roic', label: 'عائد رأس المال ١٥٪+', passed: roic >= 15 },
    { key: 'growth', label: 'نموّ مستمرّ ٥+ سنوات', passed: revGrowthYears >= 5 },
    { key: 'share', label: 'حصّة سوقيّة ٢٠٪+', passed: marketShare >= 20 },
    { key: 'pricing', label: 'قدرة تسعير مثبتة', passed: pricingPowerScore >= 60 },
    { key: 'satisfaction', label: 'رضا عملاء عالٍ', passed: nps >= 50 },
  ];
  const passed = checks.filter(c => c.passed).length;
  const score = proj.moatScore !== undefined ? Number(proj.moatScore) : Math.round((passed / checks.length) * 100);
  let tier = 'none';
  if (score >= 80) tier = 'wide';
  else if (score >= 60) tier = 'narrow';
  else if (score >= 40) tier = 'shallow';
  const moatType = proj.moatType || null;
  const moatTypeLabels = {
    intangible: '🎨 أصول غير ملموسة',
    switching: '🔒 تكاليف تبديل',
    network: '🌐 تأثير شبكة',
    cost: '💰 كفاءة تكلفة',
    scale: '📏 نطاق فعّال',
    reputation: '⭐ سمعة حاكمة',
    toll: '🌉 رسوم منخفضة',
  };
  return send(res, 200, {
    hasData: true,
    score,
    tier,
    passed,
    total: checks.length,
    checks,
    moatType,
    moatTypeLabel: moatType ? moatTypeLabels[moatType] : null,
  });
});

R('GET', /^\/app\/projects\/([^/]+)\/liquidity-tier$/, async (req, res, m) => {
  const projectId = m[1];
  const proj = db.find('projects', p => p.id === projectId);
  if (!proj) return send(res, 404, { error: 'not_found' });
  const months = Number(proj.durationMonths || 0);
  if (!months) return send(res, 200, { hasData: false });
  let tier = 4;
  let tierLabel = '';
  let icon = '';
  let yieldRange = '';
  if (months <= 1) {
    tier = 1; tierLabel = 'فوريّة'; icon = '💵'; yieldRange = '٢–٤٪';
  } else if (months <= 6) {
    tier = 2; tierLabel = 'قصيرة المدى'; icon = '📊'; yieldRange = '٤–٧٪';
  } else if (months <= 36) {
    tier = 3; tierLabel = 'متوسّطة المدى'; icon = '🏗'; yieldRange = '٧–١١٪';
  } else {
    tier = 4; tierLabel = 'طويلة المدى'; icon = '🏖'; yieldRange = '١٠–١٥٪';
  }
  const exitChannels = [];
  if (proj.sponsorBuybackEnabled) exitChannels.push('شراء الراعي');
  if (proj.secondaryMarketEnabled !== false) exitChannels.push('السوق الثانوي');
  if (proj.voluntaryWindowEnabled !== false) exitChannels.push('نوافذ طوعيّة');
  return send(res, 200, {
    hasData: true,
    tier,
    tierLabel,
    icon,
    months,
    yieldRange,
    exitChannels,
    hasEarlyExit: exitChannels.length > 0,
  });
});

R('GET', /^\/app\/projects\/([^/]+)\/correlation-matrix$/, async (req, res, m) => {
  const auth = requireAuth(req, res); if (!auth) return;
  const projectId = m[1];
  const proj = db.find('projects', p => p.id === projectId);
  if (!proj) return send(res, 404, { error: 'not_found' });
  const myInvestments = db.all('investments').filter(i => i.userId === auth.id && i.projectId !== projectId);
  if (!myInvestments.length) return send(res, 200, { hasData: false });
  const projectsById = new Map(db.all('projects').map(p => [p.id, p]));
  const corrMatrix = { 'real-estate': { 'real-estate': 0.85, 'tech': 0.15, 'healthcare': 0.2, 'agritech': 0.25, 'solar': 0.1, 'industrial': 0.4, 'retail': 0.55, 'education': 0.15 },
    'tech': { 'tech': 0.8, 'retail': 0.5, 'industrial': 0.45 },
    'healthcare': { 'healthcare': 0.75, 'education': 0.4, 'pharma': 0.7 },
    'solar': { 'solar': 0.85, 'water': 0.45, 'renewables': 0.75 },
    'agritech': { 'agritech': 0.8, 'water': 0.5, 'food': 0.6 },
    'retail': { 'retail': 0.85, 'tourism': 0.55, 'real-estate': 0.55 },
    'industrial': { 'industrial': 0.8, 'real-estate': 0.4 },
  };
  const myCorrs = [];
  for (const inv of myInvestments) {
    const p = projectsById.get(inv.projectId);
    if (!p) continue;
    const cat1 = proj.category;
    const cat2 = p.category;
    let corr = 0.1;
    if (cat1 === cat2) corr = 0.85;
    else if (corrMatrix[cat1]?.[cat2] !== undefined) corr = corrMatrix[cat1][cat2];
    else if (corrMatrix[cat2]?.[cat1] !== undefined) corr = corrMatrix[cat2][cat1];
    myCorrs.push({
      projectName: p.titleAr || p.title || p.id,
      category: cat2,
      correlation: corr,
      amount: Number(inv.amount || 0),
    });
  }
  if (!myCorrs.length) return send(res, 200, { hasData: false });
  const total = myCorrs.reduce((s, c) => s + c.amount, 0);
  const weightedAvg = total > 0 ? myCorrs.reduce((s, c) => s + (c.correlation * c.amount), 0) / total : 0;
  let verdict = 'good';
  if (weightedAvg >= 0.7) verdict = 'high';
  else if (weightedAvg >= 0.4) verdict = 'medium';
  return send(res, 200, {
    hasData: true,
    weightedAvgCorrelation: +weightedAvg.toFixed(2),
    verdict,
    samples: myCorrs.length,
    highest: myCorrs.sort((a, b) => b.correlation - a.correlation)[0],
    lowest: myCorrs.sort((a, b) => a.correlation - b.correlation)[0],
  });
});

R('GET', /^\/app\/projects\/([^/]+)\/cycle-sensitivity$/, async (req, res, m) => {
  const projectId = m[1];
  const proj = db.find('projects', p => p.id === projectId);
  if (!proj) return send(res, 404, { error: 'not_found' });
  const cat = proj.category || 'other';
  const cyclical = ['retail', 'tourism', 'real-estate-commercial', 'industrial', 'construction', 'tech'];
  const defensive = ['healthcare', 'education', 'utilities', 'food', 'water', 'pharma'];
  const counter = ['gold', 'pawn', 'discount-retail'];
  let sensitivity = 'neutral';
  let beta = 1.0;
  if (cyclical.includes(cat)) { sensitivity = 'cyclical'; beta = 1.4; }
  else if (defensive.includes(cat)) { sensitivity = 'defensive'; beta = 0.6; }
  else if (counter.includes(cat)) { sensitivity = 'counter-cyclical'; beta = -0.3; }
  const expectedReturns = {
    expansion: sensitivity === 'cyclical' ? 'عالي' : (sensitivity === 'defensive' ? 'متوسّط' : 'منخفض'),
    peak: sensitivity === 'cyclical' ? 'متراجع' : (sensitivity === 'defensive' ? 'متوسّط' : 'مستقرّ'),
    contraction: sensitivity === 'cyclical' ? 'منخفض' : (sensitivity === 'defensive' ? 'مستقرّ' : 'متحسّن'),
    recovery: sensitivity === 'cyclical' ? 'عالي' : (sensitivity === 'defensive' ? 'متوسّط' : 'منخفض'),
  };
  const labels = {
    cyclical: { txt: '📈 دورية', desc: 'تستفيد من النموّ وتعاني في الركود' },
    defensive: { txt: '🛡 دفاعيّة', desc: 'مستقرّة في كلّ الدورات' },
    'counter-cyclical': { txt: '↩ مضادّة للدورة', desc: 'تستفيد من الأزمات' },
    neutral: { txt: '➖ محايدة', desc: 'حساسيّة منخفضة للدورة' },
  };
  return send(res, 200, {
    hasData: true,
    sensitivity,
    label: labels[sensitivity].txt,
    description: labels[sensitivity].desc,
    beta,
    expectedReturns,
    bestPhase: sensitivity === 'cyclical' ? 'recovery+expansion' : (sensitivity === 'defensive' ? 'all' : 'contraction'),
  });
});

R('GET', /^\/app\/projects\/([^/]+)\/fx-exposure$/, async (req, res, m) => {
  const projectId = m[1];
  const proj = db.find('projects', p => p.id === projectId);
  if (!proj) return send(res, 404, { error: 'not_found' });
  const currency = (proj.currency || 'SAR').toUpperCase();
  const stableCodes = new Set(['SAR', 'USD', 'AED', 'BHD', 'OMR', 'QAR', 'KWD']);
  const isStable = stableCodes.has(currency);
  const volatility = proj.fxVolatility || (isStable ? 'low' : 'medium');
  const rateToSar = Number(proj.fxRateToSar) || 1;
  const hedgeAvailable = !!proj.fxHedgeAvailable;
  const hedgeCostPct = Number(proj.fxHedgeCostPct) || 0;
  let riskLevel = 'low';
  if (currency === 'SAR') riskLevel = 'none';
  else if (isStable) riskLevel = 'low';
  else if (volatility === 'high') riskLevel = 'high';
  else if (volatility === 'medium') riskLevel = 'medium';
  return send(res, 200, {
    hasData: true,
    currency,
    isStable,
    riskLevel,
    volatility,
    rateToSar,
    hedgeAvailable,
    hedgeCostPct,
  });
});

R('GET', /^\/app\/projects\/([^/]+)\/business-continuity$/, async (req, res, m) => {
  const projectId = m[1];
  const proj = db.find('projects', p => p.id === projectId);
  if (!proj) return send(res, 404, { error: 'not_found' });
  const sponsorId = proj.sponsorId;
  if (!sponsorId) return send(res, 200, { hasData: false });
  const sponsor = db.find('sponsors', s => s.id === sponsorId) || db.find('users', u => u.id === sponsorId);
  if (!sponsor) return send(res, 200, { hasData: false });
  const checks = [
    { key: 'bcpDocument', label: 'وثيقة استمراريّة معتمدة', passed: !!sponsor.hasBcpDocument },
    { key: 'lastDrill', label: 'تمرين خلال آخر ١٢ شهر', passed: sponsor.lastBcpDrillAt ? (Date.now() - new Date(sponsor.lastBcpDrillAt).getTime()) < 365 * 86400000 : false },
    { key: 'backupSite', label: 'موقع عمل بديل', passed: !!sponsor.bcpBackupSite },
    { key: 'insurance', label: 'تأمين شامل للأصول', passed: !!sponsor.bcpInsurance },
    { key: 'keyManRedundancy', label: 'صلاحيّات بديلة للموظّفين', passed: !!sponsor.bcpKeyManRedundancy },
    { key: 'recoveryTime', label: 'هدف استرداد < ٢٤ ساعة', passed: (sponsor.bcpRecoveryHours || 999) <= 24 },
    { key: 'communicationPlan', label: 'خطّة اتّصال للمستثمرين', passed: !!sponsor.bcpCommPlan },
  ];
  const passed = checks.filter(c => c.passed).length;
  const score = Math.round((passed / checks.length) * 100);
  let grade = 'D';
  if (score >= 85) grade = 'A';
  else if (score >= 70) grade = 'B';
  else if (score >= 50) grade = 'C';
  return send(res, 200, {
    hasData: true,
    score,
    grade,
    passed,
    total: checks.length,
    checks,
    lastDrillAt: sponsor.lastBcpDrillAt || null,
  });
});

