  if (proj.category === 'water') { sdgs.push({ num: 6, label: 'مياه نظيفة' }); sdgs.push({ num: 14, label: 'الحياة المائيّة' }); }
  if (proj.category === 'agritech') { sdgs.push({ num: 2, label: 'لا للجوع' }); sdgs.push({ num: 15, label: 'الحياة البرّيّة' }); }
  if (proj.category === 'green-buildings') { sdgs.push({ num: 11, label: 'مدن مستدامة' }); }
  if (proj.category === 'education') { sdgs.push({ num: 4, label: 'تعليم جيّد' }); }
