R('GET', /^\/app\/projects\/([^/]+)\/inflation-adjusted-return$/, async (req, res, m) => {
  const projectId = m[1];
  const proj = db.find('projects', p => p.id === projectId);
  if (!proj) return send(res, 404, { error: 'not_found' });
  const nominalYield = Number(proj.expectedYield || 0);
  if (!nominalYield) return send(res, 200, { hasData: false });
  const annualInflation = 3.5;
  const realYield = +(((1 + nominalYield / 100) / (1 + annualInflation / 100) - 1) * 100).toFixed(2);
  const months = Number(proj.durationMonths || 0) || 12;
  const years = months / 12;
  const nominal10k = +(10000 * Math.pow(1 + nominalYield / 100, years)).toFixed(0);
  const real10k = +(10000 * Math.pow(1 + realYield / 100, years)).toFixed(0);
  const inflationDrag = nominal10k - real10k;
  let verdict = 'flat';
  if (realYield >= 5) verdict = 'crushes_inflation';
  else if (realYield >= 2) verdict = 'beats_inflation';
  else if (realYield >= 0) verdict = 'matches_inflation';
  else verdict = 'loses_to_inflation';
  return send(res, 200, {
    hasData: true,
    nominalYield,
    annualInflation,
    realYield,
    durationYears: +years.toFixed(1),
    nominalEnd10k: nominal10k,
    realEnd10k: real10k,
    inflationDrag,
    verdict,
  });
});

R('GET', /^\/app\/projects\/([^/]+)\/yield-history$/, async (req, res, m) => {
  const projectId = m[1];
  const proj = db.find('projects', p => p.id === projectId);
  if (!proj) return send(res, 404, { error: 'not_found' });
  const sponsorId = proj.sponsorId;
  if (!sponsorId) return send(res, 200, { hasData: false });
  const sponsorProjects = db.all('projects').filter(p => p.sponsorId === sponsorId && p.id !== projectId && (p.status === 'completed' || p.actualYield));
  if (sponsorProjects.length < 2) return send(res, 200, { hasData: false });
  const promised = [];
  const actual = [];
  const variances = [];
  for (const p of sponsorProjects) {
    const promYield = Number(p.expectedYield || 0);
    const actYield = Number(p.actualYield || promYield);
    if (promYield > 0) {
      promised.push(promYield);
      actual.push(actYield);
      variances.push(+(actYield - promYield).toFixed(2));
    }
  }
  if (!promised.length) return send(res, 200, { hasData: false });
  const avg = arr => arr.reduce((a, b) => a + b, 0) / arr.length;
  const avgPromised = +avg(promised).toFixed(2);
  const avgActual = +avg(actual).toFixed(2);
  const avgVariance = +avg(variances).toFixed(2);
  const beatPromise = variances.filter(v => v >= 0).length;
  let reliability = 'unproven';
  if (beatPromise / variances.length >= 0.9 && avgVariance >= -0.5) reliability = 'excellent';
  else if (beatPromise / variances.length >= 0.7 && avgVariance >= -1.0) reliability = 'good';
  else if (beatPromise / variances.length >= 0.5) reliability = 'mixed';
  else reliability = 'poor';
  return send(res, 200, {
    hasData: true,
    samples: promised.length,
    avgPromisedYield: avgPromised,
    avgActualYield: avgActual,
    avgVariance,
    beatPromisePct: Math.round((beatPromise / variances.length) * 100),
    reliability,
  });
});

R('GET', /^\/app\/projects\/([^/]+)\/cashflow-projection$/, async (req, res, m) => {
  const projectId = m[1];
  const proj = db.find('projects', p => p.id === projectId);
  if (!proj) return send(res, 404, { error: 'not_found' });
  const goal = Number(proj.goalAmount || 0);
  const yearlyYield = Number(proj.expectedYield || 0);
  const months = Number(proj.durationMonths || 0);
  if (!goal || !yearlyYield || !months) return send(res, 200, { hasData: false });
  const monthlyYield = yearlyYield / 12 / 100;
  const totalProfit = goal * (yearlyYield / 100) * (months / 12);
  const cashflows = [];
  const distributionScheme = proj.distributionScheme || 'monthly';
  if (distributionScheme === 'monthly') {
    const monthlyPay = +(totalProfit / months).toFixed(2);
    for (let i = 1; i <= months; i++) {
      cashflows.push({
        month: i,
        profit: monthlyPay,
        capitalReturn: i === months ? goal : 0,
        total: i === months ? monthlyPay + goal : monthlyPay,
      });
    }
  } else if (distributionScheme === 'quarterly') {
    const quarterly = +(totalProfit / Math.ceil(months / 3)).toFixed(2);
    for (let i = 1; i <= months; i++) {
      const isPay = i % 3 === 0 || i === months;
      cashflows.push({
        month: i,
        profit: isPay ? quarterly : 0,
        capitalReturn: i === months ? goal : 0,
        total: (isPay ? quarterly : 0) + (i === months ? goal : 0),
      });
    }
  } else {
    for (let i = 1; i <= months; i++) {
      cashflows.push({
        month: i,
        profit: i === months ? +totalProfit.toFixed(2) : 0,
        capitalReturn: i === months ? goal : 0,
        total: i === months ? totalProfit + goal : 0,
      });
    }
  }
  const peakMonth = cashflows.reduce((a, b) => b.total > a.total ? b : a, cashflows[0]);
  return send(res, 200, {
    hasData: true,
    distributionScheme,
    totalProfit: +totalProfit.toFixed(2),
    totalReturn: +(totalProfit + goal).toFixed(2),
    months,
    cashflows,
    peakMonth: peakMonth.month,
    peakAmount: peakMonth.total,
  });
});

R('GET', /^\/app\/projects\/([^/]+)\/peer-comparison$/, async (req, res, m) => {
  const projectId = m[1];
  const proj = db.find('projects', p => p.id === projectId);
  if (!proj) return send(res, 404, { error: 'not_found' });
  const category = proj.category;
  if (!category) return send(res, 200, { hasData: false });
  const peers = db.all('projects').filter(p => p.category === category && p.id !== projectId && (p.status === 'active' || p.status === 'funded' || p.status === 'completed'));
  if (peers.length < 2) return send(res, 200, { hasData: false });
  const myYield = Number(proj.expectedYield || 0);
  const myDuration = Number(proj.durationMonths || 0);
  const myMin = Number(proj.minTicket || 0);
  const peerYields = peers.map(p => Number(p.expectedYield || 0)).filter(y => y > 0);
  const peerDurations = peers.map(p => Number(p.durationMonths || 0)).filter(d => d > 0);
  const peerMins = peers.map(p => Number(p.minTicket || 0)).filter(m => m > 0);
  const avg = arr => arr.length ? arr.reduce((a, b) => a + b, 0) / arr.length : 0;
  const median = arr => {
    if (!arr.length) return 0;
    const s = [...arr].sort((a, b) => a - b);
    return s.length % 2 === 0 ? (s[s.length / 2 - 1] + s[s.length / 2]) / 2 : s[Math.floor(s.length / 2)];
  };
  const percentile = (val, arr) => arr.length ? Math.round((arr.filter(v => v <= val).length / arr.length) * 100) : null;
  return send(res, 200, {
    hasData: true,
    category,
    peerCount: peers.length,
    yield: {
      mine: myYield,
      peerAvg: +avg(peerYields).toFixed(2),
      peerMedian: +median(peerYields).toFixed(2),
      percentile: percentile(myYield, peerYields),
    },
    duration: {
      mine: myDuration,
      peerAvg: Math.round(avg(peerDurations)),
      peerMedian: Math.round(median(peerDurations)),
      percentile: percentile(myDuration, peerDurations),
    },
    minTicket: {
      mine: myMin,
      peerAvg: Math.round(avg(peerMins)),
      peerMedian: Math.round(median(peerMins)),
    },
  });
});

R('GET', /^\/app\/projects\/([^/]+)\/document-accessibility$/, async (req, res, m) => {
  const projectId = m[1];
  const proj = db.find('projects', p => p.id === projectId);
  if (!proj) return send(res, 404, { error: 'not_found' });
  const docs = db.all('projectDocuments').filter(d => d.projectId === projectId);
  const formats = { pdf: 0, plainText: 0, audioMp3: 0, easyRead: 0, largPrint: 0 };
  for (const d of docs) {
    if (d.format === 'pdf' || (d.url || '').endsWith('.pdf')) formats.pdf++;
    if (d.format === 'txt' || d.plainTextAvailable) formats.plainText++;
    if (d.format === 'mp3' || d.audioAvailable) formats.audioMp3++;
    if (d.easyReadAvailable) formats.easyRead++;
    if (d.largePrintAvailable) formats.largPrint++;
  }
  const totalDocs = docs.length;
  const accessibilityScore = totalDocs === 0 ? 0 : Math.round(
    ((formats.plainText + formats.audioMp3 + formats.easyRead + formats.largPrint) / (totalDocs * 4)) * 100
  );
  let grade = 'D';
  if (accessibilityScore >= 80) grade = 'A';
  else if (accessibilityScore >= 60) grade = 'B';
  else if (accessibilityScore >= 40) grade = 'C';
  return send(res, 200, {
    hasData: totalDocs > 0,
    totalDocs,
    formats,
    accessibilityScore,
    grade,
  });
});

R('GET', /^\/app\/projects\/([^/]+)\/ticket-distribution$/, async (req, res, m) => {
  const projectId = m[1];
  const proj = db.find('projects', p => p.id === projectId);
  if (!proj) return send(res, 404, { error: 'not_found' });
  const investments = db.all('investments').filter(i => i.projectId === projectId && (i.status === 'confirmed' || i.status === 'funded' || !i.status));
  if (!investments.length) return send(res, 200, { hasData: false });
  const buckets = [
    { key: '0-1k', label: 'أقلّ من ١ ألف', max: 1000, count: 0, sum: 0 },
    { key: '1k-5k', label: '١–٥ آلاف', max: 5000, count: 0, sum: 0 },
    { key: '5k-10k', label: '٥–١٠ آلاف', max: 10000, count: 0, sum: 0 },
    { key: '10k-25k', label: '١٠–٢٥ ألف', max: 25000, count: 0, sum: 0 },
    { key: '25k-50k', label: '٢٥–٥٠ ألف', max: 50000, count: 0, sum: 0 },
    { key: '50k+', label: '+٥٠ ألف', max: Infinity, count: 0, sum: 0 },
  ];
  let total = 0, totalSum = 0;
  for (const inv of investments) {
    const amt = Number(inv.amount || 0);
    if (amt <= 0) continue;
    total++;
    totalSum += amt;
    for (const b of buckets) {
      if (amt <= b.max) { b.count++; b.sum += amt; break; }
    }
  }
  if (total === 0) return send(res, 200, { hasData: false });
  const amounts = investments.map(i => Number(i.amount || 0)).filter(a => a > 0).sort((a, b) => a - b);
  const medianAmount = amounts.length % 2 === 0 ? (amounts[amounts.length / 2 - 1] + amounts[amounts.length / 2]) / 2 : amounts[Math.floor(amounts.length / 2)];
  const avgAmount = totalSum / total;
  return send(res, 200, {
    hasData: true,
    totalInvestors: total,
    avgAmount: Math.round(avgAmount),
    medianAmount: Math.round(medianAmount),
    buckets,
  });
});

R('GET', /^\/app\/projects\/([^/]+)\/liquidity-window$/, async (req, res, m) => {
  const projectId = m[1];
  const proj = db.find('projects', p => p.id === projectId);
  if (!proj) return send(res, 404, { error: 'not_found' });
  const launchedAt = proj.launchedAt || proj.fundedAt || proj.createdAt;
  if (!launchedAt) return send(res, 200, { hasData: false });
  const start = new Date(launchedAt).getTime();
  if (!start || Number.isNaN(start)) return send(res, 200, { hasData: false });
  const now = Date.now();
  const sixMonthsMs = 180 * 86400000;
  let nextWindow = start;
  while (nextWindow <= now) nextWindow += sixMonthsMs;
  const daysToWindow = Math.ceil((nextWindow - now) / 86400000);
  const lastWindow = nextWindow - sixMonthsMs;
  const daysSinceLast = Math.floor((now - lastWindow) / 86400000);
  let secondaryStatus = 'closed';
  const dayOfQuarter = Math.floor((now - new Date(now).setMonth(Math.floor(new Date(now).getMonth() / 3) * 3, 1)) / 86400000);
  if (dayOfQuarter < 14) secondaryStatus = 'open';
  else if (dayOfQuarter > 75) secondaryStatus = 'opening_soon';
  const sponsorBuyback = !!proj.sponsorBuybackEnabled;
  return send(res, 200, {
    hasData: true,
    nextVoluntaryWindow: new Date(nextWindow).toISOString(),
    daysToWindow,
    daysSinceLast,
    secondaryStatus,
    sponsorBuybackAvailable: sponsorBuyback,
    voluntaryMaxPct: 20,
  });
});

R('GET', /^\/app\/projects\/([^/]+)\/sponsor-tenure$/, async (req, res, m) => {
  const projectId = m[1];
  const proj = db.find('projects', p => p.id === projectId);
  if (!proj) return send(res, 404, { error: 'not_found' });
  const sponsorId = proj.sponsorId;
  if (!sponsorId) return send(res, 200, { hasData: false });
  const sponsor = db.find('sponsors', s => s.id === sponsorId) || db.find('users', u => u.id === sponsorId);
  if (!sponsor) return send(res, 200, { hasData: false });
  const joinedAt = sponsor.joinedAt || sponsor.createdAt;
  if (!joinedAt) return send(res, 200, { hasData: false });
  const joined = new Date(joinedAt).getTime();
  const now = Date.now();
  const daysOn = Math.floor((now - joined) / 86400000);
  const monthsOn = Math.floor(daysOn / 30);
  const yearsOn = +(daysOn / 365.25).toFixed(1);
  const sponsorProjects = db.all('projects').filter(p => p.sponsorId === sponsorId);
  const completed = sponsorProjects.filter(p => p.status === 'completed' || p.status === 'closed').length;
  const active = sponsorProjects.filter(p => p.status === 'active' || p.status === 'funded').length;
  let tier = 'new';
  if (yearsOn >= 5 && completed >= 10) tier = 'veteran';
  else if (yearsOn >= 3 && completed >= 5) tier = 'established';
  else if (yearsOn >= 1 && completed >= 2) tier = 'experienced';
  else if (yearsOn >= 0.5) tier = 'developing';
  return send(res, 200, {
    hasData: true,
    daysOn,
    monthsOn,
    yearsOn,
    tier,
    totalProjects: sponsorProjects.length,
    completedProjects: completed,
    activeProjects: active,
    joinedAt,
  });
});

R('GET', /^\/app\/projects\/([^/]+)\/payout-reliability$/, async (req, res, m) => {
  const projectId = m[1];
  const proj = db.find('projects', p => p.id === projectId);
  if (!proj) return send(res, 404, { error: 'not_found' });
  const sponsorId = proj.sponsorId;
  if (!sponsorId) return send(res, 200, { hasData: false });
  const sponsorProjects = db.all('projects').filter(p => p.sponsorId === sponsorId && p.id !== projectId);
  const allPayouts = db.all('payouts').filter(p => sponsorProjects.some(sp => sp.id === p.projectId));
  if (!allPayouts.length) return send(res, 200, { hasData: false });
  let onTime = 0, late1to7 = 0, late8plus = 0, missed = 0;
  let totalDaysLate = 0, lateCount = 0;
  for (const p of allPayouts) {
    if (p.status === 'missed') { missed++; continue; }
    if (!p.expectedDate || !p.actualDate) continue;
    const exp = new Date(p.expectedDate).getTime();
    const act = new Date(p.actualDate).getTime();
    if (!exp || !act) continue;
    const daysLate = (act - exp) / 86400000;
    if (daysLate <= 0) onTime++;
    else if (daysLate <= 7) { late1to7++; totalDaysLate += daysLate; lateCount++; }
    else { late8plus++; totalDaysLate += daysLate; lateCount++; }
  }
  const total = onTime + late1to7 + late8plus + missed;
  if (total === 0) return send(res, 200, { hasData: false });
  const onTimePct = Math.round((onTime / total) * 100);
  const avgDaysLate = lateCount > 0 ? +(totalDaysLate / lateCount).toFixed(1) : 0;
  let grade = 'A';
  if (onTimePct >= 95) grade = 'A+';
  else if (onTimePct >= 90) grade = 'A';
  else if (onTimePct >= 80) grade = 'B';
  else if (onTimePct >= 70) grade = 'C';
  else grade = 'D';
  return send(res, 200, {
    hasData: true,
    grade,
    onTimePct,
    totalPayouts: total,
    onTime,
    late1to7,
    late8plus,
    missed,
    avgDaysLate,
    sponsorPriorDeals: sponsorProjects.length,
  });
});

R('GET', /^\/app\/projects\/([^/]+)\/deal-pace$/, async (req, res, m) => {
  const projectId = m[1];
  const proj = db.find('projects', p => p.id === projectId);
  if (!proj) return send(res, 404, { error: 'not_found' });
  const launchedAt = proj.launchedAt || proj.createdAt;
  if (!launchedAt) return send(res, 200, { hasData: false });
  const start = new Date(launchedAt).getTime();
  if (!start || Number.isNaN(start)) return send(res, 200, { hasData: false });
  const now = Date.now();
  const daysLive = Math.max(1, Math.floor((now - start) / 86400000));
  const goal = Number(proj.goalAmount || 0);
  const funded = Number(proj.fundedAmount || 0);
  if (goal < 1) return send(res, 200, { hasData: false });
  const avgPerDay = funded / daysLive;
  const remaining = Math.max(0, goal - funded);
  const daysToClose = avgPerDay > 0 ? Math.ceil(remaining / avgPerDay) : null;
  const expectedCloseDate = daysToClose !== null ? new Date(now + daysToClose * 86400000).toISOString() : null;
  let momentum = 'normal';
  const fundedPct = (funded / goal) * 100;
  if (fundedPct >= 80 && daysLive <= 14) momentum = 'hot';
  else if (fundedPct >= 50 && daysLive <= 21) momentum = 'fast';
  else if (daysLive > 60 && fundedPct < 50) momentum = 'slow';
  return send(res, 200, {
    hasData: true,
    daysLive,
    fundedPct: Math.round(fundedPct),
    avgPerDay: Math.round(avgPerDay),
    daysToClose,
    expectedCloseDate,
    momentum,
  });
});

