R('GET', /^\/app\/projects\/([^/]+)\/payout-schedule$/, async (req, res, m) => {
  const projectId = m[1];
  const proj = db.find('projects', p => p.id === projectId);
  if (!proj) return send(res, 404, { error: 'not_found' });
  const closingAt = proj.closingAt || proj.fundingClosesAt || proj.estimatedClosingAt || proj.fundedAt;
  if (!closingAt) return send(res, 200, { hasData: false });
  const start = new Date(closingAt).getTime();
  if (!start || Number.isNaN(start)) return send(res, 200, { hasData: false });
  const months = Number(proj.durationMonths || 12);
  const freq = proj.payoutFrequency || proj.distributionFrequency || 'quarterly';
  const stepDays = { monthly: 30, quarterly: 91, semiannual: 182, annual: 365 }[freq] || 91;
  const periods = Math.max(1, Math.floor((months * 30) / stepDays));
  const schedule = [];
  for (let i = 1; i <= Math.min(periods, 24); i++) {
    const date = start + i * stepDays * 86400000;
    schedule.push({
      seq: i,
      date: new Date(date).toISOString(),
      isFinal: i === periods,
      isProfit: i < periods,
      isPrincipal: i === periods,
    });
  }
  const maturity = start + months * 30 * 86400000;
  return send(res, 200, {
    hasData: true,
    closingAt: new Date(start).toISOString(),
    maturityAt: new Date(maturity).toISOString(),
    durationMonths: months,
    frequency: freq,
    periodsTotal: periods,
    schedule,
  });
});

R('GET', /^\/app\/projects\/([^/]+)\/total-return-preview$/, async (req, res, m) => {
  const projectId = m[1];
  const proj = db.find('projects', p => p.id === projectId);
  if (!proj) return send(res, 404, { error: 'not_found' });
  const url = new URL(req.url, 'http://x');
  const ticket = Math.max(100, Math.min(1000000, Number(url.searchParams.get('amount')) || 10000));
  const annual = Number(proj.expectedReturn || 0);
  const months = Number(proj.durationMonths || 12);
  if (annual <= 0 || months <= 0) return send(res, 200, { hasData: false });
  const simpleProfit = +(ticket * annual / 100 * (months / 12)).toFixed(2);
  const totalSimple = +(ticket + simpleProfit).toFixed(2);
  const monthly = +(simpleProfit / months).toFixed(2);
  const samaFee = Math.min(simpleProfit * 0.05, ticket * 0.02);
  const netProfit = +(simpleProfit - samaFee).toFixed(2);
  return send(res, 200, {
    hasData: true,
    ticket,
    months,
    annualPct: annual,
    simpleProfit,
    totalSimple,
    monthlyProfit: monthly,
    estimatedFee: +samaFee.toFixed(2),
    netProfit,
    netAnnualPct: +((netProfit / ticket) * (12 / months) * 100).toFixed(1),
  });
});

R('GET', /^\/app\/projects\/([^/]+)\/first-payout-eta$/, async (req, res, m) => {
  const projectId = m[1];
  const proj = db.find('projects', p => p.id === projectId);
  if (!proj) return send(res, 404, { error: 'not_found' });
  const closingAt = proj.closingAt || proj.fundingClosesAt || proj.estimatedClosingAt || proj.fundedAt;
  if (!closingAt) return send(res, 200, { hasData: false });
  const close = new Date(closingAt).getTime();
  if (!close || Number.isNaN(close)) return send(res, 200, { hasData: false });
  const freqMap = { monthly: 30, quarterly: 91, semiannual: 182, annual: 365, atMaturity: Number(proj.durationMonths || 12) * 30 };
  const freq = proj.payoutFrequency || proj.distributionFrequency || 'quarterly';
  const daysToFirst = freqMap[freq] || 91;
  const first = close + daysToFirst * 86400000;
  const now = Date.now();
  return send(res, 200, {
    hasData: true,
    closingAt: new Date(close).toISOString(),
    firstPayoutAt: new Date(first).toISOString(),
    daysFromNow: Math.ceil((first - now) / 86400000),
    isPast: first < now,
    frequency: freq,
  });
});

R('GET', /^\/app\/projects\/([^/]+)\/min-ticket-context$/, async (req, res, m) => {
  const projectId = m[1];
  const proj = db.find('projects', p => p.id === projectId);
  if (!proj) return send(res, 404, { error: 'not_found' });
  const myMin = Number(proj.minTicket || proj.minInvestment || 1000);
  const category = (proj.category || proj.sector || '').toString().toLowerCase();
  const peers = db.filter('projects', p => {
    if (p.id === proj.id) return false;
    const cat = (p.category || p.sector || '').toString().toLowerCase();
    return cat === category && (p.minTicket || p.minInvestment);
  });
  if (peers.length < 2) return send(res, 200, { hasData: false });
  const peerMins = peers.map(p => Number(p.minTicket || p.minInvestment)).filter(v => v > 0).sort((a, b) => a - b);
  const median = peerMins[Math.floor(peerMins.length / 2)];
  const avg = Math.round(peerMins.reduce((s, v) => s + v, 0) / peerMins.length);
  let position = 'average';
  if (myMin <= peerMins[0]) position = 'lowest';
  else if (myMin >= peerMins[peerMins.length - 1]) position = 'highest';
  else if (myMin < median) position = 'below_median';
  else if (myMin > median) position = 'above_median';
  return send(res, 200, {
    hasData: true,
    myMin,
    category: category || 'الفئة',
    peerCount: peers.length,
    peerMin: peerMins[0],
    peerMax: peerMins[peerMins.length - 1],
    peerMedian: median,
    peerAvg: avg,
    position,
  });
});

R('GET', /^\/app\/projects\/([^/]+)\/irr-breakdown$/, async (req, res, m) => {
  const projectId = m[1];
  const proj = db.find('projects', p => p.id === projectId);
  if (!proj) return send(res, 404, { error: 'not_found' });
  const simpleAnnualPct = Number(proj.expectedReturn || 0);
  const durationMonths = Number(proj.durationMonths || 12);
  const distribution = proj.payoutFrequency || proj.distributionFrequency || 'quarterly';
  const freqMap = { monthly: 12, quarterly: 4, semiannual: 2, annual: 1, atMaturity: 1 };
  const periodsPerYear = freqMap[distribution] || 4;
  // Cumulative simple return over deal life
  const simpleCumPct = +(simpleAnnualPct * (durationMonths / 12)).toFixed(2);
  // IRR if distributions are reinvested at same rate
  const rPeriod = simpleAnnualPct / 100 / periodsPerYear;
  const totalPeriods = (durationMonths / 12) * periodsPerYear;
  const irrCumPct = +(((Math.pow(1 + rPeriod, totalPeriods) - 1) * 100)).toFixed(2);
  const irrAnnualizedPct = durationMonths > 0
    ? +(((Math.pow(1 + irrCumPct / 100, 12 / durationMonths) - 1) * 100)).toFixed(2)
    : 0;
  return send(res, 200, {
    hasData: simpleAnnualPct > 0,
    simpleAnnualPct,
    simpleCumPct,
    irrCumPct,
    irrAnnualizedPct,
    durationMonths,
    distribution,
    boostPct: +(irrCumPct - simpleCumPct).toFixed(2),
  });
});

