R('GET', /^\/app\/projects\/([^/]+)\/secondary-market$/, async (req, res, m) => {
  const projectId = m[1];
  const proj = db.find('projects', p => p.id === projectId);
  if (!proj) return send(res, 404, { error: 'not_found' });
  const minHoldDays = Number(proj.minHoldDays || 90);
  const secondaryEnabled = proj.secondaryMarketEnabled !== false;
  const fundedAt = proj.fundedAt || proj.closingAt;
  let openDate = null, daysUntilOpen = null, isOpen = false;
  if (fundedAt) {
    const t = new Date(fundedAt).getTime();
    if (t && !Number.isNaN(t)) {
      const open = t + minHoldDays * 86400000;
      openDate = new Date(open).toISOString();
      daysUntilOpen = Math.ceil((open - Date.now()) / 86400000);
      isOpen = daysUntilOpen <= 0;
    }
  }
  return send(res, 200, {
    hasData: true,
    secondaryEnabled,
    minHoldDays,
    openDate, daysUntilOpen, isOpen,
    feePct: Number(proj.secondaryFeePct || 1),
  });
});

R('GET', /^\/app\/projects\/([^/]+)\/cancellation-window$/, async (req, res, m) => {
  const projectId = m[1];
  const proj = db.find('projects', p => p.id === projectId);
  if (!proj) return send(res, 404, { error: 'not_found' });
  const windowDays = Number(proj.cancellationWindowDays || 14);
  const closingAt = proj.closingAt || proj.fundingClosesAt || proj.estimatedClosingAt;
  const now = Date.now();
  let deadline = null;
  if (closingAt) {
    const close = new Date(closingAt).getTime();
    if (close && !Number.isNaN(close)) deadline = close + windowDays * 86400000;
  }
  const daysFromNow = deadline ? Math.ceil((deadline - now) / 86400000) : null;
  return send(res, 200, {
    hasData: !!deadline,
    cancellationWindowDays: windowDays,
    deadline: deadline ? new Date(deadline).toISOString() : null,
    daysRemaining: daysFromNow,
    isExpired: daysFromNow !== null && daysFromNow < 0,
    closingAt: closingAt || null,
  });
});

