R('GET', '/app/me/annual-statements', async (req, res) => {
  const auth = requireAuth(req, res); if (!auth) return;
  const u = db.find('users', x => x.id === auth.id);
  if (!u) return err(res, 404, 'not_found');
  const invs = db.filter('investments', i => i.userId === u.id && i.status !== 'canceled');
  const txns = db.filter('transactions', t => t.userId === u.id);
  const yearsSet = new Set();
  for (const i of invs) {
    const t = new Date(i.createdAt || i.investedAt);
    if (!Number.isNaN(t.getTime())) yearsSet.add(t.getUTCFullYear());
  }
  for (const t of txns) {
    const d = new Date(t.createdAt || t.processedAt);
    if (!Number.isNaN(d.getTime())) yearsSet.add(d.getUTCFullYear());
  }
  if (!yearsSet.size) return send(res, 200, { hasData: false });
  const years = [...yearsSet].sort((a, b) => b - a).slice(0, 5).map(y => {
    const start = new Date(Date.UTC(y, 0, 1)).getTime();
    const end = new Date(Date.UTC(y + 1, 0, 1)).getTime();
    let invested = 0, profit = 0, fees = 0;
    for (const i of invs) {
      const t = new Date(i.createdAt || i.investedAt).getTime();
      if (t >= start && t < end) invested += Number(i.amount || 0);
    }
    for (const t of txns) {
      const ts = new Date(t.createdAt || t.processedAt).getTime();
      if (!ts || ts < start || ts >= end) continue;
      const kind = (t.type || t.kind || '').toLowerCase();
      const status = (t.status || '').toLowerCase();
      if (status === 'failed' || status === 'canceled') continue;
      if (kind === 'fee' || kind === 'commission') fees += Number(t.amount || 0);
      if (kind === 'profit' || kind === 'distribution' || kind === 'payout') profit += Number(t.amount || 0);
    }
    return {
      year: y,
      invested: Math.round(invested),
      profit: Math.round(profit),
      fees: Math.round(fees),
      net: Math.round(profit - fees),
      pdfUrl: '/app/me/statements/' + y + '.pdf',
      csvUrl: '/app/me/statements/' + y + '.csv',
    };
  });
  return send(res, 200, { hasData: true, years });
});

R('GET', '/app/me/recent-receipts', async (req, res) => {
  const auth = requireAuth(req, res); if (!auth) return;
  const projects = Object.fromEntries(db.all('projects').map(p => [p.id, p]));
  const invs = db.filter('investments', i => i.userId === auth.id && i.status !== 'canceled');
  const txns = db.filter('transactions', t => t.userId === auth.id);
  const list = [];
  for (const i of invs) {
    const p = projects[i.projectId];
    list.push({
      type: 'investment',
      id: i.id,
      title: p ? (p.title || p.name) : 'صفقة استثمار',
      amount: Number(i.amount || 0),
      date: i.createdAt || i.investedAt,
      slug: p ? (p.slug || p.id) : null,
    });
  }
  for (const t of txns) {
    const kind = (t.type || t.kind || '').toLowerCase();
    const status = (t.status || '').toLowerCase();
    if (status === 'failed' || status === 'canceled') continue;
    if (kind === 'deposit') list.push({ type: 'deposit', id: t.id, title: 'إيداع', amount: Number(t.amount || 0), date: t.createdAt });
    else if (kind === 'withdraw' || kind === 'withdrawal') list.push({ type: 'withdraw', id: t.id, title: 'سحب', amount: -Number(t.amount || 0), date: t.createdAt });
    else if (kind === 'profit' || kind === 'distribution' || kind === 'payout') list.push({ type: 'payout', id: t.id, title: 'توزيع أرباح', amount: Number(t.amount || 0), date: t.createdAt });
  }
  if (!list.length) return send(res, 200, { hasData: false });
  list.sort((a, b) => (b.date || '').localeCompare(a.date || ''));
  return send(res, 200, {
    hasData: true,
    receipts: list.slice(0, 15).map(r => ({
      ...r,
      amount: Math.round(r.amount),
      receiptUrl: '/app/me/receipts/' + encodeURIComponent(r.type) + '/' + encodeURIComponent(r.id) + '.pdf',
    })),
  });
});

R('GET', '/app/me/monthly-chart', async (req, res) => {
  const auth = requireAuth(req, res); if (!auth) return;
  const invs = db.filter('investments', i => i.userId === auth.id && i.status !== 'canceled');
  if (!invs.length) return send(res, 200, { hasData: false });
  const monthly = {};
  for (const i of invs) {
    const t = new Date(i.createdAt || i.investedAt);
    if (Number.isNaN(t.getTime())) continue;
    const key = t.getUTCFullYear() + '-' + String(t.getUTCMonth() + 1).padStart(2, '0');
    if (!monthly[key]) monthly[key] = { month: key, amount: 0, count: 0 };
    monthly[key].amount += Number(i.amount || 0);
    monthly[key].count++;
  }
  // Fill in zero months over the past 12 months
  const now = new Date();
  const months = [];
  for (let i = 11; i >= 0; i--) {
    const d = new Date(Date.UTC(now.getUTCFullYear(), now.getUTCMonth() - i, 1));
    const key = d.getUTCFullYear() + '-' + String(d.getUTCMonth() + 1).padStart(2, '0');
    const m = monthly[key] || { month: key, amount: 0, count: 0 };
    months.push({ month: key, amount: Math.round(m.amount), count: m.count });
  }
  const total = months.reduce((s, x) => s + x.amount, 0);
  const activeMonths = months.filter(m => m.amount > 0).length;
  const avgActive = activeMonths > 0 ? Math.round(total / activeMonths) : 0;
  const best = months.reduce((a, b) => (b.amount > a.amount ? b : a), months[0]);
  return send(res, 200, { hasData: true, months, total: Math.round(total), avgActive, activeMonths, bestMonth: best.month, bestAmount: best.amount });
});

