R('GET', '/app/me/self-cap', async (req, res) => {
  const auth = requireAuth(req, res); if (!auth) return;
  const u = db.find('users', x => x.id === auth.id);
  if (!u) return err(res, 404, 'not_found');
  const c = u.selfCap || {};
  // Calculate spent this month
  const now = new Date();
  const monthStart = new Date(Date.UTC(now.getUTCFullYear(), now.getUTCMonth(), 1)).getTime();
  const yearStart = new Date(Date.UTC(now.getUTCFullYear(), 0, 1)).getTime();
  const invs = db.filter('investments', i => i.userId === u.id && i.status !== 'canceled');
  let monthSpent = 0, yearSpent = 0;
  for (const i of invs) {
    const t = new Date(i.createdAt || i.investedAt).getTime();
    const amt = Number(i.amount || 0);
    if (t >= monthStart) monthSpent += amt;
    if (t >= yearStart) yearSpent += amt;
  }
  return send(res, 200, {
    hasData: true,
    enabled: !!c.enabled,
    monthlyCap: Number(c.monthlyCap || 0),
    yearlyCap: Number(c.yearlyCap || 0),
    perDealCap: Number(c.perDealCap || 0),
    monthSpent: Math.round(monthSpent),
    yearSpent: Math.round(yearSpent),
    monthRemaining: c.monthlyCap > 0 ? Math.max(0, Math.round(c.monthlyCap - monthSpent)) : null,
    yearRemaining: c.yearlyCap > 0 ? Math.max(0, Math.round(c.yearlyCap - yearSpent)) : null,
  });
});

