R('GET', '/app/me/deposit-insights', async (req, res) => {
  const auth = requireAuth(req, res); if (!auth) return;
  const deposits = db.filter('transactions', t => t.userId === auth.id && (t.type === 'deposit' || t.kind === 'deposit'));
  if (!deposits.length) return send(res, 200, { hasData: false });
  let total = 0, count = 0, succeeded = 0, failed = 0;
  const byMethod = {};
  const monthly = {};
  let largest = 0, smallest = Infinity;
  for (const d of deposits) {
    const amt = Number(d.amount || 0);
    const status = (d.status || '').toLowerCase();
    if (status === 'failed' || status === 'declined') { failed++; continue; }
    if (status === 'succeeded' || status === 'completed' || !status) {
      succeeded++;
      total += amt;
      count++;
      if (amt > largest) largest = amt;
      if (amt < smallest) smallest = amt;
      const method = (d.method || d.paymentMethod || d.provider || 'غير محدّد').toString();
      byMethod[method] = (byMethod[method] || 0) + amt;
      const date = d.createdAt || d.processedAt;
      if (date) {
        const ds = new Date(date);
        if (!Number.isNaN(ds.getTime())) {
          const key = ds.getUTCFullYear() + '-' + String(ds.getUTCMonth() + 1).padStart(2, '0');
          monthly[key] = (monthly[key] || 0) + amt;
        }
      }
    }
  }
  if (!count) return send(res, 200, { hasData: false });
  const avg = Math.round(total / count);
  const months = Object.keys(monthly);
  const monthlyAvg = months.length > 0 ? Math.round(Object.values(monthly).reduce((s, v) => s + v, 0) / months.length) : 0;
  const preferredMethod = Object.entries(byMethod).sort((a, b) => b[1] - a[1])[0];
  return send(res, 200, {
    hasData: true,
    totalDeposited: Math.round(total),
    depositCount: succeeded,
    failedCount: failed,
    avgDeposit: avg,
    largestDeposit: largest,
    smallestDeposit: smallest === Infinity ? 0 : smallest,
    monthlyAverage: monthlyAvg,
    activeMonths: months.length,
    preferredMethod: preferredMethod ? preferredMethod[0] : null,
    preferredMethodAmount: preferredMethod ? Math.round(preferredMethod[1]) : 0,
  });
});

