R('GET', '/app/me/referral-earnings', async (req, res) => {
  const auth = requireAuth(req, res); if (!auth) return;
  const u = db.find('users', x => x.id === auth.id);
  if (!u) return err(res, 404, 'not_found');
  const referrals = db.filter('users', x => x.referredBy === u.id || x.referrerId === u.id);
  const invsByUser = {};
  for (const i of db.all('investments')) {
    if (i.status === 'canceled') continue;
    if (!invsByUser[i.userId]) invsByUser[i.userId] = [];
    invsByUser[i.userId].push(i);
  }
  let activated = 0, totalReferred = referrals.length;
  let totalEarned = 0, pending = 0;
  const rows = [];
  const bonusPerActivation = 50; // 50 ر.س per referred user who invests
  for (const r of referrals) {
    const invs = invsByUser[r.id] || [];
    const hasInvested = invs.length > 0;
    if (hasInvested) activated++;
    const earned = hasInvested ? bonusPerActivation : 0;
    totalEarned += earned;
    if (!hasInvested) pending++;
    rows.push({
      name: (r.firstName ? r.firstName + ' ' + ((r.lastName || '').slice(0, 1) + '.') : 'مستخدم'),
      signedUp: r.createdAt,
      invested: hasInvested,
      earned,
    });
  }
  return send(res, 200, {
    hasData: true,
    referralCode: u.referralCode || (u.id ? u.id.slice(-8).toUpperCase() : ''),
    totalReferred,
    activated,
    pending,
    totalEarned,
    activationRate: totalReferred > 0 ? Math.round((activated / totalReferred) * 100) : 0,
    bonusPerActivation,
    rows: rows.slice(-10).reverse(),
  });
});

R('GET', '/app/me/diversification', async (req, res) => {
  const auth = requireAuth(req, res); if (!auth) return;
  const invs = db.filter('investments', i => i.userId === auth.id && i.status !== 'canceled');
  if (!invs.length) return send(res, 200, { hasData: false });
  const projects = Object.fromEntries(db.all('projects').map(p => [p.id, p]));
  const bySector = {}, byCity = {}, bySponsor = {}, byDuration = {};
  let totalAmount = 0;
  for (const inv of invs) {
    const p = projects[inv.projectId];
    if (!p) continue;
    const amt = Number(inv.amount || 0);
    totalAmount += amt;
    const sector = (p.category || p.sector || 'other').toString();
    const city = (p.city || p.location || 'unknown').toString();
    const sponsor = (p.sponsorName || p.sponsor || p.developer || 'unknown').toString();
    const durBucket = Number(p.durationMonths || 12) <= 12 ? 'short' : (Number(p.durationMonths || 12) <= 36 ? 'medium' : 'long');
    bySector[sector] = (bySector[sector] || 0) + amt;
    byCity[city] = (byCity[city] || 0) + amt;
    bySponsor[sponsor] = (bySponsor[sponsor] || 0) + amt;
    byDuration[durBucket] = (byDuration[durBucket] || 0) + amt;
  }
  const entropy = obj => {
    const sum = Object.values(obj).reduce((s, v) => s + v, 0);
    if (sum < 1) return 0;
    let e = 0;
    for (const v of Object.values(obj)) {
      if (v <= 0) continue;
      const p = v / sum;
      e -= p * Math.log2(p);
    }
    const n = Object.keys(obj).length;
    const max = n > 1 ? Math.log2(n) : 1;
    return Math.round((e / max) * 100);
  };
  const sectorScore = entropy(bySector);
  const cityScore = entropy(byCity);
  const sponsorScore = entropy(bySponsor);
  const durationScore = entropy(byDuration);
  const overall = Math.round((sectorScore + cityScore + sponsorScore + durationScore) / 4);
  let grade = 'F';
  if (overall >= 80) grade = 'A';
  else if (overall >= 65) grade = 'B';
  else if (overall >= 50) grade = 'C';
  else if (overall >= 30) grade = 'D';
  let suggestion = '';
  const minScore = Math.min(sectorScore, cityScore, sponsorScore, durationScore);
  if (minScore === sectorScore) suggestion = 'حاول التنويع بين قطاعات أكثر';
  else if (minScore === cityScore) suggestion = 'حاول التنويع بين مدن أكثر';
  else if (minScore === sponsorScore) suggestion = 'حاول التنويع بين مطوّرين/مالكين أكثر';
  else suggestion = 'حاول مزج صفقات قصيرة ومتوسّطة وطويلة المدى';
  return send(res, 200, {
    hasData: true,
    overall, grade,
    sectorScore, cityScore, sponsorScore, durationScore,
    totalDeals: invs.length,
    totalAmount: Math.round(totalAmount),
    suggestion,
  });
});

