R('GET', '/app/me/compound-projection', async (req, res) => {
  const auth = requireAuth(req, res); if (!auth) return;
  const invs = db.filter('investments', i => i.userId === auth.id && i.status !== 'canceled');
  if (!invs.length) return send(res, 200, { hasData: false });
  const projects = Object.fromEntries(db.all('projects').map(p => [p.id, p]));
  let total = 0, weighted = 0;
  for (const i of invs) {
    const p = projects[i.projectId];
    const amount = Number(i.amount || 0);
    total += amount;
    if (p && p.expectedReturn) weighted += amount * Number(p.expectedReturn);
  }
  if (total < 1) return send(res, 200, { hasData: false });
  const blendedRate = +(weighted / total / 100).toFixed(4);
  const years = [1, 3, 5, 10, 20];
  const projection = years.map(y => {
    const future = total * Math.pow(1 + blendedRate, y);
    return { years: y, futureValue: Math.round(future), growth: Math.round(future - total) };
  });
  // also: with monthly addition of 1000 ر.س (illustrative)
  const monthlyAdd = 1000;
  const withAdditions = years.map(y => {
    const months = y * 12;
    const monthlyRate = blendedRate / 12;
    const fvLump = total * Math.pow(1 + monthlyRate, months);
    const fvAdd = monthlyRate > 0 ? monthlyAdd * ((Math.pow(1 + monthlyRate, months) - 1) / monthlyRate) : monthlyAdd * months;
    return { years: y, futureValue: Math.round(fvLump + fvAdd) };
  });
  return send(res, 200, {
    hasData: true,
    currentInvested: Math.round(total),
    blendedRatePct: +(blendedRate * 100).toFixed(2),
    projection,
    withMonthlyAdditions: withAdditions,
    monthlyAdditionAssumption: monthlyAdd,
  });
});

