R('GET', '/app/me/tax-year-summary', async (req, res) => {
  const auth = requireAuth(req, res); if (!auth) return;
  const url = new URL(req.url, 'http://x');
  const year = Number(url.searchParams.get('year')) || new Date().getUTCFullYear();
  const start = new Date(Date.UTC(year, 0, 1)).getTime();
  const end = new Date(Date.UTC(year + 1, 0, 1)).getTime();
  const txns = db.filter('transactions', t => t.userId === auth.id);
  const invs = db.filter('investments', i => i.userId === auth.id);
  let invested = 0, repaidPrincipal = 0, profit = 0, fees = 0, refunds = 0;
  let investCount = 0, repaidCount = 0;
  for (const i of invs) {
    const t = new Date(i.createdAt || i.investedAt).getTime();
    if (t && t >= start && t < end) {
      invested += Number(i.amount || 0);
      investCount++;
    }
    if (i.repaidAt) {
      const rt = new Date(i.repaidAt).getTime();
      if (rt && rt >= start && rt < end) {
        repaidPrincipal += Number(i.amount || 0);
        profit += Number(i.totalReturn || i.profit || 0);
        repaidCount++;
      }
    }
  }
  for (const t of txns) {
    const ts = new Date(t.createdAt || t.processedAt).getTime();
    if (!ts || ts < start || ts >= end) continue;
    const kind = (t.type || t.kind || '').toLowerCase();
    if (kind === 'fee' || kind === 'commission') fees += Number(t.amount || 0);
    if (kind === 'refund' || kind === 'cancellation') refunds += Number(t.amount || 0);
  }
  return send(res, 200, {
    hasData: true,
    year,
    invested, investCount,
    repaidPrincipal, repaidCount,
    profit, fees, refunds,
    netProfit: profit - fees,
    zakatable: profit > 0 ? Math.round(profit * 0.025) : 0,
  });
});

R('GET', '/app/me/income-projection', async (req, res) => {
  const auth = requireAuth(req, res); if (!auth) return;
  const invs = db.filter('investments', i => i.userId === auth.id && i.status !== 'canceled' && i.status !== 'repaid');
  if (!invs.length) return send(res, 200, { hasData: false });
  const projects = Object.fromEntries(db.all('projects').map(p => [p.id, p]));
  const now = new Date();
  const projection = [];
  for (let m = 0; m < 12; m++) {
    const monthDate = new Date(Date.UTC(now.getUTCFullYear(), now.getUTCMonth() + m, 1));
    const key = monthDate.getUTCFullYear() + '-' + String(monthDate.getUTCMonth() + 1).padStart(2, '0');
    let amount = 0, dealCount = 0;
    for (const inv of invs) {
      const p = projects[inv.projectId];
      if (!p) continue;
      const startDate = new Date(inv.createdAt || inv.investedAt);
      const duration = Number(p.durationMonths || 12);
      const endDate = new Date(startDate.getFullYear(), startDate.getMonth() + duration, 1);
      if (monthDate < endDate) {
        const annualReturn = Number(p.expectedReturn || 0);
        const monthly = (Number(inv.amount || 0) * annualReturn) / 100 / 12;
        amount += monthly;
        dealCount++;
      }
    }
    projection.push({ month: key, amount: Math.round(amount), deals: dealCount });
  }
  const total = projection.reduce((s, m) => s + m.amount, 0);
  const avg = projection.length > 0 ? Math.round(total / projection.length) : 0;
  const peak = projection.reduce((a, b) => (b.amount > a.amount ? b : a), { amount: 0, month: '' });
  return send(res, 200, {
    hasData: true,
    months: projection,
    annualTotal: total,
    avgMonthly: avg,
    peakMonth: peak.month,
    peakAmount: peak.amount,
  });
});

R('GET', '/app/admin/ttfi-histogram', async (req, res) => {
  const admin = requireAdmin(req, res); if (!admin) return;
  const users = db.all('users').filter(u => u.role !== 'admin' && !u.deletedAt);
  if (!users.length) return send(res, 200, { hasData: false });
  const invsByUser = {};
  for (const i of db.all('investments')) {
    if (i.status === 'canceled') continue;
    if (!invsByUser[i.userId]) invsByUser[i.userId] = [];
    invsByUser[i.userId].push(i);
  }
  const buckets = [
    { key: '0-1', label: '< يوم', max: 1, count: 0 },
    { key: '1-3', label: '١–٣ أيام', max: 3, count: 0 },
    { key: '3-7', label: '٣–٧ أيام', max: 7, count: 0 },
    { key: '7-30', label: '٧–٣٠ يوم', max: 30, count: 0 },
    { key: '30-90', label: '٣٠–٩٠ يوم', max: 90, count: 0 },
    { key: '90+', label: '+٩٠ يوم', max: Infinity, count: 0 },
  ];
  let withFirstDeal = 0, totalDays = 0;
  for (const u of users) {
    const list = invsByUser[u.id] || [];
    if (!list.length) continue;
    const signed = new Date(u.createdAt || u.signedUpAt).getTime();
    const first = list.map(i => new Date(i.createdAt || i.investedAt).getTime()).filter(t => !!t && !Number.isNaN(t)).sort((a, b) => a - b)[0];
    if (!signed || !first) continue;
    const days = Math.max(0, (first - signed) / 86400000);
    withFirstDeal++;
    totalDays += days;
    for (const b of buckets) {
      if (days <= b.max) { b.count++; break; }
    }
  }
  if (!withFirstDeal) return send(res, 200, { hasData: false });
  return send(res, 200, {
    hasData: true,
    totalActivated: withFirstDeal,
    avgDays: +(totalDays / withFirstDeal).toFixed(1),
    medianBucket: buckets.reduce((m, b) => (b.count > m.count ? b : m), buckets[0]),
    buckets,
  });
});

R('GET', /^\/app\/projects\/([^/]+)\/payout-countdown$/, async (req, res, m) => {
  const projectId = m[1];
  const proj = db.find('projects', p => p.id === projectId);
  if (!proj) return send(res, 404, { error: 'not_found' });
  const next = proj.nextPayoutAt || proj.nextPayoutDate || proj.nextDistributionAt;
  if (!next) return send(res, 200, { hasData: false });
  const target = new Date(next).getTime();
  if (!target || Number.isNaN(target)) return send(res, 200, { hasData: false });
  const now = Date.now();
  const diff = target - now;
  const days = Math.floor(diff / 86400000);
  const hours = Math.floor((diff % 86400000) / 3600000);
  return send(res, 200, {
    hasData: true,
    nextPayoutAt: new Date(target).toISOString(),
    daysRemaining: days,
    hoursRemaining: hours,
    isPast: diff < 0,
    payoutAmount: Number(proj.lastPayoutAmount || proj.expectedPayoutAmount || 0),
    frequency: proj.payoutFrequency || proj.distributionFrequency || 'quarterly',
  });
});

R('GET', '/app/me/next-payouts', async (req, res) => {
  const auth = requireAuth(req, res); if (!auth) return;
  const invs = db.filter('investments', i => i.userId === auth.id && i.status !== 'canceled' && i.status !== 'repaid');
  if (!invs.length) return send(res, 200, { hasData: false });
  const projects = Object.fromEntries(db.all('projects').map(p => [p.id, p]));
  const upcoming = [];
  const now = Date.now();
  for (const inv of invs) {
    const p = projects[inv.projectId];
    if (!p) continue;
    const next = p.nextPayoutAt || p.nextPayoutDate || p.nextDistributionAt;
    if (!next) continue;
    const t = new Date(next).getTime();
    if (!t || Number.isNaN(t) || t < now) continue;
    const expected = Number(inv.expectedMonthlyReturn || inv.expectedPayout || (inv.amount * Number(p.expectedReturn || 0) / 100 / 12) || 0);
    upcoming.push({
      projectId: p.id,
      projectName: p.title || p.name,
      slug: p.slug || p.id,
      payoutAt: new Date(t).toISOString(),
      daysRemaining: Math.floor((t - now) / 86400000),
      amount: Math.round(expected),
    });
  }
  if (!upcoming.length) return send(res, 200, { hasData: false });
  upcoming.sort((a, b) => a.daysRemaining - b.daysRemaining);
  const next30 = upcoming.filter(p => p.daysRemaining <= 30);
  const total30 = next30.reduce((s, p) => s + p.amount, 0);
  return send(res, 200, {
    hasData: true,
    upcoming: upcoming.slice(0, 8),
    next30DaysTotal: total30,
    next30DaysCount: next30.length,
    totalUpcoming: upcoming.length,
  });
});

R('GET', '/app/admin/retention-cohort', async (req, res) => {
  const admin = requireAdmin(req, res); if (!admin) return;
  const users = db.all('users').filter(u => u.role !== 'admin' && !u.deletedAt);
  if (!users.length) return send(res, 200, { hasData: false });
  const invsByUser = {};
  for (const i of db.all('investments')) {
    if (i.status === 'canceled') continue;
    if (!invsByUser[i.userId]) invsByUser[i.userId] = [];
    invsByUser[i.userId].push(i);
  }
  let signed = users.length;
  let investedOnce = 0, investedRepeat = 0, dormant = 0;
  let totalInvCount = 0;
  for (const u of users) {
    const list = invsByUser[u.id] || [];
    if (list.length === 0) dormant++;
    else if (list.length === 1) investedOnce++;
    else investedRepeat++;
    totalInvCount += list.length;
  }
  const activated = signed - dormant;
  return send(res, 200, {
    hasData: true,
    signed, dormant, investedOnce, investedRepeat, activated,
    activationPct: signed > 0 ? Math.round((activated / signed) * 100) : 0,
    repeatPct: activated > 0 ? Math.round((investedRepeat / activated) * 100) : 0,
    avgInvestmentsPerActive: activated > 0 ? +(totalInvCount / activated).toFixed(1) : 0,
  });
});

R('GET', /^\/app\/projects\/([^/]+)\/subscription-velocity$/, async (req, res, m) => {
  const projectId = m[1];
  const proj = db.find('projects', p => p.id === projectId);
  if (!proj) return send(res, 404, { error: 'not_found' });
  const invs = db.filter('investments', i => (i.projectId === proj.id || i.projectSlug === proj.slug) && i.status !== 'canceled');
  if (invs.length < 3) return send(res, 200, { hasData: false });
  const dated = invs.map(i => new Date(i.createdAt || i.investedAt).getTime()).filter(t => !!t && !Number.isNaN(t)).sort((a, b) => a - b);
  if (dated.length < 3) return send(res, 200, { hasData: false });
  const now = Date.now();
  const span = dated[dated.length - 1] - dated[0];
  if (span < 1) return send(res, 200, { hasData: false });
  const recent7Days = dated.filter(t => now - t <= 7 * 86400000).length;
  const recent24h = dated.filter(t => now - t <= 86400000).length;
  const avgPerDay = +(dated.length / Math.max(1, span / 86400000)).toFixed(2);
  const recent7Avg = +(recent7Days / 7).toFixed(2);
  let trend = 'stable';
  if (recent7Avg > avgPerDay * 1.3) trend = 'accelerating';
  else if (recent7Avg < avgPerDay * 0.7) trend = 'cooling';
  return send(res, 200, {
    hasData: true,
    avgPerDay,
    recent7Days,
    recent7Avg,
    recent24h,
    trend,
    totalInvestors: dated.length,
    daysListed: Math.round(span / 86400000),
  });
});

