R('GET', '/app/admin/balance-summary', async (req, res) => {
  const admin = requireAdmin(req, res); if (!admin) return;
  const users = db.all('users').filter(u => !u.deletedAt && u.role !== 'admin');
  const balances = users.map(u => Number(u.balance) || 0).filter(n => n > 0);
  const total = balances.reduce((s, n) => s + n, 0);
  const buckets = {
    'lt_1k': { label: 'أقل من ١٬٠٠٠ ر.س', count: 0, sum: 0 },
    'lt_5k': { label: '١٬٠٠٠ - ٥٬٠٠٠', count: 0, sum: 0 },
    'lt_25k': { label: '٥٬٠٠٠ - ٢٥٬٠٠٠', count: 0, sum: 0 },
    'lt_100k': { label: '٢٥٬٠٠٠ - ١٠٠٬٠٠٠', count: 0, sum: 0 },
    'gte_100k': { label: 'أكثر من ١٠٠٬٠٠٠', count: 0, sum: 0 },
  };
  for (const b of balances) {
    if (b < 1000) { buckets.lt_1k.count++; buckets.lt_1k.sum += b; }
    else if (b < 5000) { buckets.lt_5k.count++; buckets.lt_5k.sum += b; }
    else if (b < 25000) { buckets.lt_25k.count++; buckets.lt_25k.sum += b; }
    else if (b < 100000) { buckets.lt_100k.count++; buckets.lt_100k.sum += b; }
    else { buckets.gte_100k.count++; buckets.gte_100k.sum += b; }
  }
  return send(res, 200, {
    totalUsers: users.length,
    usersWithBalance: balances.length,
    totalBalance: total,
    avgBalance: balances.length ? Math.round(total / balances.length) : 0,
    distribution: Object.entries(buckets).map(([key, b]) => ({ key, ...b, pct: total > 0 ? Math.round((b.sum / total) * 100) : 0 })),
  });
});

