R('GET', '/app/admin/yield-report', async (req, res) => {
  const admin = requireAdmin(req, res); if (!admin) return;
  const completed = db.filter('projects', p => p.status === 'closed' || p.status === 'funded' || p.status === 'completed');
  let totalInvested = 0;
  let totalDistributed = 0;
  let weightedRate = 0;
  let dealsCount = 0;
  const rows = [];
  for (const p of completed) {
    const invs = db.filter('investments', i => i.projectId === p.id && i.status !== 'canceled');
    const invested = invs.reduce((s, i) => s + Number(i.amount || 0), 0);
    const distributed = db.all('transactions')
      .filter(t => (t.kind === 'profit' || t.kind === 'payout') && t.projectId === p.id && t.status === 'completed')
      .reduce((s, t) => s + Number(t.amount || 0), 0);
    if (invested === 0) continue;
    const realizedRate = (distributed / invested) * 100;
    totalInvested += invested;
    totalDistributed += distributed;
    weightedRate += realizedRate * invested;
    dealsCount++;
    rows.push({
      id: p.id, name: p.name, status: p.status,
      invested, distributed, realizedRate,
      expectedRate: p.expectedRate || p.profitRate || 0,
      closedAt: p.contractAt || p.closedAt || null,
    });
  }
  rows.sort((a, b) => b.realizedRate - a.realizedRate);
  return send(res, 200, {
    deals: rows,
    summary: {
      dealsCount,
      totalInvested,
      totalDistributed,
      avgRealizedRate: totalInvested > 0 ? weightedRate / totalInvested : 0,
    },
  });
});

R('GET', '/app/admin/top-investors', async (req, res) => {
  const admin = requireAdmin(req, res); if (!admin) return;
  const params = new URL(req.url, 'http://x').searchParams;
  const limit = Math.max(1, Math.min(100, parseInt(params.get('limit') || '10', 10)));
  const userIdx = Object.fromEntries(db.all('users').map(u => [u.id, u]));
  const byUser = new Map();
  for (const i of db.all('investments')) {
    if (i.status === 'canceled') continue;
    const cur = byUser.get(i.userId) || { count: 0, total: 0, firstAt: i.createdAt };
    cur.count++;
    cur.total += Number(i.amount || 0);
    if (new Date(i.createdAt) < new Date(cur.firstAt)) cur.firstAt = i.createdAt;
    byUser.set(i.userId, cur);
  }
  const rows = [...byUser.entries()]
    .map(([userId, d]) => {
      const u = userIdx[userId];
      return {
        userId,
        name: u?.name || '—',
        email: u?.email || '',
        total: d.total,
        count: d.count,
        firstAt: d.firstAt,
        approved: !!u?.approved,
      };
    })
    .sort((a, b) => b.total - a.total)
    .slice(0, limit);
  return send(res, 200, { investors: rows, total: byUser.size });
});

R('GET', '/app/admin/conversion-funnel', async (req, res) => {
  const admin = requireAdmin(req, res); if (!admin) return;
  const params = new URL(req.url, 'http://x').searchParams;
  const days = Math.max(1, Math.min(365, parseInt(params.get('days') || '30', 10)));
  const cutoff = Date.now() - days * 24 * 60 * 60 * 1000;
  const users = db.all('users').filter(u => !u.deletedAt && u.role !== 'admin' && new Date(u.createdAt || 0).getTime() >= cutoff);
  const userIds = new Set(users.map(u => u.id));
  const registered = users.length;
  const emailVerified = users.filter(u => !!u.emailVerifiedAt).length;
  const mobileVerified = users.filter(u => !!u.mobileVerifiedAt).length;
  const kycComplete = users.filter(u => u.kycStatus === 'verified' || u.kycStatus === 'verified_qualified').length;
  const approved = users.filter(u => !!u.approved).length;
  const depositedSet = new Set();
  const investedSet = new Set();
  for (const t of db.all('transactions')) {
    if (!userIds.has(t.userId)) continue;
    if (t.kind === 'deposit' && t.status === 'completed') depositedSet.add(t.userId);
  }
  for (const i of db.all('investments')) {
    if (!userIds.has(i.userId)) continue;
    if (i.status !== 'canceled') investedSet.add(i.userId);
  }
  const steps = [
    { key: 'register', label: 'تسجيل', count: registered },
    { key: 'email', label: 'تأكيد البريد', count: emailVerified },
    { key: 'mobile', label: 'تأكيد الجوال', count: mobileVerified },
    { key: 'kyc', label: 'اكتمال KYC', count: kycComplete },
    { key: 'approved', label: 'اعتماد الإدارة', count: approved },
    { key: 'deposited', label: 'أوّل إيداع', count: depositedSet.size },
    { key: 'invested', label: 'أوّل استثمار', count: investedSet.size },
  ];
  const baseline = registered || 1;
  for (const s of steps) {
    s.pct = Math.round((s.count / baseline) * 100);
    s.dropPct = Math.max(0, 100 - s.pct);
  }
  return send(res, 200, { steps, days, registered });
});

R('GET', '/app/admin/payment-method-stats', async (req, res) => {
  const admin = requireAdmin(req, res); if (!admin) return;
  const params = new URL(req.url, 'http://x').searchParams;
  const days = Math.max(1, Math.min(365, parseInt(params.get('days') || '90', 10)));
  const cutoff = Date.now() - days * 24 * 60 * 60 * 1000;
  const buckets = {
    mada: { label: 'مدى', count: 0, volume: 0 },
    card: { label: 'بطاقة ائتمانية', count: 0, volume: 0 },
    iban: { label: 'تحويل بنكي / IBAN', count: 0, volume: 0 },
    apple: { label: 'Apple Pay', count: 0, volume: 0 },
    stc: { label: 'STC Pay', count: 0, volume: 0 },
    wire: { label: 'تحويل دولي', count: 0, volume: 0 },
    other: { label: 'أخرى', count: 0, volume: 0 },
  };
  for (const t of db.all('transactions')) {
    if (t.kind !== 'deposit' || t.status !== 'completed') continue;
    if (new Date(t.createdAt).getTime() < cutoff) continue;
    const label = (t.methodLabel || '').toLowerCase();
    let key = 'other';
    if (label.includes('مدى') || label.includes('mada')) key = 'mada';
    else if (label.includes('iban') || label.includes('بنكي')) key = 'iban';
    else if (label.includes('apple')) key = 'apple';
    else if (label.includes('stc')) key = 'stc';
    else if (label.includes('wire') || label.includes('swift')) key = 'wire';
    else if (label.includes('visa') || label.includes('master') || label.includes('بطاقة')) key = 'card';
    buckets[key].count++;
    buckets[key].volume += Math.abs(Number(t.amount) || 0);
  }
  const total = Object.values(buckets).reduce((s, b) => s + b.count, 0);
  const totalVolume = Object.values(buckets).reduce((s, b) => s + b.volume, 0);
  const stats = Object.entries(buckets)
    .map(([key, b]) => ({ key, ...b, pct: total ? Math.round((b.count / total) * 100) : 0 }))
    .filter(s => s.count > 0)
    .sort((a, b) => b.volume - a.volume);
  return send(res, 200, { stats, totalCount: total, totalVolume, days });
});

R('GET', '/app/admin/db-snapshot', async (req, res) => {
  const admin = requireAdmin(req, res); if (!admin) return;
  const snap = JSON.parse(JSON.stringify(db.get()));
  // Redact sensitive fields from users
  if (Array.isArray(snap.users)) {
    snap.users = snap.users.map(u => {
      const { passwordHash, totpSecret, sms2faSecret, backupCodes, magicToken, emailOtp, mobileOtp, ...safe } = u;
      return safe;
    });
  }
  if (Array.isArray(snap.sessions)) snap.sessions = [];
  if (Array.isArray(snap.magicLinks)) snap.magicLinks = [];
  if (Array.isArray(snap.loginAttempts)) snap.loginAttempts = snap.loginAttempts.slice(-200);
  await audit(admin.id, 'admin.db.snapshot', 'db', { tables: Object.keys(snap).length }, req);
  res.writeHead(200, {
    'Content-Type': 'application/json; charset=utf-8',
    'Content-Disposition': 'attachment; filename="murbha-snapshot-' + new Date().toISOString().slice(0, 10) + '.json"',
  });
  return res.end(JSON.stringify({
    exportedAt: new Date().toISOString(),
    exportedBy: admin.email,
    note: 'Sensitive fields redacted (password hashes, OTPs, TOTP secrets, sessions).',
    data: snap,
  }, null, 2));
});

