R('POST', '/app/admin/sms-broadcast', async (req, res) => {
  const admin = requireAdmin(req, res); if (!admin) return;
  const body = await readJson(req);
  const text = (body?.text || '').toString().trim();
  if (!text || text.length > 160) return err(res, 400, 'invalid_input');
  const segment = (body?.segment || 'verified-phone').toString();
  // Only target users with a verified phone (otherwise we'd be spamming people
  // who haven't opted in). Admin can also restrict to investors.
  let recipients = db.all('users').filter(u =>
    !u.deletedAt && u.role !== 'admin' && u.phone && u.mobileVerifiedAt
  );
  if (segment === 'investors') {
    const investorIds = new Set(db.all('investments').map(i => i.userId));
    recipients = recipients.filter(u => investorIds.has(u.id));
  } else if (segment === 'kyc-pending') {
    recipients = recipients.filter(u => (u.kycStatus || 'pending') !== 'verified');
  }
  if (recipients.length > 5000) return err(res, 400, 'segment_too_large');
  let sent = 0;
  for (const u of recipients) {
    try {
      await SMS.send({ to: u.phone, text });
      sent++;
    } catch (e) { /* ignore individual failures */ }
  }
  await audit(admin.id, 'admin.sms.broadcast', segment, { recipients: recipients.length, sent, length: text.length }, req);
  return send(res, 200, { ok: true, recipients: recipients.length, sent });
});

R('GET', '/app/admin/segment-size', async (req, res) => {
  const admin = requireAdmin(req, res); if (!admin) return;
  const segment = (new URL(req.url, 'http://x').searchParams.get('segment') || 'all').toString();
  let recipients = db.all('users').filter(u => !u.deletedAt && u.role !== 'admin');
  if (segment === 'approved')     recipients = recipients.filter(u => u.approved && !u.rejected);
  else if (segment === 'pending') recipients = recipients.filter(u => !u.approved && !u.rejected);
  else if (segment === 'kyc-pending') recipients = recipients.filter(u => (u.kycStatus || 'pending') !== 'verified');
  else if (segment === 'investors')   recipients = recipients.filter(u => db.filter('investments', i => i.userId === u.id).length > 0);
  return send(res, 200, { segment, count: recipients.length });
});

