R('POST', '/app/public/deal-alerts/subscribe', async (req, res) => {
  const body = await readJson(req);
  const email = (body?.email || '').toString().trim().toLowerCase();
  const category = (body?.category || 'all').toString().trim().slice(0, 40);
  if (!email || !/^[^@\s]+@[^@\s]+\.[^@\s]+$/.test(email)) return err(res, 400, 'invalid_email');
  const existing = db.find('dealAlerts', a => a.email === email && a.category === category);
  if (existing) return send(res, 200, { ok: true, already: true });
  await db.insert('dealAlerts', {
    id: require('crypto').randomBytes(8).toString('hex'),
    email, category,
    createdAt: new Date().toISOString(),
    ip: (req.headers['x-forwarded-for'] || '').toString().split(',')[0].trim() || req.socket.remoteAddress,
  });
  return send(res, 200, { ok: true });
});

