R('PATCH', '/app/me/privacy-prefs', async (req, res) => {
  const user = requireAuth(req, res); if (!user) return;
  const body = await readJson(req);
  const valid = ['hideName', 'hideAmounts', 'noAdTargeting', 'noAnalytics'];
  const fresh = db.find('users', u => u.id === user.id);
  const cur = fresh.privacyPrefs || {};
  const next = { ...cur };
  for (const k of valid) if (typeof body?.[k] === 'boolean') next[k] = body[k];
  await db.patch('users', u => u.id === user.id, { privacyPrefs: next });
  return send(res, 200, { ok: true, privacyPrefs: next });
});

