R('POST', '/app/me/notes', async (req, res) => {
  const auth = requireAuth(req, res); if (!auth) return;
  const body = await readJson(req);
  const text = (body?.text || '').toString().trim().slice(0, 2000);
  const projectId = body?.projectId ? (body.projectId).toString().slice(0, 80) : null;
  if (!text) return err(res, 400, 'invalid_input');
  const u = db.find('users', x => x.id === auth.id);
  const notes = Array.isArray(u.privateNotes) ? u.privateNotes : [];
  if (notes.length >= 100) return err(res, 400, 'limit_reached');
  const id = require('crypto').createHash('sha256').update(auth.id + ':' + Date.now() + ':' + text.slice(0, 20)).digest('hex').slice(0, 12);
  notes.unshift({ id, text, projectId, createdAt: new Date().toISOString() });
  await db.patch('users', x => x.id === auth.id, { privateNotes: notes });
  return send(res, 200, { ok: true, id });
});

