R('GET', '/app/me/credit-history', async (req, res) => {
  const auth = requireAuth(req, res); if (!auth) return;
  const u = db.find('users', x => x.id === auth.id);
  if (!u) return err(res, 404, 'not_found');
  const credits = Array.isArray(u.creditHistory) ? u.creditHistory : [];
  const txCredits = db.filter('transactions', t => t.userId === auth.id && (t.kind === 'bonus' || t.kind === 'reward' || t.kind === 'referral') && t.status === 'completed')
    .map(t => ({
      id: t.id,
      kind: t.kind,
      label: t.label || (t.kind === 'referral' ? 'مكافأة إحالة' : t.kind === 'reward' ? 'مكافأة' : 'رصيد إضافي'),
      amount: Math.abs(Number(t.amount || 0)),
      at: t.completedAt || t.createdAt,
      reason: t.reason || '',
    }));
  const merged = [...credits, ...txCredits].sort((a, b) => new Date(b.at) - new Date(a.at));
  if (!merged.length) return send(res, 200, { hasCredits: false });
  const totalEarned = merged.reduce((s, c) => s + Number(c.amount || 0), 0);
  const last30Sum = merged.filter(c => Date.now() - new Date(c.at).getTime() < 30 * 86400e3).reduce((s, c) => s + Number(c.amount || 0), 0);
  const byKind = new Map();
  for (const c of merged) {
    const k = c.kind || 'other';
    const cur = byKind.get(k) || { kind: k, count: 0, sum: 0 };
    cur.count++;
    cur.sum += Number(c.amount || 0);
    byKind.set(k, cur);
  }
  return send(res, 200, {
    hasCredits: true,
    totalEarned: Math.round(totalEarned),
    last30Sum: Math.round(last30Sum),
    totalCount: merged.length,
    byKind: [...byKind.values()].sort((a, b) => b.sum - a.sum),
    recent: merged.slice(0, 12),
  });
});

