  const body = await readJson(req).catch(() => ({}));
  const validStyles = ['passive', 'hybrid', 'active', 'specialist'];
  const validConsent = ['auto', 'ask', 'manual'];
  const style = validStyles.includes(body.style) ? body.style : 'hybrid';
  const autoPct = Math.max(0, Math.min(100, Number(body.autoAllocationPct) || 70));
