R('PUT', '/app/me/horizon-style', async (req, res) => {
  const auth = requireAuth(req, res); if (!auth) return;
  const u = db.find('users', x => x.id === auth.id);
  if (!u) return err(res, 404, 'not_found');
  const body = await readJson(req).catch(() => ({}));
  const validStyles = ['conservative', 'balanced', 'growth', 'endowment'];
  const style = validStyles.includes(body.style) ? body.style : 'balanced';
  const validFreq = ['monthly', 'quarterly', 'yearly', 'manual'];
  const freq = validFreq.includes(body.rebalanceFrequency) ? body.rebalanceFrequency : 'yearly';
  const minH = Math.max(0, Math.min(50, Number(body.minHorizonYears) || 1));
  const targetH = Math.max(minH, Math.min(60, Number(body.targetHorizonYears) || 5));
  const tolerance = Math.max(1, Math.min(20, Number(body.rebalanceTolerancePct) || 5));
  const targets = body.endowmentTargets || {};
  const validKeys = ['murabaha', 'stocks', 'gold', 'infrastructure', 'private', 'cash'];
  const filteredTargets = {};
  let sum = 0;
  validKeys.forEach(k => {
    filteredTargets[k] = Math.max(0, Math.min(100, Number(targets[k]) || 0));
    sum += filteredTargets[k];
  });
  if (Math.abs(sum - 100) > 1) return err(res, 400, 'targets_must_sum_to_100');
  db.patch('users', u.id, {
    horizonStyle: style,
    minHorizonYears: minH,
    targetHorizonYears: targetH,
    endowmentTargets: filteredTargets,
    rebalanceFrequency: freq,
    rebalanceTolerancePct: tolerance,
    showEndowmentRecommendations: body.showEndowmentRecommendations !== false,
  });
  try { audit(u.id, 'horizon_style_updated', 'user:' + u.id, { style }, req); } catch (e) {}
  return send(res, 200, { ok: true });
});

