R('GET', '/app/me/income-needs', async (req, res) => {
  const auth = requireAuth(req, res); if (!auth) return;
  const u = db.find('users', x => x.id === auth.id);
  if (!u) return err(res, 404, 'not_found');
  const investments = db.all('investments').filter(i => i.userId === auth.id);
  const projectsById = new Map(db.all('projects').map(p => [p.id, p]));
  let estimatedMonthlyIncome = 0;
  for (const inv of investments) {
    const p = projectsById.get(inv.projectId);
    if (!p) continue;
    const yieldPct = Number(p.expectedYield || 0);
    const scheme = p.distributionScheme || 'bullet';
    const amount = Number(inv.amount || 0);
    if (scheme === 'monthly') {
      estimatedMonthlyIncome += amount * yieldPct / 100 / 12;
    } else if (scheme === 'quarterly') {
      estimatedMonthlyIncome += amount * yieldPct / 100 / 12;
    }
  }
  const targetMonthly = Number(u.targetMonthlyIncomeAfterRetirement || 10000);
  const gap = targetMonthly - estimatedMonthlyIncome;
  const requiredAdditionalCapital = gap > 0 ? Math.round(gap * 12 * 100 / 8) : 0;
  return send(res, 200, {
    hasData: true,
    targetMonthlyIncome: targetMonthly,
    estimatedMonthlyIncome: Math.round(estimatedMonthlyIncome),
    gap: Math.round(gap),
    coveragePct: targetMonthly > 0 ? +((estimatedMonthlyIncome / targetMonthly) * 100).toFixed(1) : 0,
    requiredAdditionalCapital,
    preferMonthlyOverAccumulation: !!u.preferMonthlyIncome,
    autoSweepDistributions: !!u.autoSweepDistributions,
    sweepDestination: u.sweepDestination || 'main_account',
    notifyOnEachDistribution: u.notifyEachDistribution !== false,
    monthlyReportEnabled: u.monthlyIncomeReportEnabled !== false,
  });
});

