R('GET', '/app/me/income-profile', async (req, res) => {
  const auth = requireAuth(req, res); if (!auth) return;
  const u = db.find('users', x => x.id === auth.id);
  if (!u) return err(res, 404, 'not_found');
  const monthlyIncomes = Array.isArray(u.monthlyIncomes12) ? u.monthlyIncomes12 : [];
  let avg = 0, min = 0, max = 0, stability = 'stable';
  if (monthlyIncomes.length >= 3) {
    const positive = monthlyIncomes.filter(v => v > 0);
    avg = positive.length > 0 ? positive.reduce((s, v) => s + v, 0) / positive.length : 0;
    min = Math.min(...monthlyIncomes);
    max = Math.max(...monthlyIncomes);
    const coeffVar = avg > 0 ? ((max - min) / avg) : 0;
    if (coeffVar < 0.2) stability = 'very_stable';
    else if (coeffVar < 0.5) stability = 'stable';
    else if (coeffVar < 1.0) stability = 'variable';
    else stability = 'very_variable';
  }
  return send(res, 200, {
    hasData: true,
    incomeType: u.incomeType || 'salaried',
    incomeStability: u.incomeStability || stability,
    monthlyIncomes12: monthlyIncomes,
    avg: Math.round(avg),
    min,
    max,
    autoSaveRate: u.autoSaveRate || 20,
    autoTaxRate: u.autoTaxRate || 15,
    biggestClientPct: u.biggestClientPct || 0,
    emergencyMonthsTarget: u.emergencyMonthsTarget || 9,
  });
});

