R('GET', '/app/me/catch-up-plan', async (req, res) => {
  const auth = requireAuth(req, res); if (!auth) return;
  const u = db.find('users', x => x.id === auth.id);
  if (!u) return err(res, 404, 'not_found');
  const age = u.currentAge || 40;
  const retirementAge = u.retirementAge || 65;
  const yearsToRetirement = Math.max(1, retirementAge - age);
  const target = u.retirementTargetAmount || 2000000;
  const currentSavings = u.totalInvested || 0;
  const yieldPct = 8;
  // Calculate required monthly contribution
  const months = yearsToRetirement * 12;
  const monthlyRate = yieldPct / 100 / 12;
  const fvCurrent = currentSavings * Math.pow(1 + monthlyRate, months);
  const shortfall = Math.max(0, target - fvCurrent);
  const requiredMonthly = monthlyRate > 0 ? (shortfall * monthlyRate) / (Math.pow(1 + monthlyRate, months) - 1) : shortfall / months;
  const incomePct = u.monthlyIncome ? Math.round((requiredMonthly / u.monthlyIncome) * 100) : null;
  let intensity = 'manageable';
  if (incomePct >= 40) intensity = 'heroic';
  else if (incomePct >= 25) intensity = 'aggressive';
  else if (incomePct >= 15) intensity = 'moderate';
  return send(res, 200, {
    hasData: true,
    age,
    yearsToRetirement,
    target,
    currentSavings,
    shortfall: Math.round(shortfall),
    requiredMonthly: Math.round(requiredMonthly),
    incomePct,
    intensity,
    workExtraYears: u.workExtraYears || 0,
    aggressiveSavings: !!u.aggressiveSavings,
    increasedRiskTolerance: !!u.lateStarterRisk,
    secondaryIncomePlan: u.secondaryIncomePlan || '',
  });
});

