R('POST', '/app/me/compound-calculator', async (req, res) => {
  const auth = requireAuth(req, res); if (!auth) return;
  const body = await readJson(req).catch(() => ({}));
  const initial = Math.max(0, Number(body.initial) || 0);
  const monthly = Math.max(0, Number(body.monthly) || 0);
  const yieldPct = Math.max(0, Math.min(50, Number(body.yieldPct) || 8));
  const years = Math.max(1, Math.min(60, Number(body.years) || 20));
  const inflationPct = Math.max(0, Math.min(20, Number(body.inflationPct) || 3));
  const months = years * 12;
  const monthlyRate = yieldPct / 100 / 12;
  const inflationMonthlyRate = inflationPct / 100 / 12;
  // FV of initial + FV of monthly contributions
  const fvInitial = initial * Math.pow(1 + monthlyRate, months);
  const fvMonthly = monthlyRate > 0 ? monthly * ((Math.pow(1 + monthlyRate, months) - 1) / monthlyRate) : monthly * months;
  const nominalFinal = fvInitial + fvMonthly;
  const totalContributions = initial + (monthly * months);
  const totalGains = nominalFinal - totalContributions;
  // Inflation-adjusted (real) value
  const realRate = (1 + monthlyRate) / (1 + inflationMonthlyRate) - 1;
  const realFvInitial = initial * Math.pow(1 + realRate, months);
  const realFvMonthly = realRate > 0 ? monthly * ((Math.pow(1 + realRate, months) - 1) / realRate) : monthly * months;
  const realFinal = realFvInitial + realFvMonthly;
  // Year-by-year breakdown
  const yearlyBreakdown = [];
  for (let y = 1; y <= years; y++) {
    const m = y * 12;
    const ai = initial * Math.pow(1 + monthlyRate, m);
    const am = monthlyRate > 0 ? monthly * ((Math.pow(1 + monthlyRate, m) - 1) / monthlyRate) : monthly * m;
    yearlyBreakdown.push({ year: y, amount: Math.round(ai + am) });
  }
  return send(res, 200, {
    ok: true,
    nominalFinal: Math.round(nominalFinal),
    realFinal: Math.round(realFinal),
    totalContributions: Math.round(totalContributions),
    totalGains: Math.round(totalGains),
    gainsRatio: +(totalGains / totalContributions).toFixed(2),
    doublingYears: +(72 / yieldPct).toFixed(1),
    yearlyBreakdown,
  });
});

