R('PUT', '/app/me/financial-goals', async (req, res) => {
  const auth = requireAuth(req, res); if (!auth) return;
  const u = db.find('users', x => x.id === auth.id);
  if (!u) return err(res, 404, 'not_found');
  const body = await readJson(req).catch(() => ({}));
  const validTypes = ['hajj', 'home', 'education', 'marriage', 'retirement', 'big_purchase', 'business', 'emergency', 'other'];
  const goals = Array.isArray(body.goals) ? body.goals.slice(0, 12).map(g => ({
    id: g.id || ('g_' + Math.random().toString(36).slice(2, 10)),
    type: validTypes.includes(g.type) ? g.type : 'other',
    name: String(g.name || '').slice(0, 100),
    targetAmount: Math.max(0, Number(g.targetAmount) || 0),
    currentAmount: Math.max(0, Number(g.currentAmount) || 0),
    targetDate: g.targetDate ? new Date(g.targetDate).toISOString() : null,
    priority: Math.max(1, Math.min(10, Number(g.priority) || 5)),
  })).filter(g => g.name && g.targetAmount > 0) : [];
  // Recompute onTrack flag
  goals.forEach(g => {
    if (!g.targetDate) { g.onTrack = null; return; }
    const monthsAway = Math.max(1, (new Date(g.targetDate).getTime() - Date.now()) / (30 * 86400000));
    const requiredPerMonth = (g.targetAmount - g.currentAmount) / monthsAway;
    g.onTrack = g.currentAmount >= g.targetAmount || requiredPerMonth < (g.targetAmount * 0.05);
  });
  db.patch('users', u.id, {
    financialGoals: goals,
    goalsAutoAllocate: !!body.autoAllocate,
  });
  try { audit(u.id, 'financial_goals_updated', 'user:' + u.id, { count: goals.length }, req); } catch (e) {}
  return send(res, 200, { ok: true });
});

