R('GET', '/app/me/liquidity-needs', async (req, res) => {
  const auth = requireAuth(req, res); if (!auth) return;
  const u = db.find('users', x => x.id === auth.id);
  if (!u) return err(res, 404, 'not_found');
  const investments = db.all('investments').filter(i => i.userId === auth.id && (i.status === 'confirmed' || i.status === 'active' || i.status === 'funded'));
  const projectsById = new Map(db.all('projects').map(p => [p.id, p]));
  const current = { 1: 0, 2: 0, 3: 0, 4: 0 };
  let totalInvested = 0;
  for (const inv of investments) {
    const p = projectsById.get(inv.projectId);
    if (!p) continue;
    const months = Number(p.durationMonths || 12);
    const amt = Number(inv.amount || 0);
    totalInvested += amt;
    let tier = 4;
    if (months <= 1) tier = 1;
    else if (months <= 6) tier = 2;
    else if (months <= 36) tier = 3;
    current[tier] = (current[tier] || 0) + amt;
  }
  const currentPct = { 1: 0, 2: 0, 3: 0, 4: 0 };
  if (totalInvested > 0) {
    Object.keys(current).forEach(k => { currentPct[k] = +((current[k] / totalInvested) * 100).toFixed(1); });
  }
  const recipe = u.liquidityRecipe || { 1: 10, 2: 20, 3: 35, 4: 35 };
  return send(res, 200, {
    hasData: true,
    monthlyExpenses: u.monthlyExpenses || 5000,
    emergencyBufferMonths: u.emergencyBufferMonths || 3,
    upcomingGoalsAmount: u.upcomingGoalsAmount || 0,
    upcomingGoalsHorizonMonths: u.upcomingGoalsHorizonMonths || 12,
    recipe,
    current: currentPct,
    totalInvested: +totalInvested.toFixed(0),
  });
});

