R('GET', '/app/me/diversification-coach', async (req, res) => {
  const auth = requireAuth(req, res); if (!auth) return;
  const investments = db.all('investments').filter(i => i.userId === auth.id && (i.status === 'confirmed' || i.status === 'active' || i.status === 'funded'));
  if (!investments.length) return send(res, 200, { hasData: false });
  const projectsById = new Map(db.all('projects').map(p => [p.id, p]));
  let total = 0;
  const byCategory = {};
  const bySponsor = {};
  const byRegion = {};
  for (const inv of investments) {
    const p = projectsById.get(inv.projectId);
    if (!p) continue;
    const amt = Number(inv.amount || 0);
    if (amt < 1) continue;
    total += amt;
    const cat = p.category || 'other';
    const sp = p.sponsorId || 'unknown';
    const reg = p.region || 'unknown';
    byCategory[cat] = (byCategory[cat] || 0) + amt;
    bySponsor[sp] = (bySponsor[sp] || 0) + amt;
    byRegion[reg] = (byRegion[reg] || 0) + amt;
  }
  if (total === 0) return send(res, 200, { hasData: false });
  const issues = [];
  const recommendations = [];
  // Per-deal concentration
  const dealAmounts = investments.map(i => Number(i.amount || 0));
  const maxDeal = Math.max(...dealAmounts);
  const maxDealPct = (maxDeal / total) * 100;
  if (maxDealPct > 10) {
    issues.push({ severity: 'high', label: 'صفقة واحدة تشكّل ' + maxDealPct.toFixed(1) + '٪ من محفظتك' });
    recommendations.push('وزّع لتنزل إلى ٥–٧٪ لكلّ صفقة');
  }
  // Category concentration
  const maxCat = Object.entries(byCategory).reduce((a, b) => b[1] > a[1] ? b : a, ['', 0]);
  const maxCatPct = (maxCat[1] / total) * 100;
  if (maxCatPct > 30) {
    issues.push({ severity: 'medium', label: 'قطاع ' + maxCat[0] + ' يشكّل ' + maxCatPct.toFixed(1) + '٪' });
    recommendations.push('وزّع على قطاعات أخرى مثل الصحّة، الطاقة، أو الزراعة');
  }
  // Sponsor concentration
  const maxSp = Object.entries(bySponsor).reduce((a, b) => b[1] > a[1] ? b : a, ['', 0]);
  const maxSpPct = (maxSp[1] / total) * 100;
  if (maxSpPct > 20) {
    issues.push({ severity: 'high', label: 'راعٍ واحد يدير ' + maxSpPct.toFixed(1) + '٪ من محفظتك' });
    recommendations.push('وزّع على رعاة آخرين — استهدف ٧+ رعاة');
  }
  // Number of investments
  const dealCount = investments.length;
  if (dealCount < 10) {
    issues.push({ severity: 'medium', label: 'لديك ' + dealCount + ' صفقة فقط (الحدّ الأدنى الموصى به ١٥)' });
    recommendations.push('أضف ' + (15 - dealCount) + ' صفقات جديدة على الأقلّ');
  }
  // Region count
  const regionCount = Object.keys(byRegion).length;
  if (regionCount < 3) {
    issues.push({ severity: 'low', label: 'استثماراتك في ' + regionCount + ' منطقة فقط' });
    recommendations.push('استكشف صفقات في مناطق أخرى — الشرقيّة، عسير، تبوك');
  }
  // Overall score
  let score = 100;
  issues.forEach(i => { score -= (i.severity === 'high' ? 25 : (i.severity === 'medium' ? 15 : 5)); });
  score = Math.max(0, score);
  let grade = 'D';
  if (score >= 85) grade = 'A';
  else if (score >= 70) grade = 'B';
  else if (score >= 50) grade = 'C';
  return send(res, 200, {
    hasData: true,
    score,
    grade,
    dealCount,
    categoryCount: Object.keys(byCategory).length,
    sponsorCount: Object.keys(bySponsor).length,
    regionCount,
    maxDealPct: +maxDealPct.toFixed(1),
    maxCategoryPct: +maxCatPct.toFixed(1),
    maxSponsorPct: +maxSpPct.toFixed(1),
    issues,
    recommendations,
  });
});

