R('GET', '/app/me/impact-report', async (req, res) => {
  const auth = requireAuth(req, res); if (!auth) return;
  const investments = db.all('investments').filter(i => i.userId === auth.id && (i.status === 'confirmed' || i.status === 'funded' || i.status === 'active' || i.status === 'completed'));
  if (!investments.length) return send(res, 200, { hasData: false });
  const projectsById = new Map(db.all('projects').map(p => [p.id, p]));
  let myJobs = 0, myFamilies = 0, myCompanies = 0;
  let mySaudis = 0, myWomen = 0;
  const regionContribution = {};
  const sectorContribution = {};
  const sdgs = new Set();
  let totalInvested = 0;
  let esgInvested = 0;
  const esgCategories = new Set(['solar', 'water', 'agritech', 'green-buildings', 'clean-transport', 'circular', 'education', 'healthcare', 'renewables']);
  for (const inv of investments) {
    const p = projectsById.get(inv.projectId);
    if (!p) continue;
    const myAmount = Number(inv.amount || 0);
    totalInvested += myAmount;
    const dealAmount = Number(p.goalAmount || p.fundedAmount || 0);
    if (dealAmount < 1) continue;
    const myShare = myAmount / dealAmount;
    const totalJobs = Number(p.estimatedJobs) || Math.floor(dealAmount / 700000);
    myJobs += totalJobs * myShare;
    mySaudis += Math.floor(totalJobs * 0.68 * myShare);
    myWomen += Math.floor(totalJobs * 0.34 * myShare);
    myFamilies += totalJobs * 4 * myShare;
    myCompanies += myShare;
    const region = p.region || 'الرياض';
    regionContribution[region] = (regionContribution[region] || 0) + myAmount;
    sectorContribution[p.category || 'other'] = (sectorContribution[p.category || 'other'] || 0) + myAmount;
    if (esgCategories.has(p.category)) esgInvested += myAmount;
    if (p.category === 'solar' || p.category === 'renewables') { sdgs.add(7); sdgs.add(13); }
    if (p.category === 'water') { sdgs.add(6); sdgs.add(14); }
    if (p.category === 'agritech') { sdgs.add(2); sdgs.add(15); }
    if (p.category === 'green-buildings') sdgs.add(11);
    if (p.category === 'education') sdgs.add(4);
    if (p.category === 'healthcare') sdgs.add(3);
  }
  const topRegions = Object.entries(regionContribution).map(([k, v]) => ({ region: k, amount: +v.toFixed(0) })).sort((a, b) => b.amount - a.amount).slice(0, 5);
  const topSectors = Object.entries(sectorContribution).map(([k, v]) => ({ sector: k, amount: +v.toFixed(0) })).sort((a, b) => b.amount - a.amount).slice(0, 5);
  return send(res, 200, {
    hasData: true,
    totalInvested: +totalInvested.toFixed(0),
    myJobs: Math.round(myJobs * 10) / 10,
    mySaudis,
    myWomen,
    myFamilies: Math.round(myFamilies),
    myCompanies: Math.round(myCompanies * 10) / 10,
    esgInvested: +esgInvested.toFixed(0),
    esgPct: totalInvested > 0 ? Math.round((esgInvested / totalInvested) * 100) : 0,
    sdgsTouched: Array.from(sdgs).sort((a, b) => a - b),
    topRegions,
    topSectors,
  });
});

