R('GET', '/app/me/portfolio-stress-test', async (req, res) => {
  const auth = requireAuth(req, res); if (!auth) return;
  const investments = db.all('investments').filter(i => i.userId === auth.id && (i.status === 'confirmed' || i.status === 'active' || i.status === 'funded'));
  if (!investments.length) return send(res, 200, { hasData: false });
  const totalInvested = investments.reduce((s, i) => s + Number(i.amount || 0), 0);
  // Get category exposure
  const projectsById = new Map(db.all('projects').map(p => [p.id, p]));
  const byCategory = {};
  let realEstateExposure = 0, techExposure = 0, retailExposure = 0;
  for (const inv of investments) {
    const p = projectsById.get(inv.projectId);
    if (!p) continue;
    const cat = p.category || 'other';
    byCategory[cat] = (byCategory[cat] || 0) + Number(inv.amount || 0);
    if (cat === 'real-estate' || cat === 'real_estate') realEstateExposure += Number(inv.amount || 0);
    if (cat === 'tech' || cat === 'technology') techExposure += Number(inv.amount || 0);
    if (cat === 'retail') retailExposure += Number(inv.amount || 0);
  }
  // Stress scenarios
  const scenarios = [
    {
      key: 'recession',
      label: 'ركود اقتصادي (-١٥٪ سوق)',
      impact: -totalInvested * 0.12,
      affected: ['retail', 'tech'],
    },
    {
      key: 'real_estate_crash',
      label: 'انهيار العقار (-٢٠٪ سعر)',
      impact: -realEstateExposure * 0.20,
      affected: ['real_estate'],
    },
    {
      key: 'inflation_spike',
      label: 'تضخّم ٨٪ (تآكل ٤٪ صافي)',
      impact: -totalInvested * 0.04,
      affected: ['all'],
    },
    {
      key: 'profit_rate_hike',
      label: 'رفع معدّل الربح ٣٪',
      impact: -totalInvested * 0.05,
      affected: ['real_estate', 'industrial'],
    },
    {
      key: 'sponsor_default',
      label: 'تعثّر ٢٠٪ من الرعاة',
      impact: -totalInvested * 0.10,
      affected: ['all'],
    },
  ];
  const worstCase = scenarios.reduce((sum, s) => sum + s.impact, 0);
  const portfolioAfterWorst = totalInvested + worstCase;
  return send(res, 200, {
    hasData: true,
    totalInvested: +totalInvested.toFixed(0),
    scenarios: scenarios.map(s => ({ ...s, impact: +s.impact.toFixed(0), impactPct: +((s.impact / totalInvested) * 100).toFixed(1) })),
    worstCase: +worstCase.toFixed(0),
    worstCasePct: +((worstCase / totalInvested) * 100).toFixed(1),
    portfolioAfterWorst: +portfolioAfterWorst.toFixed(0),
    realEstateExposurePct: +((realEstateExposure / totalInvested) * 100).toFixed(1),
    diversificationScore: Object.keys(byCategory).length >= 5 ? 'A' : (Object.keys(byCategory).length >= 3 ? 'B' : (Object.keys(byCategory).length >= 2 ? 'C' : 'D')),
  });
});

