R('POST', '/app/me/risk-tolerance', async (req, res) => {
  const auth = requireAuth(req, res); if (!auth) return;
  const u = db.find('users', x => x.id === auth.id);
  if (!u) return err(res, 404, 'not_found');
  const body = await readJson(req).catch(() => ({}));
  const answers = body.answers || {};
  const keys = ['horizon', 'loss', 'income', 'experience', 'goal'];
  let score = 0;
  for (const k of keys) {
    const v = Number(answers[k]);
    if (!v || v < 1 || v > 4) return err(res, 400, 'invalid_answer:' + k);
    score += v;
  }
  let tier = 'conservative';
  if (score >= 17) tier = 'aggressive';
  else if (score >= 13) tier = 'growth';
  else if (score >= 9) tier = 'balanced';
  db.patch('users', u.id, {
    riskAnswers: answers,
    riskScore: score,
    riskTier: tier,
    riskTakenAt: now(),
  });
  try { audit(u.id, 'risk_tolerance_assessed', 'user:' + u.id, { score, tier }, req); } catch (e) {}
  return send(res, 200, { ok: true, score, tier });
});

