R('GET', '/app/me/goals-timeline', async (req, res) => {
  const auth = requireAuth(req, res); if (!auth) return;
  const u = db.find('users', x => x.id === auth.id);
  if (!u) return err(res, 404, 'not_found');
  const goals = Array.isArray(u.savingsGoals) ? u.savingsGoals.slice() : [];
  if (!goals.length) return send(res, 200, { hasData: false });
  const invs = db.filter('investments', i => i.userId === u.id && i.status !== 'canceled');
  const balance = Number(u.walletBalance || u.balance || 0);
  const totalAssets = invs.reduce((s, i) => s + Number(i.amount || 0), 0) + balance;
  const now = Date.now();
  const timeline = goals.map(g => {
    const target = Number(g.targetAmount || 0);
    const saved = Math.min(target, Number(g.savedAmount || 0));
    const pct = target > 0 ? Math.min(100, Math.round((saved / target) * 100)) : 0;
    let monthsToTarget = null;
    let etaAt = null;
    if (target > 0 && saved < target && totalAssets > 0) {
      // assume current portfolio grows at 8% blended; rough months to target
      const remaining = target - saved;
      const monthlyGrowth = (totalAssets * 0.08) / 12;
      if (monthlyGrowth > 0) {
        monthsToTarget = Math.ceil(remaining / monthlyGrowth);
        etaAt = new Date(now + monthsToTarget * 30 * 86400000).toISOString();
      }
    }
    return {
      id: g.id,
      name: g.name || 'هدف',
      icon: g.icon || '🎯',
      target,
      saved,
      pct,
      deadline: g.deadline || null,
      monthsToTarget,
      etaAt,
      onTrack: monthsToTarget !== null && g.deadline
        ? new Date(g.deadline).getTime() >= now + monthsToTarget * 30 * 86400000
        : null,
    };
  }).sort((a, b) => {
    if (a.deadline && b.deadline) return a.deadline.localeCompare(b.deadline);
    if (a.deadline) return -1;
    if (b.deadline) return 1;
    return b.pct - a.pct;
  });
  return send(res, 200, { hasData: true, timeline, portfolioValue: Math.round(totalAssets) });
});

