R('GET', '/app/me/category-limits', async (req, res) => {
  const auth = requireAuth(req, res); if (!auth) return;
  const u = db.find('users', x => x.id === auth.id);
  if (!u) return err(res, 404, 'not_found');
  const limits = u.categoryLimits || {};
  const invs = db.filter('investments', i => i.userId === u.id && i.status !== 'canceled' && i.status !== 'repaid');
  const projects = Object.fromEntries(db.all('projects').map(p => [p.id, p]));
  const totalsByCategory = {};
  for (const i of invs) {
    const p = projects[i.projectId];
    if (!p) continue;
    const cat = (p.category || p.sector || 'other').toString().toLowerCase();
    totalsByCategory[cat] = (totalsByCategory[cat] || 0) + Number(i.amount || 0);
  }
  const categories = [
    { key: 'real-estate', label: '🏢 العقارات' },
    { key: 'retail', label: '🛍 التجزئة' },
    { key: 'industrial', label: '🏭 الصناعة' },
    { key: 'agritech', label: '🌱 الزراعة' },
    { key: 'renewables', label: '☀️ الطاقة المتجدّدة' },
    { key: 'tech', label: '💻 التقنية' },
    { key: 'healthcare', label: '🏥 الصحّة' },
    { key: 'logistics', label: '📦 اللوجستيّات' },
    { key: 'tourism', label: '🏖 السياحة' },
    { key: 'education', label: '🎓 التعليم' },
  ];
  const list = categories.map(c => ({
    key: c.key,
    label: c.label,
    cap: Number(limits[c.key] || 0),
    invested: Math.round(totalsByCategory[c.key] || 0),
  }));
  return send(res, 200, { hasData: true, categories: list });
});

