R('GET', '/app/me/withdrawal-projection', async (req, res) => {
  const auth = requireAuth(req, res); if (!auth) return;
  const u = db.find('users', x => x.id === auth.id);
  if (!u) return err(res, 404, 'not_found');
  const balance = Number(u.walletBalance || u.balance || 0);
  const invs = db.filter('investments', i => i.userId === u.id && i.status !== 'canceled' && i.status !== 'repaid');
  if (!invs.length && balance < 1) return send(res, 200, { hasData: false });
  const projects = Object.fromEntries(db.all('projects').map(p => [p.id, p]));
  const now = Date.now();
  const periods = [
    { key: 'now', label: 'فوراً', maxDays: 0, available: balance, deals: 0 },
    { key: '3m', label: 'خلال ٣ أشهر', maxDays: 90, available: balance, deals: 0 },
    { key: '6m', label: 'خلال ٦ أشهر', maxDays: 180, available: balance, deals: 0 },
    { key: '1y', label: 'خلال سنة', maxDays: 365, available: balance, deals: 0 },
    { key: '2y', label: 'خلال سنتين', maxDays: 730, available: balance, deals: 0 },
  ];
  for (const inv of invs) {
    const p = projects[inv.projectId];
    if (!p) continue;
    const start = new Date(inv.createdAt || inv.investedAt).getTime();
    const duration = Number(p.durationMonths || 12);
    const matureAt = start + duration * 30 * 86400000;
    const daysToMature = Math.ceil((matureAt - now) / 86400000);
    const amt = Number(inv.amount || 0);
    for (const period of periods) {
      if (daysToMature <= period.maxDays) {
        period.available += amt;
        period.deals++;
      }
    }
  }
  return send(res, 200, {
    hasData: true,
    balance: Math.round(balance),
    periods: periods.map(p => ({ ...p, available: Math.round(p.available) })),
  });
});

