R('GET', '/app/me/personalized-insights', async (req, res) => {
  const auth = requireAuth(req, res); if (!auth) return;
  const u = db.find('users', x => x.id === auth.id);
  if (!u) return err(res, 404, 'not_found');
  const invs = db.filter('investments', i => i.userId === u.id && i.status !== 'canceled');
  const projects = Object.fromEntries(db.all('projects').map(p => [p.id, p]));
  const insights = [];
  // Insight: avg expected return
  if (invs.length >= 3) {
    let totalAmt = 0, weightedReturn = 0;
    for (const i of invs) {
      const p = projects[i.projectId];
      const amt = Number(i.amount || 0);
      totalAmt += amt;
      if (p) weightedReturn += amt * Number(p.expectedReturn || 0);
    }
    const blend = totalAmt > 0 ? +(weightedReturn / totalAmt).toFixed(1) : 0;
    insights.push({
      icon: '📈',
      title: 'متوسّط عائد محفظتك ' + blend + '٪',
      body: blend >= 10 ? 'محفظتك تستهدف عوائد جيّدة جدّاً.' : (blend >= 8 ? 'عوائد متوازنة بمخاطر معقولة.' : 'محفظتك محافظة. قد تستفيد من إضافة قطاعات أعلى عائداً.'),
    });
  }
  // Insight: diversity hint
  const cats = new Set();
  for (const i of invs) {
    const p = projects[i.projectId];
    if (p) cats.add((p.category || p.sector || 'other').toString().toLowerCase());
  }
  if (invs.length >= 3 && cats.size < 3) {
    insights.push({ icon: '🎨', title: 'تنويعك محدود (' + cats.size + ' قطاع)', body: 'حاول التوزيع على ٣ قطاعات على الأقل لتقليل المخاطر.' });
  }
  // Insight: consecutive activity
  if (invs.length === 0) {
    insights.push({ icon: '🚀', title: 'ابدأ رحلتك الاستثماريّة', body: 'لم تستثمر بعد. اطّلع على الصفقات المقترحة لك في هذه الصفحة.' });
  } else if (invs.length >= 5) {
    insights.push({ icon: '⭐', title: 'مستثمر نشط', body: invs.length + ' صفقة تظهر التزامك. حافظ على الانتظام.' });
  }
  // Insight: balance hint
  const balance = Number(u.walletBalance || u.balance || 0);
  if (balance > 5000) {
    insights.push({ icon: '💰', title: 'رصيدك المتاح ' + balance.toLocaleString('ar-SA') + ' ر.س', body: 'رصيد متاح يمكن توجيهه لصفقة جديدة بدل تركه عاطلاً.' });
  }
  // Insight: KYC nudge
  if (u.kycStatus !== 'approved') {
    insights.push({ icon: '🛡', title: 'أكمل KYC لإلغاء القيود', body: 'بدون KYC معتمد قد تكون بعض الصفقات غير متاحة لك.' });
  }
  // Insight: 2FA nudge
  if (!u.twofaEnabled) {
    insights.push({ icon: '🔐', title: 'فعّل المصادقة الثنائيّة', body: 'حماية إضافيّة في ٣ دقائق فقط.' });
  }
  if (!insights.length) {
    insights.push({ icon: '✨', title: 'حسابك في حالة ممتازة', body: 'استمرّ كما أنت.' });
  }
  return send(res, 200, { hasData: true, insights: insights.slice(0, 6) });
});

R('GET', '/app/me/trust-score', async (req, res) => {
  const auth = requireAuth(req, res); if (!auth) return;
  const u = db.find('users', x => x.id === auth.id);
  if (!u) return err(res, 404, 'not_found');
  const invs = db.filter('investments', i => i.userId === u.id && i.status !== 'canceled');
  const totalAmount = invs.reduce((s, i) => s + Number(i.amount || 0), 0);
  const components = [
    { key: 'kyc', label: 'اعتماد KYC', value: u.kycStatus === 'approved' ? 20 : 0, max: 20 },
    { key: 'twofa', label: 'تفعيل 2FA', value: u.twofaEnabled ? 15 : 0, max: 15 },
    { key: 'phone', label: 'تأكيد الجوّال', value: (u.phoneVerified || u.phoneVerifiedAt) ? 10 : 0, max: 10 },
    { key: 'email', label: 'تأكيد البريد', value: (u.emailVerified || u.emailVerifiedAt) ? 10 : 0, max: 10 },
    { key: 'profile', label: 'اكتمال البيانات', value: (u.firstName && u.lastName && u.birthDate) ? 10 : 0, max: 10 },
    { key: 'investing', label: 'سجلّ استثماري', value: Math.min(15, invs.length * 3), max: 15 },
    { key: 'commitment', label: 'حجم الاستثمار', value: Math.min(10, Math.floor(totalAmount / 10000)), max: 10 },
    { key: 'tenure', label: 'مدّة الحساب', value: u.createdAt ? Math.min(10, Math.floor((Date.now() - new Date(u.createdAt).getTime()) / (365.25 * 86400000)) * 2.5) : 0, max: 10 },
  ];
  const total = components.reduce((s, c) => s + c.value, 0);
  const maxTotal = components.reduce((s, c) => s + c.max, 0);
  const score = Math.round((total / maxTotal) * 100);
  let grade = 'F';
  if (score >= 90) grade = 'A+';
  else if (score >= 80) grade = 'A';
  else if (score >= 70) grade = 'B';
  else if (score >= 55) grade = 'C';
  else if (score >= 35) grade = 'D';
  return send(res, 200, { hasData: true, score, grade, components, total, maxTotal });
});

R('GET', '/app/me/smart-matches', async (req, res) => {
  const auth = requireAuth(req, res); if (!auth) return;
  const u = db.find('users', x => x.id === auth.id);
  if (!u) return err(res, 404, 'not_found');
  const prefs = u.preferredCategories || [];
  const alerts = u.investmentAlerts || {};
  const projects = db.all('projects').filter(p => {
    const status = (p.status || '').toLowerCase();
    return status !== 'funded' && status !== 'closed' && status !== 'repaid' && status !== 'defaulted';
  });
  const myInvs = new Set(db.filter('investments', i => i.userId === u.id && i.status !== 'canceled').map(i => i.projectId));
  const scored = projects.map(p => {
    if (myInvs.has(p.id)) return null;
    const cat = (p.category || p.sector || '').toString().toLowerCase();
    const ret = Number(p.expectedReturn || 0);
    const dur = Number(p.durationMonths || 0);
    let score = 0;
    const tags = [];
    if (prefs.includes(cat)) { score += 40; tags.push('💚 قطاع مفضّل'); }
    if (alerts.minReturnPct > 0 && ret >= alerts.minReturnPct) { score += 25; tags.push('📈 عائد يلبّي تفضيلك'); }
    if (alerts.maxDurationMonths > 0 && dur > 0 && dur <= alerts.maxDurationMonths) { score += 20; tags.push('⏱ مدّة تناسبك'); }
    if (Number(p.minTicket || p.minInvestment || 0) <= 2000) { score += 10; tags.push('💸 حدّ أدنى منخفض'); }
    if (score === 0) return null;
    return {
      id: p.id,
      slug: p.slug || p.id,
      title: p.title || p.name || '—',
      category: p.category || p.sector || '',
      expectedReturn: ret,
      durationMonths: dur,
      minTicket: Number(p.minTicket || p.minInvestment || 0),
      score,
      tags,
    };
  }).filter(Boolean).sort((a, b) => b.score - a.score).slice(0, 8);
  return send(res, 200, { hasData: scored.length > 0, matches: scored });
});

