R('GET', '/app/me/referral-rank', async (req, res) => {
  const auth = requireAuth(req, res); if (!auth) return;
  const users = db.all('users').filter(u => u.role !== 'admin' && !u.deletedAt);
  const refsByUser = {};
  for (const u of users) {
    const ref = u.referredBy || u.referrerId;
    if (ref) refsByUser[ref] = (refsByUser[ref] || 0) + 1;
  }
  const ranking = Object.entries(refsByUser).map(([uid, count]) => ({ uid, count })).sort((a, b) => b.count - a.count);
  const myRank = ranking.findIndex(r => r.uid === auth.id);
  const myCount = refsByUser[auth.id] || 0;
  const total = ranking.length;
  const top = ranking.slice(0, 5).map((r, idx) => {
    const u = users.find(x => x.id === r.uid);
    return {
      rank: idx + 1,
      displayName: u ? ((u.firstName || '') + ' ' + ((u.lastName || '').slice(0, 1) + '.')).trim() : 'مستخدم',
      count: r.count,
      isMe: r.uid === auth.id,
    };
  });
  return send(res, 200, {
    hasData: true,
    myRank: myRank === -1 ? null : myRank + 1,
    myCount,
    totalReferrers: total,
    top,
  });
});

