  if (!u.twofaSecret && !u.totpEnabledAt) actions.push({ key: 'twofa', label: '🔐 فعّل المصادقة الثنائية', urgency: 'medium', href: '/profile.html#twofa' });
  if (!(Array.isArray(u.backupCodes) && u.backupCodes.length > 0) && (u.twofaSecret || u.totpEnabledAt)) actions.push({ key: 'backup', label: '🛟 احفظ رموز الاسترداد', urgency: 'medium', href: '/profile.html#twofa' });
  if (!Array.isArray(u.bankAccounts) || !u.bankAccounts.some(b => b.verifiedAt)) actions.push({ key: 'bank', label: '🏦 أضف حسابك البنكي', urgency: 'medium', href: '/profile.html#bank' });
  const pendingContracts = db.filter('contracts', c => c.userId === u.id && c.status === 'pending').length;
  if (pendingContracts > 0) actions.push({ key: 'contracts', label: '📋 لديك ' + pendingContracts + ' عقد بانتظار التوقيع', urgency: 'high', href: '/portfolio.html' });
  const pendingDeposits = db.filter('transactions', t => t.userId === u.id && t.kind === 'deposit' && t.status === 'pending').length;
  if (pendingDeposits > 0) actions.push({ key: 'deposit', label: '💳 ' + pendingDeposits + ' إيداع قيد المعالجة', urgency: 'low', href: '/wallet.html' });
  const unread = db.filter('notifications', n => n.userId === u.id && !n.readAt && !n.archived).length;
