  const now = Date.now();
  const idExpiringIn30 = u.idExpiry && (new Date(u.idExpiry).getTime() - now) < 30 * 86400e3 && (new Date(u.idExpiry).getTime() - now) > 0;
  if (idExpiringIn30) actions.push({ key: 'idExp', label: '⏰ هويّتك تنتهي قريباً', urgency: 'high', href: '/kyc.html' });
