R('POST', '/app/me/trusted-devices', async (req, res) => {
  const auth = requireAuth(req, res); if (!auth) return;
  const body = await readJson(req);
  const label = (body?.label || '').toString().trim().slice(0, 40);
  const userAgent = (req.headers['user-agent'] || '').toString().slice(0, 200);
  if (!label) return err(res, 400, 'invalid_input');
  const u = db.find('users', x => x.id === auth.id);
  const trusted = Array.isArray(u.trustedDevices) ? u.trustedDevices : [];
  if (trusted.length >= 10) return err(res, 400, 'limit_reached');
  const fingerprint = require('crypto').createHash('sha256').update(userAgent + ':' + auth.id).digest('hex').slice(0, 16);
  if (trusted.find(d => d.id === fingerprint)) return err(res, 400, 'already_trusted');
  trusted.push({
    id: fingerprint,
    label,
    addedAt: new Date().toISOString(),
    lastUsedAt: new Date().toISOString(),
    userAgent,
  });
  await db.patch('users', x => x.id === auth.id, { trustedDevices: trusted });
  return send(res, 200, { ok: true, id: fingerprint });
});

