R('PUT', /^\/app\/admin\/projects\/([^/]+)\/faq$/, async (req, res, m) => {
  const admin = requireAdmin(req, res); if (!admin) return;
  const project = db.find('projects', p => p.id === m[1]);
  if (!project) return err(res, 404, 'not_found');
  const body = await readJson(req);
  const incoming = Array.isArray(body?.faq) ? body.faq : [];
  const clean = incoming
    .map(item => ({
      question: String(item?.question || '').trim().slice(0, 300),
      answer: String(item?.answer || '').trim().slice(0, 2000),
    }))
    .filter(item => item.question && item.answer)
    .slice(0, 30);
  await db.patch('projects', p => p.id === project.id, { faq: clean });
  await audit(admin.id, 'project.faq.update', project.id, { count: clean.length }, req);
  return send(res, 200, { faq: clean });
});

R('POST', /^\/app\/admin\/projects\/([^/]+)\/clone$/, async (req, res, m) => {
  const admin = requireAdmin(req, res); if (!admin) return;
  const original = db.find('projects', p => p.id === m[1]);
  if (!original) return err(res, 404, 'not_found');
  const stamp = new Date().toISOString().slice(0, 10);
  const copy = JSON.parse(JSON.stringify(original));
  const cleanName = (original.name || 'مشروع') + ' — نسخة ' + stamp;
  copy.id = S.newId('proj_');
  copy.name = cleanName;
  copy.slug = cleanName.toLowerCase().replace(/[^a-z0-9أ-ي\s-]/g, '').replace(/\s+/g, '-') + '-' + Math.floor(Math.random() * 9000 + 1000);
  copy.status = 'draft';
  copy.fundedAmount = 0;
  copy.raised = 0;
  copy.fundedPct = 0;
  copy.investorCount = 0;
  copy.shareCount = 0;
  copy.createdAt = now();
  copy.completedAt = null;
  copy.contractAt = null;
  copy.executionStartAt = null;
  copy.executionEndAt = null;
  copy.firstDistributionAt = null;
  copy.expectedCompletionAt = null;
  delete copy.fullyFundedAt;
  await db.insert('projects', copy);
  await audit(admin.id, 'project.clone', copy.id, { sourceId: original.id }, req);
  return send(res, 200, { project: copy });
});

R('POST', '/app/admin/projects', async (req, res) => {
  const admin = requireAdmin(req, res); if (!admin) return;
  const body = await readJson(req);
  if (!body) return err(res, 400, 'invalid_input');

  const id = body.id || '';
  const name = (body.name || '').trim();
  const category = (body.category || 'عقاري سكني').trim();
  const city = (body.city || 'الرياض').trim();
  const summary = (body.summary || '').trim();
  const description = (body.description || '').trim();
  const image = (body.image || '🏢').trim();
  const goal = Number(body.goal);
  const minAmount = Number(body.minAmount) || 1000;
  const totalProjectValue = Number(body.totalProjectValue) || goal;
  const opsCosts = Number(body.opsCosts) || 0;
  const otherCosts = Number(body.otherCosts) || 0;
  const minInvestors = Number(body.minInvestors) || 1;
  const maxInvestors = Number(body.maxInvestors) || 1000;
  const extendable = !!body.extendable;

  if (!name || !goal || goal <= 0) return err(res, 400, 'invalid_input');

  // ROI auto-calculation: profitRate = Net Profit / Total Project Value
  const netProfit = totalProjectValue - opsCosts - otherCosts;
  const profitRate = totalProjectValue > 0 ? (netProfit / totalProjectValue) : 0.08;

  const slug = name.toLowerCase().replace(/[^a-z0-9أ-ي\s-]/g, '').replace(/\s+/g, '-');

  await db.update(d => {
    let p = d.projects.find(x => x.id === id);
    if (p) {
      Object.assign(p, {
        name, category, city, summary, description, image, goal, minAmount,
        totalProjectValue, opsCosts, otherCosts, minInvestors, maxInvestors, extendable,
        profitRate, slug
      });
    } else {
      const newPrjId = id || S.newId('prj_');
      d.projects.push({
        id: newPrjId,
        slug,
        name,
        category,
        city,
        summary,
        description,
        image,
        goal,
        raised: 0,
        investorCount: 0,
        minAmount,
        profitRate,
        termMonths: Number(body.termMonths) || 12,
        status: 'open',
        openedAt: now(),
        closesAt: body.closesAt || now(),
        guarantee: body.guarantee || 'رهن عقاري + كفالة شركة',
        shariaApproval: body.shariaApproval || 'اعتماد الهيئة الشرعية',
        documents: [
          { "id": "doc_1", "name": "نموذج عقد المرابحة", "type": "pdf" },
          { "id": "doc_2", "name": "الفتوى الشرعية", "type": "pdf" }
        ],
        faq: [],
        totalProjectValue,
        opsCosts,
        otherCosts,
        minInvestors,
        maxInvestors,
        extendable,
        updates: [
          {
            "id": S.newId('upd_'),
            "date": now(),
            "title": "إطلاق الفرصة الاستثمارية",
            "body": `تم بحمد الله طرح فرصة تمويل مشروع "${name}" للعموم بعقد مرابحة شرعي.`
          }
        ]
      });
    }
  });

  return send(res, 200, { success: true });
});

R('POST', /^\/app\/admin\/projects\/([^/]+)\/updates$/, async (req, res, m) => {
  const admin = requireAdmin(req, res); if (!admin) return;
  const body = await readJson(req);
  if (!body) return err(res, 400, 'invalid_input');

  const title = (body.title || '').trim();
  const bodyText = (body.body || '').trim();
  if (!title || !bodyText) return err(res, 400, 'invalid_input');

  const prj = db.find('projects', x => x.id === m[1] || x.slug === m[1]);
  if (!prj) return err(res, 404, 'not_found');

  const newUpdate = {
    id: S.newId('upd_'),
    date: now(),
    title,
    body: bodyText
  };

  await db.update(d => {
    const p = d.projects.find(x => x.id === prj.id);
    if (!p.updates) p.updates = [];
    p.updates.push(newUpdate);

    // Investors (everyone who has an investment) + followers (anyone who hit the
    // follow button). Investors are usually a superset of "interested" users
    // but followers may include people who haven't invested yet but want to
    // hear when status changes.
    const investorIds = new Set(d.investments.filter(i => i.projectId === prj.id).map(i => i.userId));
    const followerIds = new Set(d.users.filter(u => Array.isArray(u.follows) && u.follows.includes(prj.id)).map(u => u.id));
    const recipientIds = new Set([...investorIds, ...followerIds]);
    for (const uid of recipientIds) {
      d.notifications.push({
        id: S.newId('ntf_'),
        userId: uid,
        kind: 'project_update',
        title: `تحديث جديد: ${title}`,
        body: `تحديث لمشروع ${p.name}: ${bodyText}`,
        meta: { projectId: p.id, updateId: newUpdate.id },
        read: false,
        createdAt: now(),
      });
    }
  });

  return send(res, 200, { success: true, update: newUpdate });
});

