R('POST', '/app/admin/settings/import', async (req, res) => {
  const admin = requireAdmin(req, res); if (!admin) return;
  const body = await readJson(req);
  if (!body || typeof body !== 'object') return err(res, 400, 'invalid_input');
  const importable = ['social', 'support', 'promo', 'welcomeEmail', 'flags', 'roadmapItems'];
  const applied = [];
  await db.update(d => {
    d.settings = d.settings || {};
    for (const k of importable) {
      if (k in body && body[k] !== null) {
        d.settings[k] = body[k];
        applied.push(k);
      }
    }
  });
  await audit(admin.id, 'admin.settings.import', 'settings', { keys: applied }, req);
  return send(res, 200, { ok: true, applied });
});

R('PATCH', '/app/admin/settings', async (req, res) => {
  const admin = requireAdmin(req, res); if (!admin) return;
  const body = await readJson(req);
  if (!body || typeof body !== 'object') return err(res, 400, 'invalid_input');
  await db.update(d => {
    d.settings = d.settings || {};
    if (body.social && typeof body.social === 'object') {
      d.settings.social = { ...(d.settings.social || {}), ...body.social };
    }
    if (body.support && typeof body.support === 'object') {
      d.settings.support = { ...(d.settings.support || {}), ...body.support };
    }
    if (body.welcomeEmail && typeof body.welcomeEmail === 'object') {
      d.settings.welcomeEmail = { ...(d.settings.welcomeEmail || {}), ...body.welcomeEmail };
    }
    if (body.promo && typeof body.promo === 'object') {
      const cur = d.settings.promo || {};
      d.settings.promo = { ...cur, ...body.promo };
      // Bumping version forces dismissed viewers to see it again
      if (body.promo.active && !cur.active) d.settings.promo.version = (cur.version || 0) + 1;
    }
    if (body.maintenance && typeof body.maintenance === 'object') {
      const prev = d.settings.maintenance || {};
      const next = { ...prev, ...body.maintenance };
      d.settings.maintenance = next;
      // Append to history on toggle transitions
      d.settings.maintenanceHistory = d.settings.maintenanceHistory || [];
      const becameActive = body.maintenance.active === true && !prev.active;
      const becameInactive = body.maintenance.active === false && prev.active;
      if (becameActive) {
        d.settings.maintenanceHistory.push({
          id: S.newId('mh_'),
          startedAt: now(),
          endedAt: null,
          message: next.message || null,
          eta: next.eta || null,
          by: 'admin',
        });
      }
      if (becameInactive) {
        const last = d.settings.maintenanceHistory[d.settings.maintenanceHistory.length - 1];
        if (last && !last.endedAt) last.endedAt = now();
      }
      // Cap history at 50 entries
      if (d.settings.maintenanceHistory.length > 50) {
        d.settings.maintenanceHistory = d.settings.maintenanceHistory.slice(-50);
      }
    }
  });
  await audit(admin.id, 'settings.update', 'settings', Object.keys(body), req);
  return send(res, 200, _settings());
});

// Public status snapshot for /status.html
R('GET', '/app/public/status', async (req, res) => {
  const s = _settings();
  const projects = db.all('projects');
  const investments = db.all('investments');
  const users = db.all('users');
  const recentInvCount = investments.filter(i => {
    const t = new Date(i.createdAt || 0).getTime();
    return Date.now() - t < 24 * 60 * 60 * 1000;
  }).length;
  const maint = s.maintenance || {};
  const components = [
    { id: 'api',       name: 'API الأساسي', status: 'operational' },
    { id: 'database',  name: 'قاعدة البيانات', status: 'operational' },
    { id: 'auth',      name: 'تسجيل الدخول', status: 'operational' },
    { id: 'payments',  name: 'بوابة الدفع', status: process.env.HYPERPAY_KEY ? 'operational' : 'degraded' },
    { id: 'email',     name: 'إشعارات البريد', status: process.env.RESEND_API_KEY ? 'operational' : 'degraded' },
    { id: 'sms',       name: 'الرسائل النصية', status: (process.env.UNIFONIC_API_KEY || process.env.TWILIO_SID) ? 'operational' : 'degraded' },
  ];
  if (maint.active) components.forEach(c => c.status = 'maintenance');
  const overall = components.every(c => c.status === 'operational') ? 'operational'
    : components.some(c => c.status === 'down') ? 'down'
    : components.some(c => c.status === 'maintenance') ? 'maintenance'
    : 'degraded';
  res.setHeader('Cache-Control', 'public, max-age=15');
  return send(res, 200, {
    overall,
    components,
    metrics: {
      projectsOpen: projects.filter(p => p.status === 'open').length,
      investmentsLast24h: recentInvCount,
      userCount: users.filter(u => !u.deletedAt).length,
    },
    serverTime: new Date().toISOString(),
  });
});

