R('PATCH', '/app/admin/flags', async (req, res) => {
  const admin = requireAdmin(req, res); if (!admin) return;
  const body = await readJson(req);
  if (!body || typeof body !== 'object') return err(res, 400, 'invalid_input');
  await db.update(d => {
    d.settings = d.settings || {};
    d.settings.flags = { ...(d.settings.flags || {}) };
    for (const [k, v] of Object.entries(body)) {
      const key = String(k).trim().toLowerCase().replace(/[^a-z0-9_]/g, '_').slice(0, 60);
      if (!key) continue;
      if (v === null || v === undefined) { delete d.settings.flags[key]; continue; }
      d.settings.flags[key] = !!v;
    }
  });
  await audit(admin.id, 'flags.update', 'flags', Object.keys(body), req);
  const s = _settings();
  return send(res, 200, { flags: s.flags || {} });
});

