// Public maintenance gate: anyone (incl. non-admin) checks current state.
R('GET', '/app/public/maintenance', async (req, res) => {
  const s = _settings();
  const m = s.maintenance || {};
  // Compute whether we're currently inside a scheduled window. The
  // explicit `active` flag still wins (admin can force immediately).
  const now = Date.now();
  let active = !!m.active;
  let scheduledNow = false;
  if (!active && m.scheduledStart && m.scheduledEnd) {
    const start = new Date(m.scheduledStart).getTime();
    const end = new Date(m.scheduledEnd).getTime();
    if (now >= start && now <= end) { active = true; scheduledNow = true; }
  }
  res.setHeader('Cache-Control', 'no-cache');
  return send(res, 200, {
    active,
    scheduledNow,
    message: m.message || 'النظام تحت الصيانة حالياً. سنعود قريباً.',
    eta: m.eta || m.scheduledEnd || null,
    scheduledStart: m.scheduledStart || null,
    scheduledEnd: m.scheduledEnd || null,
  });
});

