R('GET', '/app/admin/investment-status-breakdown', async (req, res) => {
  const admin = requireAdmin(req, res); if (!admin) return;
  const counts = { active: 0, pending_signature: 0, pending_payment: 0, completed: 0, canceled: 0, other: 0 };
  let totalAmount = 0;
  db.all('investments').forEach(inv => {
    const s = inv.status || 'other';
    if (counts[s] === undefined) counts.other++;
    else counts[s]++;
    if (inv.status !== 'canceled') totalAmount += Number(inv.amount || 0);
  });
  return send(res, 200, {
    total: Object.values(counts).reduce((a, b) => a + b, 0),
    totalAmount,
    counts,
  });
});

R('GET', '/app/admin/failed-login-series', async (req, res) => {
  const admin = requireAdmin(req, res); if (!admin) return;
  const params = new URL(req.url, 'http://x').searchParams;
  const days = Math.max(7, Math.min(60, parseInt(params.get('days') || '14', 10)));
  const cutoff = Date.now() - days * 24 * 60 * 60 * 1000;
  const dayKey = (iso) => (iso || '').slice(0, 10);
  const series = new Map();
  for (let i = days - 1; i >= 0; i--) {
    const k = new Date(Date.now() - i * 24 * 60 * 60 * 1000).toISOString().slice(0, 10);
    series.set(k, { day: k, count: 0 });
  }
  db.all('loginAttempts').forEach(a => {
    if (a.success) return;
    const t = new Date(a.createdAt).getTime();
    if (t < cutoff) return;
    const k = dayKey(a.createdAt);
    if (series.has(k)) series.get(k).count++;
  });
  return send(res, 200, { days, points: [...series.values()] });
});

R('GET', '/app/admin/investment-series', async (req, res) => {
  const admin = requireAdmin(req, res); if (!admin) return;
  const params = new URL(req.url, 'http://x').searchParams;
  const days = Math.max(7, Math.min(180, parseInt(params.get('days') || '30', 10)));
  const cutoff = Date.now() - days * 24 * 60 * 60 * 1000;
  const dayKey = (iso) => (iso || '').slice(0, 10);
  const series = new Map();
  for (let i = days - 1; i >= 0; i--) {
    const k = new Date(Date.now() - i * 24 * 60 * 60 * 1000).toISOString().slice(0, 10);
    series.set(k, { day: k, count: 0, amount: 0 });
  }
  db.all('investments').forEach(inv => {
    const t = new Date(inv.createdAt).getTime();
    if (t < cutoff) return;
    const k = dayKey(inv.createdAt);
    if (!series.has(k)) return;
    const cell = series.get(k);
    cell.count++;
    cell.amount += Number(inv.amount || 0);
  });
  return send(res, 200, { days, points: [...series.values()] });
});

const KNOWN_JOBS = ['daily_digest', 'backup_snapshot', 'notif_cleanup', 'magic_link_cleanup', 'erasure_executor', 'webhook_retry'];

R('POST', /^\/app\/admin\/jobs\/([^/]+)\/run$/, async (req, res, m) => {
  const admin = requireAdmin(req, res); if (!admin) return;
  const id = m[1];
  if (!KNOWN_JOBS.includes(id)) return err(res, 404, 'unknown_job');
  // Record manual run in settings.jobs.<id> so the UI reflects it.
  await db.update(d => {
    d.settings = d.settings || {};
    d.settings.jobs = d.settings.jobs || {};
    d.settings.jobs[id] = {
      ...(d.settings.jobs[id] || {}),
      lastRunAt: new Date().toISOString(),
      lastResult: 'manual_run_ok',
      lastRunBy: admin.id,
    };
  });
  await audit(admin.id, 'admin.job.run', id, { manual: true }, req);
  return send(res, 200, { ok: true, jobId: id });
});

R('GET', '/app/admin/jobs', async (req, res) => {
  const admin = requireAdmin(req, res); if (!admin) return;
  const s = _settings();
  const j = s.jobs || {};
  const fmt = (ts) => ts ? new Date(ts).toISOString() : null;
  const ago = (ts) => ts ? Math.round((Date.now() - new Date(ts).getTime()) / 60000) : null;
  // Scheduled jobs are declared here. Last-run timestamps are written by the
  // job runners into settings.jobs.<id>.lastRunAt / lastResult. If a job has
  // never been recorded, lastRunAt is null and the UI surfaces "—".
  const jobs = [
    { id: 'daily_digest',       title: 'الملخّص اليومي للإدارة', cadence: '08:00 يومياً', expectedFrequencyMin: 60 * 24 },
    { id: 'backup_snapshot',    title: 'نسخة احتياطية مضغوطة',   cadence: '03:00 يومياً', expectedFrequencyMin: 60 * 24 },
    { id: 'notif_cleanup',      title: 'تنظيف إشعارات قديمة',     cadence: '04:00 أسبوعياً', expectedFrequencyMin: 60 * 24 * 7 },
    { id: 'magic_link_cleanup', title: 'حذف روابط سحرية منتهية', cadence: 'كل ساعة', expectedFrequencyMin: 60 },
    { id: 'erasure_executor',   title: 'تنفيذ طلبات حذف الحساب',  cadence: '02:00 يومياً', expectedFrequencyMin: 60 * 24 },
    { id: 'webhook_retry',      title: 'إعادة محاولة Webhooks',   cadence: 'كل ١٥ دقيقة', expectedFrequencyMin: 15 },
  ];
  const out = jobs.map(spec => {
    const rec = j[spec.id] || {};
    const lateMin = ago(rec.lastRunAt);
    const overdue = lateMin == null ? null : lateMin > spec.expectedFrequencyMin * 1.5;
    return {
      ...spec,
      lastRunAt:    fmt(rec.lastRunAt),
      lastResult:   rec.lastResult || null,
      lastDuration: rec.lastDurationMs || null,
      ageMinutes:   lateMin,
      overdue:      overdue,
    };
  });
  return send(res, 200, { jobs: out, generatedAt: new Date().toISOString() });
});

R('GET', '/app/admin/failed-transactions', async (req, res) => {
  const admin = requireAdmin(req, res); if (!admin) return;
  const params = new URL(req.url, 'http://x').searchParams;
  const days = Math.max(1, Math.min(90, parseInt(params.get('days') || '14', 10)));
  const cutoff = Date.now() - days * 24 * 60 * 60 * 1000;
  const userIdx = Object.fromEntries(db.all('users').map(u => [u.id, u]));
  const rows = db.all('transactions')
    .filter(t => (t.status === 'failed' || t.status === 'declined') && new Date(t.createdAt).getTime() >= cutoff)
    .sort((a, b) => new Date(b.createdAt) - new Date(a.createdAt))
    .slice(0, 200)
    .map(t => ({
      id: t.id, kind: t.kind, amount: t.amount,
      status: t.status, failureReason: t.failureReason || null,
      description: t.description, methodLabel: t.methodLabel,
      userId: t.userId,
      userName: userIdx[t.userId]?.name || null,
      userEmail: userIdx[t.userId]?.email || null,
      createdAt: t.createdAt,
    }));
  // Aggregate by reason for quick triage
  const byReason = {};
  for (const r of rows) {
    const key = r.failureReason || 'unknown';
    byReason[key] = (byReason[key] || 0) + 1;
  }
  return send(res, 200, { transactions: rows, count: rows.length, byReason, days });
});

R('GET', '/app/admin/audit-log.csv', async (req, res) => {
  const admin = requireAdmin(req, res); if (!admin) return;
  const params = new URL(req.url, 'http://x').searchParams;
  const limit = Math.min(parseInt(params.get('limit') || '5000', 10), 50000);
  const q = (params.get('q') || '').trim().toLowerCase();
  const action = (params.get('action') || '').trim().toLowerCase();
  let actor = (params.get('actor') || '').trim();
  const actorEmail = (params.get('actorEmail') || '').trim().toLowerCase();
  if (!actor && actorEmail) {
    const u = db.all('users').find(x => (x.email || '').toLowerCase() === actorEmail);
    actor = u ? u.id : '__none__';
  }
  const from = params.get('from');
  const to = params.get('to');
  const fromT = from ? new Date(from).getTime() : 0;
  const toT = to ? new Date(to).getTime() + 86400000 : Infinity;
  const usrIdx = Object.fromEntries(db.all('users').map(u => [u.id, u.name]));
  let list = db.all('auditLog').filter(e => {
    const t = new Date(e.createdAt).getTime();
    if (t < fromT || t > toT) return false;
    if (action && !(e.action || '').toLowerCase().includes(action)) return false;
    if (actor && e.actorId !== actor) return false;
    if (q) {
      const hay = ((e.action || '') + ' ' + (e.target || '') + ' ' + JSON.stringify(e.meta || {}) + ' ' + (usrIdx[e.actorId] || '')).toLowerCase();
      if (!hay.includes(q)) return false;
    }
    return true;
  }).sort((a, b) => new Date(b.createdAt) - new Date(a.createdAt)).slice(0, limit);
  const rows = [['createdAt','actorId','actorName','action','target','ip','meta']];
  for (const e of list) {
    rows.push([
      e.createdAt || '',
      e.actorId || '',
      usrIdx[e.actorId] || 'system',
      e.action || '',
      e.target || '',
      e.ip || '',
      e.meta ? JSON.stringify(e.meta) : '',
    ]);
  }
  const csv = rows.map(r => r.map(v => {
    const s = String(v == null ? '' : v);
    return /[",\n]/.test(s) ? '"' + s.replace(/"/g, '""') + '"' : s;
  }).join(',')).join('\r\n');
  await audit(admin.id, 'admin.audit.export', 'csv', { count: list.length }, req);
  res.writeHead(200, {
    'Content-Type': 'text/csv; charset=utf-8',
    'Content-Disposition': 'attachment; filename="murbha-audit-log.csv"',
  });
  res.end('﻿' + csv);
});

R('GET', '/app/admin/audit-log', async (req, res) => {
  const admin = requireAdmin(req, res); if (!admin) return;
  const params = new URL(req.url, 'http://x').searchParams;
  const limit = Math.min(parseInt(params.get('limit') || '100', 10), 500);
  const q = (params.get('q') || '').trim().toLowerCase();
  const action = (params.get('action') || '').trim().toLowerCase();
  let actor = (params.get('actor') || '').trim();
  const actorEmail = (params.get('actorEmail') || '').trim().toLowerCase();
  if (!actor && actorEmail) {
    const u = db.all('users').find(x => (x.email || '').toLowerCase() === actorEmail);
    actor = u ? u.id : '__none__';
  }
  const from = params.get('from');
  const to = params.get('to');
  const fromT = from ? new Date(from).getTime() : 0;
  const toT = to ? new Date(to).getTime() + 86400000 : Infinity;

  const usrIdx = Object.fromEntries(db.all('users').map(u => [u.id, u.name]));
  let list = db.all('auditLog').filter(e => {
    const t = new Date(e.createdAt).getTime();
    if (t < fromT || t > toT) return false;
    if (action && !(e.action || '').toLowerCase().includes(action)) return false;
    if (actor && e.actorId !== actor) return false;
    if (q) {
      const hay = ((e.action || '') + ' ' + (e.target || '') + ' ' + JSON.stringify(e.meta || {}) + ' ' + (usrIdx[e.actorId] || '')).toLowerCase();
      if (!hay.includes(q)) return false;
    }
    return true;
  });
  const total = list.length;
  list = list
    .sort((a, b) => new Date(b.createdAt) - new Date(a.createdAt))
    .slice(0, limit);
  const enriched = list.map(e => ({ ...e, actorName: usrIdx[e.actorId] || 'system' }));
  return send(res, 200, { entries: enriched, total });
});

