// ─── Secondary Market Listings ───────────────────────────────────────────────

R('GET', '/app/secondary-market/listings', async (req, res) => {
  const user = requireAuth(req, res); if (!user) return;
  const projects = db.all('projects') || [];
  const investments = db.all('investments') || [];
  const listings = [];
  projects.forEach(proj => {
    if (!proj.secondaryMarketEnabled && proj.secondaryMarketEnabled !== undefined) return;
    const fundedAt = proj.fundedAt || proj.closingAt;
    if (!fundedAt) return;
    const minHold = Number(proj.minHoldDays || 90);
    const openTime = new Date(fundedAt).getTime() + minHold * 86400000;
    const isOpen = openTime <= Date.now();
    const daysLeft = proj.endDate ? Math.ceil((new Date(proj.endDate).getTime() - Date.now()) / 86400000) : null;
    const totalFunded = investments.filter(i => i.projectId === proj.id && i.status === 'active').reduce((s, i) => s + (i.amount || 0), 0);
    if (totalFunded < 500) return;
    listings.push({
      projectId: proj.id,
      projectName: proj.name || proj.title || proj.id,
      category: proj.category || 'other',
      yield: proj.yield || proj.expectedReturn || 0,
      daysLeft,
      shareSize: Math.min(10000, Math.round(totalFunded * 0.1)),
      askPrice: Math.min(10000, Math.round(totalFunded * 0.1)),
      feePct: Number(proj.secondaryFeePct || 1),
      open: isOpen,
    });
  });
  return send(res, 200, { listings: listings.slice(0, 20) });
});

// ─── Investor Scorecard ───────────────────────────────────────────────────────

R('GET', '/app/me/investor-scorecard', async (req, res) => {
  const user = requireAuth(req, res); if (!user) return;
  const investments = (db.all('investments') || []).filter(i => i.userId === user.id);
  const active = investments.filter(i => i.status === 'active');
  const projects = db.all('projects') || [];

  const cats = new Set(active.map(i => projects.find(p => p.id === i.projectId)?.category).filter(Boolean));
  const referrals = db.all('users').filter(u => u.referredBy === user.referralCode);
  const memberSinceMs = user.createdAt ? Date.now() - new Date(user.createdAt).getTime() : 0;
  const monthsOld = memberSinceMs / (30 * 86400000);

  const actScore = Math.min(100, investments.length * 15 + (user.lastLoginAt ? 10 : 0));
  const divScore = Math.min(100, cats.size * 25);
  const loyScore = Math.min(100, Math.round(monthsOld * 8) + (referrals.length > 0 ? 10 : 0));

  const badges = [];
  if (investments.length >= 1) badges.push('first_investment');
  if (investments.length >= 5) badges.push('five_deals');
  if (cats.size >= 3) badges.push('diversified');
  if (monthsOld >= 12) badges.push('year_one');
  if (referrals.length >= 1) badges.push('referrer');
  if (active.some(i => i.amount >= 10000)) badges.push('big_ticket');
  if (user.kycStatus === 'approved' || user.kycVerified) badges.push('full_kyc');

  const milestones = [];
  milestones.push('reg');
  if (user.kycStatus === 'approved' || user.kycVerified) milestones.push('kyc');
  if (investments.length >= 1) milestones.push('inv1');
  if (investments.length >= 5) milestones.push('inv5');
  if (cats.size >= 3) milestones.push('div3');
  if (referrals.length >= 1) milestones.push('ref1');

  const totalPoints = milestones.length * 100 + badges.length * 50;
  const level = totalPoints >= 800 ? 'مستثمر ذهبي' : totalPoints >= 400 ? 'مستثمر متقدّم' : totalPoints >= 200 ? 'مستثمر نشط' : 'مستثمر ناشئ';

  return send(res, 200, {
    fullName: user.fullName || user.name,
    memberSince: user.createdAt,
    level,
    totalPoints,
    scores: { activity: actScore, diversity: divScore, loyalty: loyScore },
    badges,
    milestones,
  });
});

// ─── Admin Deal Health Monitor ────────────────────────────────────────────────

R('GET', '/app/admin/deal-health', async (req, res) => {
  const admin = requireAdmin(req, res); if (!admin) return;
  const projects = db.all('projects') || [];
  const investments = db.all('investments') || [];
  const now = Date.now();

  const health = projects.filter(p => p.status === 'active' || p.status === 'funded').map(proj => {
    const invs = investments.filter(i => i.projectId === proj.id && i.status === 'active');
    const funded = invs.reduce((s, i) => s + (i.amount || 0), 0);
    const target = proj.amount || 1;
    const pct = Math.min(100, Math.round((funded / target) * 100));
    const daysLeft = proj.endDate ? Math.ceil((new Date(proj.endDate).getTime() - now) / 86400000) : null;
    const flags = [];
    if (pct < 30 && daysLeft !== null && daysLeft < 7) flags.push('low_funding_near_close');
    if (invs.length === 0) flags.push('no_investors');
    if (daysLeft !== null && daysLeft < 0) flags.push('overdue');
    return {
      id: proj.id,
      name: proj.name || proj.title || proj.id,
      category: proj.category || 'other',
      fundedPct: pct,
      investorCount: invs.length,
      daysLeft,
      flags,
      status: flags.length > 0 ? 'warning' : pct >= 100 ? 'funded' : 'healthy',
    };
  }).sort((a, b) => b.flags.length - a.flags.length || a.fundedPct - b.fundedPct);

  return send(res, 200, {
    deals: health,
    summary: {
      total: health.length,
      healthy: health.filter(h => h.status === 'healthy').length,
      warning: health.filter(h => h.status === 'warning').length,
      funded: health.filter(h => h.status === 'funded').length,
    },
  });
});

// ─── Sponsor Directory ───────────────────────────────────────────────────────

R('GET', '/app/public/sponsors', async (req, res) => {
  const projects = db.all('projects') || [];
  const investments = db.all('investments') || [];

  const sponsorMap = {};
  projects.forEach(proj => {
    const sid = proj.sponsorId || proj.sponsor;
    if (!sid) return;
    if (!sponsorMap[sid]) {
      sponsorMap[sid] = {
        id: sid,
        name: proj.sponsorName || sid,
        category: proj.category || 'other',
        categoryLabel: { real_estate:'عقارات', logistics:'لوجستيات', agri:'زراعة', tech:'تقنية', energy:'طاقة', retail:'تجزئة', other:'متنوّع' }[proj.category] || 'متنوّع',
        sharia: proj.sharia !== false,
        hasBcpDocument: proj.hasBcpDocument || false,
        rating: proj.sponsorRating || 4,
        deals: [],
      };
    }
    sponsorMap[sid].deals.push(proj);
  });

  const sponsors = Object.values(sponsorMap).map(sp => {
    const totalFunded = investments
      .filter(i => sp.deals.some(d => d.id === i.projectId) && i.status === 'active')
      .reduce((s, i) => s + (i.amount || 0), 0);
    const activeDealCount = sp.deals.filter(d => d.status === 'active' || d.status === 'open').length;
    const completedDeals = sp.deals.filter(d => d.status === 'completed').length;
    const successRate = sp.deals.length ? Math.round((completedDeals / sp.deals.length) * 100) : 100;
    return {
      id: sp.id,
      name: sp.name,
      category: sp.category,
      categoryLabel: sp.categoryLabel,
      sharia: sp.sharia,
      hasBcpDocument: sp.hasBcpDocument,
      rating: sp.rating,
      dealCount: sp.deals.length,
      activeDealCount,
      totalFunded,
      successRate,
    };
  }).sort((a, b) => b.dealCount - a.dealCount);

  return send(res, 200, { sponsors });
});

// ─── Tax Certificate ──────────────────────────────────────────────────────────

R('GET', '/app/me/tax-certificate/years', async (req, res) => {
  const user = requireAuth(req, res); if (!user) return;
  const investments = (db.all('investments') || []).filter(i => i.userId === user.id);
  const yearSet = new Set();
  investments.forEach(inv => {
    if (inv.createdAt) yearSet.add(new Date(inv.createdAt).getFullYear());
  });
  const years = Array.from(yearSet).sort((a, b) => b - a);
  return send(res, 200, { years });
});

R('GET', '/app/me/tax-certificate', async (req, res) => {
  const user = requireAuth(req, res); if (!user) return;
  const params = new URL('http://x' + req.url).searchParams;
  const year = parseInt(params.get('year') || new Date().getFullYear(), 10);
  if (!year || isNaN(year)) return err(res, 400, 'invalid_year');

  const investments = (db.all('investments') || [])
    .filter(i => i.userId === user.id && i.createdAt && new Date(i.createdAt).getFullYear() === year);
  const projects = db.all('projects') || [];
  const VAT_RATE = 0.15;

  const rows = investments.map(inv => {
    const proj = projects.find(p => p.id === inv.projectId);
    const yieldRate = parseFloat(inv.yield || proj?.yield || proj?.expectedReturn || 8) / 100;
    const income = Math.round(inv.amount * yieldRate * 100) / 100;
    const vat = Math.round(income * VAT_RATE * 100) / 100;
    return {
      projectName: proj?.name || proj?.title || inv.projectId,
      invested: inv.amount || 0,
      income,
      vat,
    };
  });

  return send(res, 200, {
    userId: user.id,
    investorName: user.fullName || user.name,
    year,
    rows,
    totals: {
      invested: rows.reduce((s, r) => s + r.invested, 0),
      income: rows.reduce((s, r) => s + r.income, 0),
      vat: rows.reduce((s, r) => s + r.vat, 0),
    },
  });
});

// ─── Admin Investor Cohort Report ─────────────────────────────────────────────

R('GET', '/app/admin/investor-cohort-report', async (req, res) => {
  const admin = requireAdmin(req, res); if (!admin) return;
  const users = db.all('users') || [];
  const investments = db.all('investments') || [];

  const cohorts = {};
  users.forEach(u => {
    if (!u.createdAt) return;
    const d = new Date(u.createdAt);
    const key = d.getFullYear() + '-' + String(d.getMonth() + 1).padStart(2, '0');
    if (!cohorts[key]) cohorts[key] = { month: key, users: 0, investors: 0, totalInvested: 0, retained: 0 };
    cohorts[key].users++;
    const userInvs = investments.filter(i => i.userId === u.id);
    if (userInvs.length > 0) {
      cohorts[key].investors++;
      cohorts[key].totalInvested += userInvs.reduce((s, i) => s + (i.amount || 0), 0);
    }
    const recentActivity = userInvs.some(i => i.createdAt && Date.now() - new Date(i.createdAt).getTime() < 90 * 86400000);
    if (recentActivity) cohorts[key].retained++;
  });

  const rows = Object.values(cohorts)
    .sort((a, b) => b.month.localeCompare(a.month))
    .slice(0, 24)
    .map(c => ({
      ...c,
      conversionRate: c.users ? Math.round((c.investors / c.users) * 100) : 0,
      avgInvestment: c.investors ? Math.round(c.totalInvested / c.investors) : 0,
      retentionRate: c.investors ? Math.round((c.retained / c.investors) * 100) : 0,
    }));

  return send(res, 200, { cohorts: rows });
});

