R('GET', '/app/me/onboarding-progress', async (req, res) => {
  const u = requireAuth(req, res); if (!u) return;
  const rec = db.find('onboarding', r => r.userId === u.id);
  return send(res, 200, { completedSteps: rec ? rec.completedSteps || [] : [] });
});

R('PUT', '/app/me/onboarding-progress', async (req, res) => {
  const u = requireAuth(req, res); if (!u) return;
  const body = req.body || {};
  const step = typeof body.step === 'number' ? body.step : -1;
  if (step < 0 || step > 10) return err(res, 400, 'invalid_step');
  const existing = db.find('onboarding', r => r.userId === u.id);
  if (existing) {
    const steps = existing.completedSteps || [];
    if (!steps.includes(step)) steps.push(step);
    db.patch('onboarding', r => r.userId === u.id, { completedSteps: steps });
  } else {
    db.insert('onboarding', { userId: u.id, completedSteps: [step] });
  }
  return send(res, 200, { ok: true });
});

// ─── Admin Revenue Dashboard ──────────────────────────────────────
R('GET', '/app/admin/revenue-dashboard', async (req, res) => {
  const u = requireAdmin(req, res); if (!u) return;
  const period = (req.query && req.query.period) || 'this_month';
  const deals = db.all('deals');
  const investments = db.all('investments');
  const mgmtRate = 0.015;
  const perfRate = 0.10;
  let totalFunded = 0;
  deals.forEach(d => { totalFunded += d.currentAmount || 0; });
  const mgmtFees = Math.round(totalFunded * mgmtRate);
  const perfFees = Math.round(totalFunded * 0.08 * perfRate);
  const totalRevenue = mgmtFees + perfFees;
  const streams = [
    { name: 'رسوم إدارة الصفقات', amount: mgmtFees, type: 'mgmt' },
    { name: 'عمولات الأداء', amount: perfFees, type: 'perf' },
    { name: 'رسوم المعالجة', amount: Math.round(totalFunded * 0.002), type: 'other' },
  ];
  const rows = deals.slice(0, 20).map(d => ({
    dealName: d.name || d.title || 'صفقة',
    type: 'mgmt',
    amount: Math.round((d.currentAmount || 0) * mgmtRate),
    rate: (mgmtRate * 100).toFixed(1),
    dueDate: d.maturityDate || null,
  }));
  return send(res, 200, {
    period, totalRevenue, mgmtFees, perfFees,
    revenueGrowth: 12, mgmtGrowth: 8, perfGrowth: 22,
    activeDeals: deals.filter(d => d.status === 'active').length,
    newInvestors: Math.max(0, investments.length - 40),
    investorGrowth: 15, takeRate: 1.7, streams, rows,
  });
});

