R('GET', '/app/me/documents', async (req, res) => {
  const u = requireAuth(req, res); if (!u) return;
  const userInvs = db.all('investments').filter(i => i.userId === u.id);
  const deals = db.all('deals');
  const dealMap = {};
  deals.forEach(d => { dealMap[d.id] = d.name || d.title || 'صفقة'; });
  const documents = [];
  userInvs.forEach(inv => {
    const dealName = dealMap[inv.dealId] || 'صفقة';
    documents.push({ id: 'contract-' + inv.id, name: 'عقد المرابحة — ' + dealName, type: 'contract', dealName, date: inv.createdAt || null });
    documents.push({ id: 'sharia-' + inv.dealId, name: 'شهادة الهيئة الشرعية — ' + dealName, type: 'sharia', dealName, date: inv.createdAt || null });
    if (inv.status === 'completed') {
      documents.push({ id: 'report-' + inv.id, name: 'تقرير الإغلاق — ' + dealName, type: 'report', dealName, date: inv.updatedAt || null });
    }
  });
  const months = new Set(
    db.all('payouts').filter(p => p.userId === u.id).map(p => (p.paidAt || '').slice(0, 7)).filter(Boolean)
  );
  months.forEach(m => {
    documents.push({ id: 'stmt-' + m + '-' + u.id, name: 'كشف حساب — ' + m, type: 'statement', dealName: null, date: m + '-01' });
  });
  documents.sort((a, b) => (b.date || '').localeCompare(a.date || ''));
  return send(res, 200, { documents });
});

