R('POST', /^\/app\/deals\/([^/]+)\/qa\/([^/]+)\/upvote$/, async (req, res, m) => {
  const u = requireAuth(req, res); if (!u) return;
  const [, dealId, questionId] = m;
  const already = db.find('deal_qa_votes', v => v.userId === u.id && v.questionId === questionId);
  if(already) return err(res, 409, 'already_voted');
  db.insert('deal_qa_votes', { userId: u.id, dealId, questionId });
  const q = db.find('deal_qa', x => x.id === questionId);
  if(q) db.patch('deal_qa', x => x.id === questionId, { upvotes: (q.upvotes || 0) + 1 });
  return send(res, 200, { ok: true });
});

